window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch11"]={"id":"ch11","title":"第六章(二) 细胞信号转导","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"信号通路 · 网络 · 受体","modules":[{"i":0,"name":"4.1.2 G-蛋白偶联受体","slides":[{"i":0,"sec":"4.1.2 G-蛋白偶联受体","title":"4.1.2 G-蛋白偶联受体","notes":"效应器（二）腺苷酸环化酶→cAMP-PKA 信号通路\n细胞外信号与相应的G蛋白偶联\n受体结合，导致细胞内第二信使\ncAMP的水平变化而引起细胞反\n应的信号通路。\n大多数哺乳动物细胞应答激素反应的\n主要机制之一。\n磷酸二酯酶\n【结合课本/笔记】cAMP信号通路●反应链：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP依赖的蛋白激酶A→基因调控蛋白→基因转录●组分及其分析G-蛋白偶联受体G-蛋白活化与调节效应酶——腺苷酸环化酶●GPLR的失敏（desensitization）与减量调节●细菌毒素对G蛋白的修饰作用","page":1,"level":"掌握","img":"assets/img/ch11/p001.jpg","anim":null,"fig":null,"points":["效应器(二)：腺苷酸环化酶→cAMP-PKA信号通路","胞外信号与G蛋白偶联受体结合，使胞内第二信使cAMP水平变化而引起细胞反应","是大多数哺乳动物细胞应答激素反应的主要机制之一，cAMP由磷酸二酯酶降解"],"check":{"q":"以腺苷酸环化酶为效应器的cAMP-PKA信号通路，其反应链是？","o":["A. 激素→受体酪氨酸激酶→Ras→cAMP→PKA","B. 激素→受体→磷脂酶C→IP3→Ca2+","C. 激素→G蛋白偶联受体→G蛋白→腺苷酸环化酶→cAMP→PKA→基因调控蛋白","D. 激素→受体→鸟苷酸环化酶→cGMP→PKG"],"a":"C","e":"cAMP-PKA通路反应链为激素→GPCR→G蛋白→腺苷酸环化酶→cAMP→PKA→基因调控蛋白→基因转录。","oe":["Ras通路属RTK通路，效应器非腺苷酸环化酶。","该链为肌醇磷脂(PLC-IP3-Ca2+)通路。","该反应链正确描述了cAMP-PKA通路。","该链为NO-cGMP-PKG通路。"]},"cards":null,"mem":"cAMP通路：激素→GPCR→G→AC→cAMP→PKA","big":"assets/img/ch11/big/p001.jpg","terms":[{"t":"失敏","en":"desensitization","d":"受体受到持续刺激后反应性下降的现象，如受体被磷酸化或内化。"}]},{"i":1,"sec":"4.1.2 G-蛋白偶联受体","title":"cAMP -PKA 信号通路","notes":"信号分子与G蛋白偶联受体结合\n受体构象改变，G蛋白活化-GTP\n活化腺苷酸环化酶，产生cAMP\n活化蛋白激酶A(PKA)\n一些特定的蛋白磷酸化     如：动物肝脏、肌肉应答肾上腺\n素、胰高血糖素，分解糖原，生成\n引起一系列生物学反应     葡萄糖。-肝脏和肌肉是人体调节糖\n原代谢、血糖浓度的主要组织。\n【结合课本/笔记】cAMP信号通路●反应链：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP依赖的蛋白激酶A→基因调控蛋白→基因转录●组分及其分析G-蛋白偶联受体G-蛋白活化与调节效应酶——腺苷酸环化酶●GPLR的失敏（desensitization）与减量调节●细菌毒素对G蛋白的修饰作用","page":2,"level":"掌握","img":"assets/img/ch11/p002.jpg","anim":null,"fig":null,"points":["信号分子与GPCR结合→G蛋白活化→腺苷酸环化酶产生cAMP→活化蛋白激酶A(PKA)→特定蛋白磷酸化","如肝脏、肌肉应答肾上腺素、胰高血糖素，分解糖原生成葡萄糖"],"check":{"q":"肝脏、肌肉细胞应答肾上腺素、胰高血糖素时，cAMP-PKA通路的作用是？","o":["A. 经腺苷酸环化酶产生cAMP，激活PKA使特定蛋白磷酸化，分解糖原生成葡萄糖","B. 直接分解糖原，无需PKA参与","C. 抑制腺苷酸环化酶，减少cAMP生成","D. 使cAMP直接进入细胞核调控基因转录"],"a":"A","e":"该通路反应链为：激素→G蛋白偶联受体→G蛋白→腺苷酸环化酶→cAMP→PKA→特定蛋白磷酸化，从而分解糖原生成葡萄糖。","oe":["该通路经cAMP激活PKA并磷酸化蛋白分解糖原，正确。","糖原分解依赖PKA活化，不能绕过。","该通路活化而非抑制腺苷酸环化酶。","进入核内调控基因的是PKA作用的下游，cAMP不直接进入核。"],"basis":"cAMP激活PKA，磷酸化蛋白分解糖原生成葡萄糖"},"cards":null,"mem":"cAMP-PKA：激素→GPCR→AC→cAMP→PKA","big":"assets/img/ch11/big/p002.jpg"},{"i":2,"sec":"4.1.2 G-蛋白偶联受体","title":"cAMP通过激活蛋白激酶A(PKA)起作用","notes":"在多细胞动物各种以cAMP为第二信使的信号通路中，主要是通过激活蛋白激酶A(protein kinase A, PKA)来起作用。cAMP特异结合到PKA的调节亚基上，使调节亚基与催化亚基分离，释放出PKA的催化亚基，从而激活PKA。","page":3,"level":"掌握","img":"assets/img/ch11/p003.jpg","anim":null,"fig":null,"points":["cAMP特异结合到蛋白激酶A(PKA)的调节亚基上","结合后释放出PKA的催化亚基"],"check":{"q":"在多细胞动物以cAMP为第二信使的信号通路中，PKA的激活方式是？","o":["A. cAMP结合PKA的催化亚基使其磷酸化","B. cAMP结合PKA的调节亚基，释放催化亚基","C. cAMP使PKA的调节亚基磷酸化后激活","D. cAMP促进PKA基因转录出更多PKA"],"a":"B","e":"cAMP特异结合PKA调节亚基，使催化亚基释放而激活。","oe":["cAMP结合的是调节亚基，并非直接结合催化亚基。","正确，cAMP结合调节亚基，释放催化亚基而激活。","磷酸化并非cAMP激活PKA的方式。","cAMP作用于已存在的PKA蛋白，不调控基因转录。"],"basis":"cAMP特异结合到蛋白激酶A的调节亚基上，释放催化亚基。"},"cards":null,"mem":"cAMP结合PKA调节亚基，释放催化亚基而激活","big":"assets/img/ch11/big/p003.jpg"},{"i":3,"sec":"4.1.2 G-蛋白偶联受体","title":"PKA的功能：胞质代谢调节与细胞核基因表达","notes":"蛋白激酶A(PKA)具有两方面的功能：①胞质功能——促进肝脏/肌细胞糖原分解，属短期快速应答；动物体内葡萄糖以不溶的糖原形式储存，糖原分解受胰高血糖素和肾上腺素控制。②细胞核功能——调节基因表达。","page":4,"level":"掌握","img":"assets/img/ch11/p004.jpg","anim":null,"fig":null,"points":["PKA的胞质功能：肝脏/肌细胞糖原分解(短期快速应答)","PKA的细胞核功能：调节基因表达","动物体内葡萄糖以不溶的糖原形式储存，糖原分解受胰高血糖素和肾上腺素控制"],"check":{"q":"蛋白激酶A(PKA)的细胞核功能是？","o":["A. 水解ATP生成cAMP","B. 合成cAMP","C. 分解糖原","D. 调节基因表达"],"a":"D","e":"PKA在胞质中参与糖原分解等快速应答，在细胞核中则通过磷酸化调节基因表达。","oe":["水解ATP生成cAMP的是腺苷酸环化酶。","PKA不合成cAMP，cAMP由腺苷酸环化酶生成。","糖原分解属于PKA在胞质中的功能，而非核功能。","PKA入核可调节基因表达，正确。"]},"cards":null,"mem":"PKA双功能：胞质促糖原分解，入核调基因表达","big":"assets/img/ch11/big/p004.jpg"},{"i":4,"sec":"4.1.2 G-蛋白偶联受体","title":"● 肾上腺细胞：肾上腺素","notes":"肝脏细胞表面G-蛋白偶联受体\n→ G－蛋白-GTP\n激活腺苷酸环化酶(adenylyl cylase)\nATP→cAMP\n蛋白激酶A（PKA）\n→肝细胞细胞质中\n➢ 磷酸化&激活糖原磷酸化酶激酶(glycogen phosphorylase\nkinase, GPK)，催化GP磷酸化后激活，促进糖原分解；\n➢ 磷酸化&抑制糖原合成酶(GS)，抑制糖原合成。\n血糖浓度升高","page":5,"level":"掌握","img":"assets/img/ch11/p005.jpg","anim":null,"fig":null,"points":["肾上腺素→肝细胞表面GPCR→G蛋白-GTP→腺苷酸环化酶→ATP→cAMP→PKA","PKA磷酸化并激活糖原磷酸化酶激酶(GPK)，促进糖原分解","PKA磷酸化并抑制糖原合成酶(GS)，抑制糖原合成，血糖浓度升高"],"check":{"q":"肾上腺素使肝细胞血糖升高时，PKA对糖原代谢的调节是？","o":["A. 激活糖原磷酸化酶激酶，抑制糖原合成酶","B. 同时激活糖原磷酸化酶激酶和糖原合成酶","C. 对两者均无影响","D. 抑制糖原磷酸化酶激酶，激活糖原合成酶"],"a":"A","e":"PKA磷酸化激活糖原磷酸化酶激酶(GPK)促进糖原分解，同时磷酸化抑制糖原合成酶(GS)抑制糖原合成。","oe":["PKA激活GPK、抑制GS，使血糖升高，正确。","PKA抑制而非激活糖原合成酶，减少糖原合成。","PKA显著调节这两个酶的活性。","方向相反，PKA促进分解、抑制合成。"]},"cards":null,"mem":"肾上腺素→PKA：激活GPK分解糖原、抑制GS合成","big":"assets/img/ch11/big/p005.jpg"},{"i":5,"sec":"4.1.2 G-蛋白偶联受体","title":"肾上腺素刺激骨骼肌细","notes":"胞中的糖原分解\nGPK        糖原磷酸化酶激酶被激活\nGP   糖原磷酸化酶\n糖原分解\n\n【读图讲解】\n该图展示肾上腺素刺激骨骼肌细胞中糖原分解的信号级联。肾上腺素(adrenaline)结合活化的GPCR(肾上腺素能受体)，激活G蛋白α亚基(Gs)，进而激活腺苷酸环化酶(adenylyl cyclase)，把ATP转变为cAMP。cAMP结合并激活PKA；活化的PKA使糖原磷酸化酶激酶(GPK)磷酸化激活，后者再磷酸化激活糖原磷酸化酶(GP)，最终催化糖原分解(glycogen breakdown)。要点：G蛋白—cAMP—PKA逐级放大，一个激素分子可引发大量糖原分解，是信号转导级联放大的典型。","page":6,"level":"掌握","img":"assets/img/ch11/p006.jpg","anim":null,"fig":null,"points":["肾上腺素刺激骨骼肌细胞中的糖原分解","糖原磷酸化酶激酶(GPK)被激活，进而激活糖原磷酸化酶(GP)，促使糖原分解"],"check":{"q":"在肾上腺素刺激骨骼肌糖原分解的级联中，被PKA磷酸化激活的是？","o":["A. 糖原磷酸化酶激酶(GPK)","B. 糖原合成酶","C. Gs蛋白α亚基","D. 腺苷酸环化酶"],"a":"A","e":"PKA活化后使GPK磷酸化激活，GPK再激活GP，最终催化糖原分解。","oe":["正确，PKA使GPK磷酸化激活。","该级联讲糖原分解，不涉及糖原合成酶激活。","Gs蛋白激活腺苷酸环化酶，位于PKA上游。","腺苷酸环化酶位于PKA上游，催化生成cAMP。"],"basis":"活化的PKA使糖原磷酸化酶激酶(GPK)磷酸化激活。"},"cards":null,"mem":"AD→cAMP→PKA→GPK→GP，级联放大促糖原分解","big":"assets/img/ch11/big/p006.jpg"},{"i":6,"sec":"4.1.2 G-蛋白偶联受体","title":"糖原磷酸化酶激酶","notes":"糖原合成酶\n糖原磷酸化酶\n\n【读图讲解】\n该图总结cAMP升高时活化PKA对糖原代谢的双向调控。向右“促进糖原降解”：活化的PKA磷酸化激活糖原磷酸化酶激酶(GPK→GPK-Pi)，再激活糖原磷酸化酶(GP→GP-Pi)，催化糖原加Pi生成G-1-P。向右“抑制糖原合成”：PKA抑制磷蛋白磷酸酶(IP→IP-Pi)，使活化的PP变为失活状态，同时使糖原合成酶(GS→GS-Pi)失活。要点：PKA通过磷酸化同时促进分解、抑制合成，实现代谢的协同调节；Pi代表磷酸基团。","page":7,"level":"掌握","img":"assets/img/ch11/p007.jpg","anim":null,"fig":null,"points":["糖原代谢涉及糖原磷酸化酶激酶、糖原合成酶与糖原磷酸化酶"],"check":{"q":"cAMP升高激活PKA后，对糖原代谢的双向调节表现为？","o":["A. 促进糖原降解，同时抑制糖原合成","B. 抑制糖原降解，同时促进糖原合成","C. 既促进糖原降解，又促进糖原合成","D. 对糖原降解和合成均无作用"],"a":"A","e":"PKA磷酸化激活GPK/GP促进糖原降解，同时使糖原合成酶失活抑制糖原合成，实现协同调节。","oe":["促进分解、抑制合成，表述正确。","PKA促进而非抑制糖原降解，使血糖升高。","PKA抑制而非促进糖原合成，二者协同调节。","PKA是糖原代谢的关键调节者。"]},"cards":null,"mem":"PKA双向调控：磷酸化激活GP促降解，抑制GS阻合成","big":"assets/img/ch11/big/p007.jpg"},{"i":7,"sec":"4.1.2 G-蛋白偶联受体","title":"● 细胞核功能：调节基因表达","notes":"Kinase A\n激活的胞质溶胶中的蛋白激酶A，2个\n催化亚基随后可转移入细胞核，\nkinase A磷酸化转录因子CREB\n(cAMP response element-binding\nprotein)→作用于DNA的特定核苷酸序\n列位点(CRE，cAMP response\nelement)，\n增强相应基因的转录起始速率。如与\n糖异生有关的酶，其编码基因均含有\nCRE序列。\n利用小分子前体合成葡萄糖","page":8,"level":"掌握","img":"assets/img/ch11/p008.jpg","anim":null,"fig":null,"points":["PKA的2个催化亚基随后转移入细胞核，磷酸化转录因子CREB","CREB作用于DNA特定核苷酸序列位点(CRE)，增强相应基因的转录起始速率","如与糖异生有关的酶，其编码基因均含有CRE序列"],"check":{"q":"PKA入核后调节基因表达的途径是？","o":["A. 磷酸化转录因子CREB，作用于DNA的CRE序列增强转录","B. 直接与DNA的启动子结合启动转录","C. 使RNA聚合酶磷酸化后失活","D. 降解CREB从而抑制转录"],"a":"A","e":"PKA催化亚基入核磷酸化转录因子CREB，CREB作用于DNA的CRE序列，增强相应基因的转录起始速率。","oe":["PKA磷酸化CREB并经CRE增强转录，正确。","PKA不直接结合DNA，需通过CREB。","它增强转录，而非使RNA聚合酶失活。","PKA激活而非降解CREB，从而启动靶基因转录。"]},"cards":null,"mem":"PKA入核磷酸化CREB→结合CRE→增强基因转录","big":"assets/img/ch11/big/p008.jpg"},{"i":8,"sec":"4.1.2 G-蛋白偶联受体","title":"激素/神经递质经cAMP-PKA-CREB调节基因表达","notes":"激素和神经递质与G蛋白偶联受体结合→激活腺苷酸环化酶→产生cAMP→激活胞质中的PKA→PKA随后转移入细胞核，磷酸化转录因子CREB→激活一整套靶基因的转录。","page":9,"level":"掌握","img":"assets/img/ch11/p009.jpg","anim":null,"fig":null,"points":["激素和神经递质与GPCR结合→腺苷酸环化酶→cAMP→激活胞质中的PKA","PKA随后转移入细胞核，磷酸化转录因子CREB，激活一整套靶基因的转录"],"check":{"q":"激素/神经递质经GPCR-cAMP-PKA通路调节基因表达时，被磷酸化的转录因子是？","o":["A. GPK","B. CREB","C. Ras","D. Piezo2"],"a":"B","e":"PKA入核磷酸化转录因子CREB，从而激活一整套靶基因的转录。","oe":["GPK是糖原磷酸化酶激酶，属胞质代谢酶。","CREB是被PKA磷酸化的转录因子，正确。","Ras是单体G蛋白，不是转录因子。","Piezo2是机械门控离子通道。"]},"cards":null,"mem":"激素→GPCR→cAMP→PKA入核→CREB→基因转录","big":"assets/img/ch11/big/p009.jpg"}],"mcq":[{"id":"ch11_mcq_3","mod":"4.1.2 G-蛋白偶联受体","modI":0,"q":"在 cAMP 信号中，G 蛋白的偶联作用表现为（            ）。","o":["A．受体的活化导致 G 蛋白的α、β、γ三个亚单位的偶联","B．受体的活化通过 G 蛋白与 MAPK 激酶级联反应通路偶联","C．受体的活化通过 G 蛋白与 PKA(cAMP-dependent protein kinase A)的活化偶联 n 受体的活 化通过 G 蛋白与 AC(adenyl cyclase)的活化偶联","D．受体的活化通过 G 蛋白与 cAMP 偶联"],"a":"D","e":"在 cAMP 信号通路中，三聚体 G 蛋白由α、β、γ三个亚单位组成，受体的活化导致 与 G 蛋白α亚单位相结合的 GDP 被 GTP 交换，而β、γ二聚体共价结合锚于内膜。在 cAMP 信号通路中，处于活化状态的三聚体 G 蛋白亚单位α—GTP 作用于 AC。活化的 AC 使 ATP 环化，生成 cAMP。","kp":"ch11_s0_0","oe":["受体活化使G蛋白α亚基结合GTP并与βγ解离，而非使三亚基偶联。","cAMP通路不经过MAPK级联，MAPK属RTK-Ras通路。","G蛋白不直接与PKA偶联，PKA由cAMP激活，故C表述错误。","受体活化经G蛋白α亚基与AC偶联，催化生成cAMP，表述正确。"]},{"id":"ch11_mcq_5","mod":"4.1.2 G-蛋白偶联受体","modI":0,"q":"一氧化氮受体是（            ）。","o":["A．G 蛋白偶联受体","B．鸟苷酸环化酶","C．腺苷酸环化酶","D．受体酪氨酸激酶"],"a":"B","e":"NO 是种可溶性气体，可作为局部介质在许多组织中发挥作用，靶细胞内可溶性鸟 苷酸环化酶（G-cyclase，GC）的激活是 NO 发挥作用的主要机制。","kp":"ch11_s0_0","oe":["NO不通过G蛋白偶联受体发挥其信号作用。","可溶性鸟苷酸环化酶是NO的靶分子，激活后生成cGMP，正确。","腺苷酸环化酶催化生成cAMP，不是NO的受体。","受体酪氨酸激酶与NO的信号作用无关。"]},{"id":"ch11_mcq_6","mod":"4.1.2 G-蛋白偶联受体","modI":0,"q":"有关 cAMP 信号通路，下列说法错误的是（              ）。","o":["A．被激活的蛋白激酶 A 的催化亚基转位进入细胞核，使基因调控蛋白磷酸化","B．结合 GTP 的α亚基具有活性，而βγ亚基复合物没有活性","C．βγ亚基复合物与游离的 Gs 的α亚基结合，可使 Gs 的α亚基失活","D．这一通路的首要效应酶是腺苷酸环化酶，cAMP 被环腺苷磷酸二酯酶消除"],"a":"B","e":"当细胞没有受到激素刺激，Gs 处于非活化态时，Gs 蛋白为异聚体，α亚基与 GDP 结合，此时腺苷酸环化酶没有活性；当激素配体与 Rs 受体结合，导致受体构象改变，暴露 出与 Gs 结合的位点，膜的流动性使激素-受体复合物与 Gs 结合，Gs 的α亚基构象改变，从 而排斥 GDP，结合 GTP 而活化，使三聚体 Gs 蛋白解离出α亚基和βγ亚基复合物，并暴露出 α亚基与腺苷酸环化酶的结合位点，结合 GTP 的α亚基与腺苷酸环化酶结合，使之活化，并 将 ATP 转化为 cAMP。当 Gi 与 GTP 结合，Gi 的α亚基与βγ亚基解离后，一是通过α亚基与 腺苷酸环化酶结合，直接抑制酶的活性，二是通过βγ亚基复合物与游离的 Gs α亚基结合， 阻断的α亚基对腺苷酸环化酶的活化。","kp":"ch11_s0_2","oe":["PKA催化亚基可进入细胞核使基因调控蛋白磷酸化，说法正确。","βγ亚基复合物并非没有活性，仍可调节效应器，故B错误。","βγ复合物结合游离Gs的α亚基可使Gs失活，说法正确。","该通路首要效应酶是AC，cAMP由磷酸二酯酶降解，说法正确。"]}],"judge":[{"id":"ch11_judge_2","modI":0,"q":"G 蛋白偶联受体中，霍乱毒素使 G 蛋白α亚基不能活化，百日咳毒素使 G 蛋白α亚基持续 活化。（      ）","a":"错","e":"霍乱毒素，使α亚基丧失 GTP 酶的活性并处于持续活化状态；百日咳毒素抑制 Gi 的活性。","kp":"ch11_s0_8","oe":["误将霍乱毒素与百日咳毒素对G蛋白的作用弄反，故判对。","霍乱毒素使Gα丧失GTP酶活性而持续活化，百日咳毒素则抑制Gi活性。"]}],"fill":[{"id":"ch11_fill_2","modI":0,"q":"cAMP 信号通路的效应酶是______，磷脂酰肌醇信号通路的效应酶是______。","a":"腺苷酸环化酶；磷脂酶 C","kp":"ch11_s0_0","oe":["cAMP通路的效应酶是腺苷酸环化酶，催化生成cAMP","磷脂酰肌醇通路效应酶是磷脂酶C，水解PIP2"]},{"id":"ch11_fill_4","modI":0,"q":"受体的本质是______，构成______。","a":"激素激活的基因调控蛋白；细胞内受体超家族","kp":"ch11_s0_0","oe":["胞内受体的本质是激素激活的基因调控蛋白","它们结构同源，共同构成细胞内受体超家族"]},{"id":"ch11_fill_5","modI":0,"q":"G 蛋白耦联受体是细胞表面由______条多肽______次跨膜形成的受体，N 端在______，C 端在______。N 端与______结合，C 端与______作用。","a":"单；7；外；内；信号；G 蛋白","kp":"ch11_s0_4","oe":["G蛋白耦联受体由单条多肽链构成，反复穿膜","该肽链7次跨膜，形成七个跨膜α螺旋","该受体N端位于细胞膜外侧，朝向胞外","该受体C端位于细胞膜内侧，朝向胞质","N端负责与细胞外的信号分子结合","C端则与胞内的G蛋白相互作用并传递信号"]},{"id":"ch11_fill_6","modI":0,"q":"第一信使指______。","a":"细胞外信号分子","kp":"ch11_s0_0","oe":["第一信使即细胞外信号分子，是信号转导的起始携带者"]},{"id":"ch11_fill_7","modI":0,"q":"硝酸甘油能用于治疗心绞痛是因为______。","a":"硝酸甘油在体内转化为 NO，可舒张血管","kp":"ch11_s0_0","oe":["硝酸甘油在体内释放NO，NO舒张血管缓解心绞痛"]},{"id":"ch11_fill_9","modI":0,"q":"无活性的蛋白激酶 A 有______和______亚基，cAMP 结合它的______使其激活。","a":"调节亚基；无活性的催化；调节亚基","kp":"ch11_s0_2","oe":["无活性的蛋白激酶A含有调节亚基","同时含无活性的催化亚基，二者组成四聚体","cAMP结合调节亚基，使催化亚基释放而被激活"]}],"short":[{"id":"ch11_short_3","modI":0,"q":"G 蛋白偶联受体与酶联受体有什么主要不同点？","a":"蛋白偶联受体都含有 7 次跨膜的结构域，在信号转导中全部与 G 蛋白偶联；酶联受体 都属于单次跨膜受体，当该类受体与配体结合时导致受体二聚化形成同源或异源多聚化。","kp":"ch11_s0_8"},{"id":"ch11_short_4","modI":0,"q":"简述 cAMP 途径中的 Gs 调节模型。","a":"在该途径中由刺激型 Gs 蛋白复合物偶联刺激型受体与腺苷酸环化酶。当细胞没有接受 刺激信号时，Gs 处于非活化状态，Gs 蛋白为异三聚体，α亚基与 GDP 结合，这时腺苷酸环 化酶没有活性。当刺激型的第一信使作用于刺激型的受体后，导致受体构象改变，受体复合 物与 GS 结合引起 Gs 的α亚基构象变化排斥 GDP，而与 GTP 结合被活化，三聚体 Gs 解离 出α亚基和贝塔嘎嘛亚基复合物，活化的刺激型 Gsα亚基继激活腺苷酸环化酶的活性，从而 产生第二信使 cAMP，由于 cAMP 的浓度升高，引起细胞内依赖于 cAMP 的靶酶活化，由 此将胞外信号转换成胞内信号传递、放大以致调节细胞生理反应或基因的表达等。随着 GTP 的水解使α亚基恢复原来的构象并导致与腺苷酸环化酶解离，终止腺苷酸环化酶的活化作 用,α亚基和βγ亚基重新结合，使细胞回复到静止状态。","kp":"ch11_s0_8"}],"calc":[{"id":"ch11_calc_3","modI":0,"q":"如何理解信号系统及其功能?","a":"（1）信号系统的基本组成及信号蛋白 ①通过细胞表面受体介导的信号途径的步骤组成： a．细胞通过特异性受体识别胞外信号分子； b．信号跨膜转导； c．通过胞内级联反应实现信号放大作用，并终止细胞活性改变； d．由于信号分子失活，细胞反应终止或下调。 ②相关信号蛋白： a．细胞表面受体；b．转承蛋白；c．信使蛋白；d．接头蛋白；e．放大和转导蛋白；f．传 感蛋白；g．分歧蛋白；h．整合蛋白；i．潜在基因调控蛋白。 （2）信号转导系统的功能 ①相关信号蛋白的功能如下： a．细胞表面受体：特异识别胞外信号。 b．转承蛋白：负责信息向下传递。 c．信使蛋白：携带信号从一部分传递到另外一部分。 d．接头蛋白：连接信号蛋白。 e．放大和转导蛋白：由酶和离子通道组成，介导信号级联反应。 f．传感蛋白：负责不同形式信号的转换。 g．分歧蛋白：信号从一条途径传递到另外一条途径。 h．整合蛋白：从多条通路接受信号并向下传递。 i．潜在基因调控蛋白：在表面被受体活化，迁移到细胞核刺激基因转录。 ②细胞内信号蛋白的相互作用是靠蛋白质模式结合域特异性介导的。信号蛋白具有不同的模 式结合域与另一相匹配的基序识别并结合，在细胞内组装成不同的信号转导复合物，构成细 胞内信号传递通路的基础。 ③信号转导系统的主要作用：特异性、放大作用、信号终止、整合作用。","kp":"ch11_s0_0"}],"term":[{"id":"ch11_term_6","modI":0,"term":"蛋白激酶 VS 蛋白酶体","def":"蛋白激酶又称蛋白质磷酸化酶，是一类催化蛋白质磷酸化反应的酶，能够特异性地在某 些蛋白质的某些氨基酸位点上添加磷酸基团。蛋白激酶在细胞内的分布遍及核、线粒体、微 粒体和胞液。一般分为 3 大类：①底物专一的蛋白激酶：如磷酸化酶激酶，丙酮酸脱氢酶激 酶等。②依赖于环核苷酸的蛋白激酶：如环腺苷酸（cAMP）蛋白激酶，环鸟苷酸（cGMP） 蛋白激酶。③其他蛋白激酶：如组蛋白激酶等。 蛋白酶体是一类能降解细胞不需要的或受到损伤蛋白质的蛋白复合物。经过蛋白酶体的作用， 蛋白质被切断为约 7～8 个氨基酸长的肽段，这些肽段可以被进一步降解为单个氨基酸分子， 然后被用于合成新的蛋白质。蛋白酶体是细胞用来调控特定蛋白质和除去错误折叠蛋白质的 主要机制。一般来说，需要被降解的蛋白质会先被一个称为泛素的小型蛋白质所标记，被标 记上的蛋白质就会被蛋白酶体降解，因此人们常把蛋白酶体和泛素结合起来，将这一过程称 为泛素依赖性蛋白酶体降解途径。","kps":"","kp":"ch11_s0_6"}]},{"i":1,"name":"4.1.3 G蛋白偶联受体","slides":[{"i":9,"sec":"4.1.3 G蛋白偶联受体","title":"4.1.3 G蛋白偶联受体","notes":"效应器(三)磷脂酶C(PLC)\n－肌醇磷脂信号通路(又称双信使系统)\n● 胞外信号分子与细胞表面G蛋白偶联受体结合，激活质膜上\n的磷脂酶C(PLC)\n●质膜上的4，5-二磷酸磷脂酰肌醇（PIP2）水解成1,4,5-三磷\n酸肌醇（IP3）和二酰基甘油(DAG)两个第二信使，胞外信号转\n变为胞内信号。\n●IP3水溶性小分子，离开质膜迅速在胞质溶胶中扩散。使内质\n网Ca2+ 通道打开，释放Ca2+到胞质，细胞内 Ca2+溶度升高；\nCa2+ 协同DAG激活蛋白激酶C(PKC)，PKC 进一步磷酸化底物\n蛋白。","page":10,"level":"掌握","img":"assets/img/ch11/p010.jpg","anim":null,"fig":null,"points":["效应器(三)：磷脂酶C(PLC)-肌醇磷脂信号通路，又称双信使系统","胞外信号与GPCR结合激活PLC，PIP2水解成IP3和DAG两个第二信使","IP3使内质网Ca2+通道打开、释放Ca2+到胞质；Ca2+协同DAG激活蛋白激酶C(PKC)"],"check":{"q":"磷脂酶C(PLC)被激活后，PIP2水解生成的两个第二信使是？","o":["A. IP3和DAG","B. Ca2+和NO","C. cAMP和cGMP","D. ATP和ADP"],"a":"A","e":"PLC催化质膜上的PIP2水解成IP3和DAG两个第二信使，分别介导Ca2+释放与PKC激活。","oe":["PIP2水解生成IP3和DAG，正确。","Ca2+为IP3下游释放的信号，NO非本通路产物。","cAMP、cGMP不由此途径产生。","ATP、ADP属核苷酸，不是第二信使。"]},"cards":null,"mem":"PLC切PIP2→IP3+DAG；激活PKC需Ca2+","big":"assets/img/ch11/big/p010.jpg","terms":[{"t":"PIP2","en":"phosphatidylinositol 4,5-bisphosphate","d":"质膜上的磷脂，被磷脂酶C水解生成IP3和DAG两个第二信使。"}]},{"i":10,"sec":"4.1.3 G蛋白偶联受体","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• phospholipase C-β —— 磷脂酶C-β\n• PI 4,5-bisphosphate [PI(4,5)P2] —— PIP2（磷脂酰肌醇4,5-二磷酸）\n• diacylglycerol (DAG) —— DAG（二酰甘油）→激活蛋白激酶C(PKC)\n• inositol 1,4,5-trisphosphate (IP3) —— IP3（肌醇1,4,5-三磷酸）→从内质网释放Ca²⁺\n• CYTOSOL —— 胞质溶胶\n【读图讲解】\n信号转导示意图：磷脂酶C-β水解膜脂 PIP2，生成两种第二信使——DAG(留膜激活PKC)与 IP3(促内质网释放Ca²⁺)。考点：Gq-PLCβ 通路与双信使分岔。","page":11,"level":"掌握","img":"assets/img/ch11/p011.jpg","anim":null,"fig":null,"points":["fatty acid chains of inner","lipid monolayer of","plasma membrane","O=","C=O","=O","C=O","CYTOSOL"],"check":{"q":"关于肌醇磷脂信号通路中DAG与IP3的作用，正确的是？","o":["A. DAG留在膜上激活PKC，IP3促进内质网释放Ca2+","B. 两者都留在膜上激活PKC","C. DAG促进内质网释放Ca2+，IP3留在膜上激活PKC","D. 两者都进入胞质促进Ca2+释放"],"a":"A","e":"PLC-β水解PIP2生成DAG和IP3；DAG留在膜上激活PKC，IP3为水溶性、促内质网释放Ca2+。","oe":["DAG激活PKC、IP3促Ca2+释放，正确。","IP3是水溶性，会扩散入胞质。","二者作用正好相反，DAG并非促Ca2+释放者。","DAG留在质膜上而非进入胞质，IP3才进入胞质。"]},"cards":null,"mem":"PLCβ切PIP2：DAG激PKC，IP3放Ca2+","big":"assets/img/ch11/big/p011.jpg"},{"i":11,"sec":"4.1.3 G蛋白偶联受体","title":"肌醇磷脂信号通路","notes":"肌醇磷脂信号通路：信号分子与G蛋白偶联受体结合→活化的受体通过G蛋白激活磷脂酶C(PLC)→PIP2分解为IP3和DAG两个第二信使。IP3使内质网钙库释放Ca²⁺，DAG活化蛋白激酶C(PKC)，进而调节一系列生物学反应。该通路又称PKC系统(protein kinase C system)。","page":12,"level":"掌握","img":"assets/img/ch11/p012.jpg","anim":null,"fig":null,"points":["信号分子与GPCR结合，活化受体经G蛋白激活磷脂酶C，PIP2分解为IP3和DAG","IP3从内质网钙库释放Ca2+，DAG活化蛋白激酶C(PKC)","该通路又称PKC系统(protein kinase C system)"],"check":{"q":"在肌醇磷脂信号通路中，IP3的作用是？","o":["A. 使PIP2水解为DAG","B. 从内质网钙库中释放Ca2+","C. 激活腺苷酸环化酶生成cAMP","D. 活化蛋白激酶C(PKC)"],"a":"B","e":"PIP2被磷脂酶C水解为IP3和DAG，IP3释放Ca2+，DAG活化PKC。","oe":["PIP2水解由磷脂酶C催化，非IP3所致。","正确，IP3作用于内质网钙库，释放Ca2+。","该通路不涉及腺苷酸环化酶与cAMP。","活化PKC的是DAG，不是IP3。"],"basis":"IP3从ER钙库中释放Ca2+；DAG活化蛋白激酶C(PKC)。"},"cards":null,"mem":"肌醇磷脂通路：GPCR→PLC→IP3/DAG→PKC","big":"assets/img/ch11/big/p012.jpg"},{"i":12,"sec":"4.1.3 G蛋白偶联受体","title":"－蛋白激酶C为细胞质酶，在未受刺激的细胞","notes":"中水溶性，游离在细胞质中，非活性状态；\nDAG和Ca2+同时作用下激活后成为质膜结合\n蛋白。\n－PKC与PKA一样，将靶蛋白的丝氨酸、苏氨\n酸残基磷酸化。","page":13,"level":"掌握","img":"assets/img/ch11/p013.jpg","anim":null,"fig":null,"points":["蛋白激酶C(PKC)为细胞质酶，未受刺激时游离在胞质中呈非活性状态","在DAG和Ca2+同时作用下激活，成为质膜结合蛋白","PKC将靶蛋白的丝氨酸、苏氨酸残基磷酸化"],"check":{"q":"关于蛋白激酶C(PKC)的特性，正确的是？","o":["A. 未受刺激时游离于胞质，DAG和Ca2+共同作用后成为质膜结合蛋白","B. 是一种能与DNA直接结合的转录因子","C. 始终结合在质膜上，无需DAG和Ca2+","D. 只磷酸化靶蛋白的酪氨酸残基"],"a":"A","e":"PKC为细胞质酶，静息时游离在胞质呈非活性态，DAG和Ca2+共同作用下激活并变为质膜结合蛋白，磷酸化底物丝/苏氨酸残基。","oe":["PKC静息游离、DAG与Ca2+协同激活后结合质膜，正确。","PKC是激酶，不是DNA结合转录因子。","静息时PKC游离于胞质，并非始终结合质膜。","PKC磷酸化丝氨酸/苏氨酸，非酪氨酸。"]},"cards":null,"mem":"PKC：DAG+Ca2+激活转膜，磷酸化Ser/Thr","big":"assets/img/ch11/big/p013.jpg"},{"i":13,"sec":"4.1.3 G蛋白偶联受体","title":"DAG","notes":"The activation of PKC\ndepends on an increase of\nboth Ca2+ and DAG.\n【中文讲解·对照课本/考点】\n考点：4.1.3 G蛋白偶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 磷脂酰肌醇信号通路● “双信使系统”反应链：胞外信号分子→G-蛋白偶联受体→G-蛋白→\n\n【本页英文讲解】\n本页主题为DAG（二酰甘油/甘油二酯，diacylglycerol）。原文指出：PKC（蛋白激酶C，protein kinase C）的活化需Ca2+与DAG两者同时升高。DAG由质膜磷脂酶C水解PIP2产生，与IP3一同生成。考点：PKC是Ca2+和DAG双重依赖的激酶，为翟中和教材第九章双信使（IP3/DAG）通路的关键环节。","page":14,"level":"掌握","img":"assets/img/ch11/p014.jpg","anim":null,"fig":null,"points":["蛋白激酶C(PKC)的激活依赖于Ca2+和DAG同时升高"],"check":{"q":"蛋白激酶C(PKC)的活化依赖于？","o":["A. 仅cAMP升高","B. Ca2+与DAG两者同时升高","C. 仅cGMP升高","D. IP3单独作用"],"a":"B","e":"PKC的活化需Ca2+与DAG两者同时升高，DAG由PLC水解PIP2产生，与IP3一同生成。","oe":["cAMP主要激活PKA，而非PKC。","PKC依赖Ca2+和DAG双重升高而活化，正确。","cGMP主要激活蛋白激酶G(PKG)，而非PKC。","IP3促Ca2+释放，单独不足以活化PKC。"]},"cards":null,"mem":"DAG与IP3同源PIP2；PKC需Ca2+和DAG升高","big":"assets/img/ch11/big/p014.jpg"},{"i":14,"sec":"4.1.3 G蛋白偶联受体","title":"●分子开关 (Molecular Switches）","notes":"在细胞内信号级联放大过程中分子开关信号蛋\n白起关键作用。作为分子开关的蛋白几乎均属\n于以下这两大类：\n1. 分子开关蛋白的活性由磷酸化与去磷酸化\n（磷酸基团的加上和去除）来开启和关闭；\n2. GTP结合蛋白，根据开关蛋白结合GTP或\nGDP来决定这些开关是激活态or失活态。","page":15,"level":"掌握","img":"assets/img/ch11/p015.jpg","anim":null,"fig":null,"points":["相对更普遍存在"],"check":{"q":"关于细胞内信号级联放大中的分子开关蛋白，叙述正确的是（　）","o":["A. 活性可由磷酸化与去磷酸化来开启和关闭","B. 分子开关不参与信号级联放大过程","C. 结合GDP时被激活，结合GTP时失活","D. 只有GTP结合蛋白一类，不存在磷酸化开关"],"a":"A","e":"作为分子开关的信号蛋白主要有两大类：一类由磷酸化与去磷酸化开启和关闭；另一类为GTP结合蛋白，由结合GTP或GDP决定其激活或失活。","oe":["正确：磷酸化与去磷酸化是开启/关闭分子开关的普遍机制。","错误：分子开关在细胞内信号级联放大过程中起关键作用。","错误：GTP结合蛋白结合GTP为激活态，结合GDP为失活态。","错误：分子开关包括磷酸化开关和GTP结合蛋白两大类。"]},"cards":null,"mem":"分子开关两类：磷酸化开关与GTP/GDP开关","big":"assets/img/ch11/big/p015.jpg"},{"i":15,"sec":"4.1.3 G蛋白偶联受体","title":"信号转导中的分子开关：蛋白激酶/磷酸酶与GEF/GAP","notes":"信号转导中的两类“分子开关”：①蛋白激酶与蛋白磷酸水解酶(磷酸酶)相互对应——激酶将ATP的磷酸基加到靶蛋白上，磷酸酶则水解去除磷酸基；②GEF与GAP/RGS——GEF促进GDP从G蛋白上解离并结合GTP，使G蛋白处于“ON”(激活)状态；GAP/RGS促进GTP水解为GDP，使G蛋白转为“OFF”(失活)状态。","page":16,"level":"掌握","img":"assets/img/ch11/p016.jpg","anim":null,"fig":null,"points":["蛋白激酶与蛋白磷酸水解酶相互对应","GEF促进GTP结合(ON)，GAP/RGS促进GTP水解(OFF)"],"check":{"q":"在信号转导的分子开关调节中，使G蛋白由“ON”转为“OFF”的是？","o":["A. GEF促进GDP解离","B. GAP/RGS促进GTP水解","C. 蛋白磷酸水解酶去磷酸化","D. 蛋白激酶磷酸化底物"],"a":"B","e":"GAP/RGS促进GTP水解使G蛋白由“ON”转为“OFF”，GEF则促进GDP换成GTP使其激活。","oe":["GEF使G蛋白由OFF转为ON。","GAP/RGS促进GTP水解使G蛋白关闭，正确。","蛋白磷酸酶作用于磷酸化蛋白，非G蛋白开关。","蛋白激酶磷酸化属下游效应，非G蛋白开关。"]},"cards":null,"mem":"激酶加磷酸、磷酸酶去磷酸；GEF开、GAP关","big":"assets/img/ch11/big/p016.jpg"},{"i":16,"sec":"4.1.3 G蛋白偶联受体","title":"➢ 蛋白激酶(kinase)","notes":"An enzyme that transfers the terminal phosphate group from\nATP to a substrate. Protein kinase, which phosphorylate specific\nserine, threonine, or tyrosine residues in target proteins, play a\ncritical role in regulating the activity of many cellular proteins.\n➢ 蛋白磷酸酶/蛋白磷酸水解酶(phosphatase)\nAn enzyme that removes a phosphate group form a substrate\nby hydrolysis.\n（区别于糖原磷酸化酶：glycogen phosphorylase, GP）\n➢ 蛋白酶体(proteasome)\nLarge multifunctional protease complex in the cytosol that\ndegrades intracellular proteins marked for destruction by\nattachment of multiple ubiquitin molecules.\n【中文讲解·对照课本/考点】\n考点：4.1.3 G蛋白偶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。\n\n【本页英文讲解】\n本页辨析三个易混术语。蛋白激酶（kinase）是把ATP末端磷酸基团转移到底物上的酶，可磷酸化靶蛋白的丝氨酸、苏氨酸或酪氨酸残基。蛋白磷酸酶（phosphatase）经水解去除底物的磷酸基团。蛋白酶体（proteasome）是胞质中大型多功能蛋白酶复合体，降解被多个泛素标记的细胞内蛋白，注意与糖原磷酸化酶（GP）区分。","page":17,"level":"掌握","img":"assets/img/ch11/p017.jpg","anim":null,"fig":null,"points":["蛋白激酶(kinase)把ATP末端的磷酸基团转移到底物上","可磷酸化靶蛋白的丝氨酸、苏氨酸或酪氨酸残基，调节蛋白活性","蛋白磷酸酶经水解去除底物的磷酸基团；蛋白酶体降解被泛素标记的胞内蛋白"],"check":{"q":"关于蛋白激酶(kinase)的描述，正确的是？","o":["A. 通过水解去除底物上的磷酸基团","B. 是降解泛素标记蛋白的蛋白酶复合体","C. 将ATP末端磷酸基团转移到底物蛋白的丝氨酸、苏氨酸或酪氨酸残基上","D. 催化糖原加磷酸生成G-1-P"],"a":"C","e":"蛋白激酶把ATP末端磷酸基团转移到底物，磷酸化其丝氨酸、苏氨酸或酪氨酸残基，调节蛋白活性。","oe":["水解去除磷酸基团的是蛋白磷酸酶，而非蛋白激酶。","降解泛素标记蛋白的是蛋白酶体，不是蛋白激酶。","蛋白激酶转移ATP磷酸基团到底物，正确。","催化糖原加磷酸的是糖原磷酸化酶。"]},"cards":null,"mem":"激酶移ATP磷酸至Ser/Thr/Tyr；磷酸酶去磷酸","big":"assets/img/ch11/big/p017.jpg"}],"mcq":[{"id":"ch11_mcq_1","mod":"4.1.3 G蛋白偶联受体","modI":1,"q":"细胞内信号蛋白的相互作用是靠（            ）所特异性介导的。","o":["A．蛋白质模式结合域","B．受体蛋白","C．G 蛋白偶联受体","D．疏水性分子相互作用"],"a":"A","e":"靠信号蛋白具有不同的模式结合域与另一相匹配的基序识别与结合，在细胞内组装 成不同信号转导复合物，构成细胞内信号传递通路的基础。","kp":"ch11_s1_14","oe":["信号蛋白靠模式结合域与相匹配基序识别结合，组装信号复合物，正确。","受体蛋白位于膜上识别胞外信号，非胞内信号蛋白互作的介导者。","G蛋白偶联受体为膜受体，不是胞内信号蛋白互作的基础。","疏水性分子间的相互作用不具特异性识别功能。"]},{"id":"ch11_mcq_4","mod":"4.1.3 G蛋白偶联受体","modI":1,"q":"与细胞内钙离子浓度调控直接相关的信号为（                ）。","o":["A．DAG","B．PKC","C．CaM","D．IP3"],"a":"D","e":"IP3 通过细胞质基质扩散，结合并打开内质网膜上 IP3 敏感的钙通道，引起钙离子顺 电化学梯度从钙库释放进入细胞质基质，通过钙调蛋白引起细胞反应。","kp":"ch11_s1_15","oe":["DAG主要激活蛋白激酶C，不直接引起胞内Ca2+释放。","PKC是DAG和Ca2+激活的激酶，并非直接调控钙浓度者。","CaM是钙结合蛋白，感受Ca2+信号而非直接引起其释放。","IP3结合内质网IP3受体钙通道，促使Ca2+从钙库释放，正确。"]}],"judge":[{"id":"ch11_judge_1","modI":1,"q":"与胞内受体结合的信号分子多为亲脂性分子。（         ）","a":"对","e":"亲脂性分子疏水性较强，可穿过细胞膜进入细胞。","kp":"ch11_s1_15","oe":["亲脂性分子疏水性强，易穿过细胞膜进入胞内与胞内受体结合。","误以为胞内受体的配体都是亲水分子，忽视了其需穿膜的特性。"]},{"id":"ch11_judge_3","modI":1,"q":"受体都分布于质膜表面，在信息传递和细胞识别过程中起信号接收器的作用。(       )","a":"错","e":"受体分为胞内受体和胞外受体两种类型。","kp":"ch11_s1_15","oe":["误以为受体只存在于质膜表面，故判对。","受体分胞内受体和胞外（膜）受体两类，并非都分布在质膜表面。"]},{"id":"ch11_judge_7","modI":1,"q":"胞内受体一般处于受抑制状态，细胞内信号的作用是解除抑制。（       ）","a":"对","e":"","kp":"ch11_s1_15","oe":["类固醇激素胞内受体结合抑制蛋白而失活，配体结合后解除抑制被激活。","误以为胞内受体平时即活化，其实需配体解除抑制才能发挥调控作用。"]},{"id":"ch11_judge_8","modI":1,"q":"IP3 是直接由 PIP2 产生的，PIP2 是从肌醇磷脂衍生而来的，肌醇磷脂没有掺入另外的磷酸 基团。","a":"对","e":"PIP2 含有三个磷酸基团，其中一个连接糖与二酰甘油酯。IP3 通过一个简单的水解 反应产生。","kp":"ch11_s1_11","oe":["IP3由PIP2经简单水解产生，PIP2含三个磷酸基团，衍生时不再额外加磷。","误以为肌醇磷脂衍生时又掺入新的磷酸基团，其实仅是原有基团的保留。"]}],"fill":[{"id":"ch11_fill_1","modI":1,"q":"一般将胞外的信号分子称为______，将细胞内最早产生的信号分子称为______。","a":"第一信使；第二信使","kp":"ch11_s1_15","oe":["胞外信号分子称第一信使，负责携带外来信号","细胞内最早产生的信号分子称第二信使，如cAMP"]},{"id":"ch11_fill_12","modI":1,"q":"细胞识别作用引起三种反应：①是______；②是______；③是______。","a":"内吞作用；细胞黏着；接触抑制","kp":"ch11_s1_15","oe":["细胞识别可触发内吞作用，摄取特定物质","细胞识别可介导细胞黏着，使细胞相互连接","细胞识别可引起接触抑制，控制细胞增殖"]},{"id":"ch11_fill_13","modI":1,"q":"胞内受体一般有三个结构域：①______；②______；③______。","a":"与信号分子结合的 C 端结构域；与 DNA 结合的中间结构域；活化基因转录的 N 端结构域","kp":"ch11_s1_15","oe":["C端为与信号分子（激素）结合的结构域","中间为与DNA结合的结构域，调控转录","N端为活化基因转录的结构域，启动表达"]},{"id":"ch11_fill_17","modI":1,"q":"细胞表面受体丝氨酸∕苏氨酸激酶是_____次跨膜蛋白受体，受体胞内区具有_____活性， 它的主要配体是_____。","a":"1；丝氨酸∕苏氨酸蛋白激酶；转化生长因子β家族成员","kp":"ch11_s1_12","oe":["丝氨酸/苏氨酸激酶受体为单次跨膜蛋白","其胞内区具有丝氨酸/苏氨酸蛋白激酶活性","其主要配体是转化生长因子β家族成员"]}],"short":[{"id":"ch11_short_6","modI":1,"q":"Ca2+为何可以作为胞内信号进行信号转导，Ca2+的储存与释放在信号转导中有什么作用？","a":"在细胞质基质中，基态的 Ca2+浓度约为 l0-7～mol／L，很少的 Ca2+流入就可以导致胞内 溶胶 Ca2+较大程度变化。与 Na+相比，胞内 Na+浓度发生显著改变所需要的离子量要大得多。 在信号转导中，Ca2+作用极其重要，不仅可以作为第三信使参与广泛的生理活动，活化各种 Ca2+结合蛋白并引起细胞反应，而且在双信使系统本身的调节方面也非常重要。胞内 Ca2+ 浓度过高会引起细胞中毒，质膜上的钙泵和钠钙交换器将 Ca2+泵出细胞，内质网膜上的钙 泵会将高浓度的 Ca2+泵进内质网钙库。至少已经发现 4 种以上的钙结合蛋白，每个钙结合蛋 白可与 30 个左右的 Ca2+结合，钙结合蛋白的浓度可达 30～100 mg／mL，内质网作为 Ca2+ 的储存库。","kp":"ch11_s1_9"},{"id":"ch11_short_7","modI":1,"q":"比较 cAMP 信号系统与 IP3-DAG 信号系统在跨膜信号传递作用的异同。","a":"二者都是 G 蛋白偶联信号转导系统，但是第二信使不同，分别由不同的效应物生成： cAMP 由腺苷酸环化酶(AC)水解细胞中的 ATP 生成，cAMP 再与蛋白激酶 A(PKA)结合，引 发一系列细胞质反应与细胞核中的作用。在另一种信号转导系统中，效应物磷脂酶 Cq(PLC) 将膜上的磷脂酰肌醇 4，5-二磷酸分解为两个信使：二酰甘油(DAG)与 1，4，5-三磷酸肌醇(IP3)， IP3 动员胞内钙库释放 Ca2+，与钙调蛋白结合引起系列反应，而 DAG 在 Ca2+的协同下激活 蛋白激酶 C(PKC)，再引起级联反应。","kp":"ch11_s1_11"},{"id":"ch11_short_9","modI":1,"q":"请列举三种以上受体酪氨酸蛋白激酶介导的信号转导的级联通路。","a":"受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要受体家族。 当配体与受体相结合，激活受体的酪氨酸蛋白激酶活性，随即引起一系列磷酸化级联反应， 最终导致细胞生理和基因表达的改变。其介导的信号转导级联通路举例如下： （1）Grb2 信号通路 活化的受体识别含有 SH2 结构的靶蛋白，当 TPK 受体被激活后便借助于自身磷酸化的酪氨 酸残基与细胞内的信号分子接头蛋白 Grb2 的 SH2 结构结合，激活靶蛋白。 （2）Sos 信号通路 TPK 除含有一个隐含的 SH2 结构域外，还具有两个 SH3 结构域。它的功能是识别并结合下 游的另一个信号分子——鸟苷酸释放因子（Sos），识别部位是 Sos 中富含脯氨酸的区段。 在细胞静息状态时，Grb2 通过两个 SH3 结构与 Sos 结合形成复合物，存在于胞浆中，当 TPK 受体被激活，通过 Grb2 的 N 端 SH2 结构将 Grb2-Sos 复合物与受体相连，并将其转移至细 胞膜上募集 Sos，提高 Sos 在质膜上的局部浓度，Sos 具有核苷酸转移酶的活性，可激活下 游靶蛋白 Ras。 （3）RTK-Ras 蛋白信号通路 Ras 蛋白在 RTK 介导的信号通路中是一种关键组分。Ras 蛋白结合 GTP 时为活化态，而结 合 GDP 时为失活态。所以 Ras 蛋白具有分子开关的作用。Ras 蛋白的活化及其细胞应答是 通过配体与 RTK 的结合而诱导的。由 RTK 介导的信号通路具有广泛的功能，包括调节细胞 的增殖、分化、促进细胞存活，以及细胞代谢过程中的调节与校正作用。各种不同的胞外配 体（生长因子）与 RTK 结合，有时会引起细胞内产生多向性的效应，包括早期和晚期的基 因表达。","kp":"ch11_s1_15"},{"id":"ch11_short_11","modI":1,"q":"真核细胞为何以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使？（注：细胞质中游 ＋        ＋   离 Ca2 的浓度维持在 10-7mol/L，而 Na 的浓度维持在 10-3mol/L） ＋                     ＋","a":"真核细胞之所以以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使，主要有两方面 ＋       ＋   的原因： （1）以 Ca2 为细胞内的第三信使，只需要少量的 Ca2 进入细胞，即可达到传递信号所需的 ＋                         ＋   浓度阈值，从而诱发各种细胞反应，即使在细胞外 Ca2 缺乏的情况下也容易达到； ＋   （2）若以 Na 作为第三信使，势必需要很多 Na 进入细胞内，一方面会引起细胞外 Na 的 ＋                   ＋                          ＋   缺少，需要大量 Na 进行补充；另一方面也会引起膜电位的紊乱，对细胞造成伤害。 ＋","kp":"ch11_s1_12"},{"id":"ch11_short_12","modI":1,"q":"如果说细胞信号产生于多细胞生命形式的需要，那如何解释动物与单细胞的出芽酵母之 间在细胞信号上有如此相似的机制？","a":"动物与单细胞的出芽酵母之间在细胞信号上有相似机制的原因：多细胞有机体的细胞和 细胞之间需要进行信息交流，所以有信号转导机制。单细胞的出芽酵母也要与周围的环境进 行信息交流，当细胞受到刺激后首先被细胞表面特异性受体所识别，胞外信号通过信使进入 胞内转变为胞内信号，这与多细胞生物是相似的。","kp":"ch11_s1_15"},{"id":"ch11_short_13","modI":1,"q":"G 蛋白在细胞质膜受体介导的信号传导途径中的功能及其调节。","a":"（1）G 蛋白在细胞质膜受体介导的信号传导途径中的功能 G 蛋白能够将受体接受的信号传递给效应物，产生第二信使，进行信号转导，某些 G 蛋白 还可直接调节某些离子通道的通透性。 （2）G 蛋白在细胞质膜受体介导的信号传导途径中的调节 G 蛋白由α，β，γ三个不同亚基组成。配体和受体结合，诱导 GTP 与 G 蛋白结合的 GDP 进 行交换，GTP 结合的 G 蛋白处于活化状态，激活位于信号传导途径中的下游分子如腺苷酸 环化酶。G 蛋白α亚基具有内源 GTP 酶活性，当 GTP-Gα水解为 GDP-Gα后，则处于失活状 态。 G 蛋白偶联受体介导的信号通路主要有两条：一条是 cAMP 信号通路，另有一条是磷脂酰 肌醇信号通路。前者是配体与受体结合，激活偶联的 G 蛋白，G 蛋白激活腺苷酸环化酶， 产生第二信使 cAMP，引发下游细胞事件。后者也是配体与受体结合激活偶联的 G 蛋白， 活化的 G 蛋白激活质膜上的磷脂酶 C，使 PIP2 水解为 IP3 和 DAG 两个第二信使，IP3 可动员 细胞内 Ca2 释放，DAG 可激活蛋白激酶 C（PKC），分别激发细胞的下游事件，又称“双信 ＋   使系统”。","kp":"ch11_s1_15"}],"calc":[],"term":[{"id":"ch11_term_3","modI":1,"term":"双信使系统（double messenger system）。","def":"双信使系统（double messenger system）是指磷脂酰肌醇信号通路的胞外信号被膜蛋白 受体接受后，同时产生两个胞内信使，分别启动两个信号传递途径即 IP3-Ca2+和 DG-PKC 途 径，实现细胞对外界信号的应答的一种信号系统。","kps":"","kp":"ch11_s1_9"},{"id":"ch11_term_7","modI":1,"term":"分子开关","def":"分子开关是指通过激活机制或失活机制精确控制细胞内一系列信号传递级联反应的蛋白 质分子，可分为两类：一类分子开关蛋白的活性由磷酸化和去磷酸化控制，蛋白激酶使之磷 酸化而开放，蛋白磷酸酯酶使之去磷酸化而关闭，许多由可逆磷酸化控制的开关蛋白是蛋白 激酶本身；另一类分子开关蛋白是 GTP 结合蛋白，结合 GTP 而活化，结合 GDP 而失活。","kps":"","kp":"ch11_s1_14"},{"id":"ch11_term_8","modI":1,"term":"第二信使","def":"第二信使是指受细胞外信号的作用，在细胞质溶质内形成或向细胞质溶质释放的细胞内 小分子，负责将信号传到细胞内部，如 cAMP、IP3、Ca2 等。第二信使通过其浓度变化（增 ＋   加或减少）应答胞外信号与细胞表面受体的结合，调节细胞内酶和非酶蛋白的活性，从而在 细胞信号转导途径中行使携带和放大信号的功能。","kps":"","kp":"ch11_s1_9"},{"id":"ch11_term_9","modI":1,"term":"cell recognition","def":"cell recognition 的中文名称细胞识别。细胞识别主要是指细胞表面的受体或者配体与相 邻细胞表面的配体或者受体选择性识别、结合并引起一系列下游生理生化反应的过程，对多 细胞生物体的发育具有重要意义。","kps":"","kp":"ch11_s1_15"}]},{"i":2,"name":"4.2 酶联受体","slides":[{"i":17,"sec":"4.2 酶联受体","title":"4.2 酶联受体","notes":"(enzyme linked receptor)\n◆酶联受体本身在细胞内侧一端具有酶的活\n性，当其胞外端与配体信号分子结合后，则\n启动细胞膜内侧另一端的酶活性，并将信号\n放大，又称催化受体(catalytic receptor)。\n◆这类受体传导的信号(生长因子)主要与细\n胞生长、分裂繁殖有关。","page":18,"level":"掌握","img":"assets/img/ch11/p018.jpg","anim":null,"fig":null,"points":["酶联受体本身在细胞内侧一端具有酶的活性，与配体结合后启动其酶活性并放大信号","又称催化受体(catalytic receptor)","其信号(生长因子)主要与细胞生长、分裂繁殖有关"],"check":{"q":"酶联受体传导的信号主要与下列哪项有关？","o":["A. 血糖的快速分解","B. 细胞生长、分裂繁殖","C. 肌肉收缩","D. 视觉光信号感受"],"a":"B","e":"酶联受体又称催化受体，其信号主要调控细胞生长与分裂繁殖。","oe":["糖原分解属cAMP-PKA通路，非酶联受体。","正确，酶联受体信号(生长因子)主要与生长、分裂繁殖有关。","肌肉收缩主要由Ca2+与G蛋白偶联信号介导。","视觉感受由G蛋白偶联受体通路完成。"],"basis":"这类受体传导的信号(生长因子)主要与细胞生长、分裂繁殖有关。"},"cards":null,"mem":"酶联受体胞内具酶活；配体结合激活，主控生长分裂","big":"assets/img/ch11/big/p018.jpg","terms":[{"t":"催化受体","en":"catalytic receptor","d":"即酶联受体，胞内段具有酶活性，配体结合后启动其酶活性并放大信号。"}]},{"i":18,"sec":"4.2 酶联受体","title":"酪氨酸蛋白激酶活性的受体(Receptor","notes":"Tyrosine Kinases, RTK)信号通路之\n(RTK-Ras蛋白信号通路)\n通过受体自身的酪氨酸蛋白激酶的激活来完成信\n号跨膜转导的。其信号分子多为一些生长因子。\nSignaling ligands of RTKs\n1.Nerve growth factor 神经生长因子 (NGF)\n2.Platelet-derived growth factor 血小板生长因子\n(PDGF)\n3.Epidermal growth factor 表皮生长(EGF)\n4.insulin and insulin-like GF 胰岛素和类胰岛素(IGF-1)\n5.vascular endothelial factor 血管内皮生长因子(VEGF)\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。","page":19,"level":"掌握","img":"assets/img/ch11/p019.jpg","anim":null,"fig":null,"points":["受体酪氨酸蛋白激酶(RTK)通过受体自身酪氨酸蛋白激酶的激活完成信号跨膜转导","RTK的信号分子多为生长因子，如NGF、PDGF、EGF、胰岛素等"],"check":{"q":"下列属于受体酪氨酸激酶(RTK)信号分子的是？","o":["A. 神经生长因子(NGF)","B. 一氧化氮","C. 乙酰胆碱","D. 肾上腺素"],"a":"A","e":"RTK的信号分子多为生长因子，包括NGF、PDGF、EGF、胰岛素/IGF-1、VEGF等。","oe":["NGF是RTK的典型信号分子，正确。","NO是气体信号分子，直接扩散入细胞。","乙酰胆碱主要作用于GPCR或离子通道受体。","肾上腺素作用于G蛋白偶联受体，不是RTK。"]},"cards":null,"mem":"RTK配体:EGF/PDGF/NGF/VEGF/IGF","big":"assets/img/ch11/big/p019.jpg","terms":[{"t":"RTK","en":"receptor tyrosine kinase","d":"受体酪氨酸蛋白激酶，胞内段具酪氨酸激酶活性，配体多为生长因子。"},{"t":"生长因子配体","en":"NGF / PDGF / EGF / IGF-1 / VEGF","d":"常见的RTK配体，包括神经生长因子、血小板生长因子、表皮生长因子、胰岛素样生长因子、血管内皮生长因子等。"}]},{"i":19,"sec":"4.2 酶联受体","title":"Some subfamilies of RTKs","notes":"【结合课本/笔记】A protein kinaseis an enzyme that modifies other proteins by chemically adding phosphategroups to them (phosphorylation). This usually results in a functionalchange of the target protein (substrate) by changing enzyme activity,cellular location, or association with other proteins.第二信使：是在细胞内的多由胞外信号分子转导的产物，同时又可以介导下一步的信号转\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页标题为“RTK的部分亚家族”（Some subfamilies of RTKs）。RTK即受体酪氨酸激酶（receptor tyrosine kinase），是细胞表面一大类酶联受体，胞内段具酪氨酸激酶活性。原文仅给出标题，说明不同RTK可依据胞外配体结合结构域等差异分为若干亚家族，同类成员结构相似而配体各异。","page":20,"level":"掌握","img":"assets/img/ch11/p020.jpg","anim":null,"fig":null,"points":["受体酪氨酸激酶(RTK)可分为若干亚家族"],"check":{"q":"关于受体酪氨酸激酶(RTK)亚家族的描述，正确的是？","o":["A. 所有RTK的胞外配体结合域和配体完全相同","B. RTK亚家族间无任何结构相似性","C. RTK不属于酶联受体","D. 不同RTK可依胞外配体结合结构域等差异分为若干亚家族"],"a":"D","e":"RTK可依据胞外配体结合结构域等差异分为若干亚家族，同类成员结构相似而配体各异。","oe":["各亚家族配体不同，并非完全相同。","同亚家族成员结构相似，存在相似性。","RTK是典型的酶联受体，认为其不属于是错误的。","RTK可依胞外结构域差异分亚家族，正确。"]},"cards":null,"mem":"RTK是激酶：加磷酸改变底物活性、定位或结合","big":"assets/img/ch11/big/p020.jpg"},{"i":20,"sec":"4.2 酶联受体","title":"The Structure and Activation of a Receptor","notes":"Tyrosine Kinase\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。\n\n【本页英文讲解】\n本页标题为“受体酪氨酸激酶的结构与活化”（The Structure and Activation of a Receptor Tyrosine Kinase）。RTK通常为一次跨膜的膜蛋白：胞外为配体结合区，胞内为酪氨酸激酶结构域。配体结合使两个受体分子二聚化，激酶结构域相互磷酸化（自磷酸化）而被激活，并招募下游信号蛋白，属第九章酶联受体信号转导考点。","page":21,"level":"掌握","img":"assets/img/ch11/p021.jpg","anim":null,"fig":null,"points":["受体酪氨酸激酶(RTK)具有胞外配体结合域、跨膜区和胞内酪氨酸激酶结构域"],"check":{"q":"受体酪氨酸激酶(RTK)被配体激活的关键步骤是？","o":["A. 受体使cAMP磷酸化而被激活","B. 受体二聚化并相互磷酸化(自磷酸化)","C. 受体单体化后与G蛋白结合","D. 受体被蛋白酶切割释放胞内域"],"a":"B","e":"RTK与配体结合后二聚化，激酶结构域相互磷酸化而被激活。","oe":["RTK是蛋白激酶，不作用于cAMP。","正确，配体结合使受体二聚化并自磷酸化而激活。","RTK激活靠二聚化，而非单体化或结合G蛋白。","RTK不被切割释放胞内域来激活。"],"basis":"配体结合使两个受体分子二聚化，激酶结构域相互磷酸化（自磷酸化）而被激活。"},"cards":null,"mem":"RTK一次跨膜：配体促二聚化，胞内激酶自磷酸化激活","big":"assets/img/ch11/big/p021.jpg"},{"i":21,"sec":"4.2 酶联受体","title":"RTK-Ras蛋白信号通路","notes":"1) RTK没有信号分子结合时，以无活性的单体存在。\nIn the inactive state, the RTK receptors are in the membrane\nas monomers, Ras is combined with GDP and is inactive.\n2) 信号分子与受体结合，2个单体受体分子在膜上聚和成二聚体。\n二聚化受体酪氨酸残基互相磷酸化：自身磷酸化而激活。\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。","page":22,"level":"掌握","img":"assets/img/ch11/p022.jpg","anim":null,"fig":null,"points":["RTK无信号分子结合时以无活性单体存在，Ras与GDP结合而无活性","信号分子与受体结合后，2个单体受体分子在膜上聚合成二聚体","二聚化受体酪氨酸残基互相磷酸化(自身磷酸化)而激活"],"check":{"q":"信号分子与RTK结合后，二聚化受体的酪氨酸残基发生的变化是？","o":["A. 被泛素化降解","B. 被甲基化修饰","C. 相互磷酸化即自身磷酸化而激活","D. 去磷酸化而失活"],"a":"C","e":"RTK二聚后酪氨酸残基发生自身磷酸化，从而被激活。","oe":["配体结合使其激活，并非直接降解。","该过程为磷酸化，与甲基化无关。","正确，二聚化受体酪氨酸残基互相磷酸化而激活。","激活需要磷酸化，不是去磷酸化。"],"basis":"二聚化受体酪氨酸残基互相磷酸化：自身磷酸化而激活。"},"cards":null,"mem":"静息RTK单体+Ras-GDP；配体→二聚化自磷酸化激活","big":"assets/img/ch11/big/p022.jpg"},{"i":22,"sec":"4.2 酶联受体","title":"RTK经接头蛋白Grb2-SOS激活Ras","notes":"RTK激活Ras的过程：③接头蛋白Grb2的SH2结构域与活化的酪氨酸激酶(RTK的磷酸酪氨酸)结合；Grb2的SH3结构域为Ras激活蛋白SOS(鸟苷酸交换因子GEF)提供结合位点。SOS作为GEF，促进Ras上的GDP换成GTP，从而激活Ras。","page":23,"level":"掌握","img":"assets/img/ch11/p023.jpg","anim":null,"fig":null,"points":["接头蛋白Grb2的SH2结构域与活化的酪氨酸激酶结合","Grb2的SH3结构域为Ras激活蛋白SOS(鸟苷酸交换因子GEF)提供结合位点"],"check":{"q":"在RTK激活Ras的过程中，SOS的功能是？","o":["A. 作为酪氨酸激酶磷酸化Ras","B. 作为鸟苷酸交换因子(GEF)激活Ras","C. 作为磷酸二酯酶水解cAMP","D. 作为接头蛋白结合SH2结构域"],"a":"B","e":"Grb2的SH2结合受体的磷酸酪氨酸，SH3招募SOS；SOS作为GEF激活Ras。","oe":["SOS不是激酶，而是交换因子。","正确，SOS是Ras激活蛋白，即鸟苷酸交换因子。","SOS与cAMP的代谢过程没有直接关系。","结合SH2结构域的是接头蛋白Grb2。"],"basis":"SH3结构域为Ras激活蛋白SOS－鸟苷酸交换因子(GEF)提供结合位点。"},"cards":null,"mem":"Grb2：SH2接磷酸化RTK，SH3接SOS(GEF)","big":"assets/img/ch11/big/p023.jpg"},{"i":23,"sec":"4.2 酶联受体","title":"GRB2蛋白","notes":"(growth factor receptor-bound protein 2)\n唯一功能作为接头分子(adaptor)将其它蛋白连\n接到一个复合体中。其中一个结构域(SH2)与磷酸化的\nRTK结合，另一个结构域(SH3)与一个叫SOS的蛋白结\n合。\nSH2/SH3结构域特点：\n高度保守，无酶的催化活性\nThe SH2 domain is a compact,\n“plug-in” module(模块)\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。","page":24,"level":"掌握","img":"assets/img/ch11/p024.jpg","anim":null,"fig":null,"points":["Grb2唯一功能是作为接头分子(adaptor)，将其他蛋白连接到一个复合体中","其SH2结构域与磷酸化的RTK结合，SH3结构域与SOS结合","SH2/SH3结构域高度保守，无酶的催化活性"],"check":{"q":"关于接头蛋白Grb2，下列叙述正确的是？","o":["A. 具有激酶催化活性，可磷酸化SOS","B. 通过SH3结构域直接结合磷酸化RTK","C. 本身即为鸟苷酸交换因子，能直接激活Ras","D. 唯一功能是作接头分子，其SH2/SH3高度保守且无酶活性"],"a":"D","e":"Grb2是纯接头分子，仅把其它蛋白连成复合体，其SH2/SH3结构域高度保守但无酶的催化活性。","oe":["Grb2无催化活性，不能磷酸化SOS。","SH2结合磷酸化RTK，SH3结合SOS，方向相反。","Grb2不是GEF，SOS才是鸟苷酸交换因子。","Grb2仅作接头，SH2/SH3无酶活性，正确。"]},"cards":null,"mem":"Grb2接头蛋白：SH2接RTK、SH3接SOS","big":"assets/img/ch11/big/p024.jpg","terms":[{"t":"Grb2","en":"growth factor receptor-bound protein 2","d":"只作接头分子(adaptor)的蛋白：SH2结合磷酸化RTK、SH3结合SOS。"},{"t":"SH2 / SH3 结构域","en":"SH2 / SH3 domain","d":"高度保守、无催化活性的蛋白相互作用模块，介导信号蛋白间的识别与组装。"}]},{"i":24,"sec":"4.2 酶联受体","title":"• src 基因首先在鸡肉瘤病毒（Rous sarcoma virus）中发现","notes":"SH (Src homolog region)\nOrganization of human Src. CL, catalytic loop; AS, activation segment\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页讲SH区与Src蛋白。SH为Src同源区（Src homolog region），src基因最初在鸡肉瘤病毒（Rous sarcoma virus）中发现。Src位于胞质中，属非受体型酪氨酸激酶。SH1为激酶活性区，SH2选择性结合磷酸化Tyr（酪氨酸）残基，SH3选择性结合富含Pro（脯氨酸）序列，图注另有CL（催化环）与AS（活化段）。","page":25,"level":"掌握","img":"assets/img/ch11/p025.jpg","anim":null,"fig":null,"points":["Src位于胞质中，属于非受体型TK (tyrosine kinase)","SH1 激酶活性区","SH2 选择性结合磷酸化的Tyr残基","SH3 选择性结合富含Pro的序列"],"check":{"q":"关于Src蛋白及其SH结构域，叙述正确的是（　）","o":["A. SH3结构域选择性结合磷酸化的酪氨酸残基","B. Src位于胞质中，属非受体型酪氨酸激酶","C. SH2结构域选择性结合富含脯氨酸的序列","D. Src为跨膜受体型酪氨酸激酶，含胞外配体结合区"],"a":"B","e":"src基因最初在鸡肉瘤病毒中发现；Src位于胞质中，属非受体型酪氨酸激酶，其SH1为激酶活性区，SH2选择性结合磷酸化Tyr残基，SH3选择性结合富含Pro的序列。","oe":["错误：SH3识别富含Pro序列，结合磷酸化Tyr残基的是SH2。","正确：Src位于胞质中，属于非受体型酪氨酸激酶（TK）。","错误：SH2结合磷酸化Tyr残基，结合富含Pro序列的是SH3。","错误：Src为非受体型酪氨酸激酶，并非跨膜受体。"]},"cards":null,"mem":"Src:SH1激酶/SH2认Tyr/SH3认Pro","big":"assets/img/ch11/big/p025.jpg","terms":[{"t":"Src","en":"Src","d":"首次在鸡肉瘤病毒中发现的酪氨酸激酶癌基因产物；SH结构域即Src同源区。"}]},{"i":25,"sec":"4.2 酶联受体","title":"信号分子间的识别结构域⎯SH结构域","notes":"介导信号分子的相互识别和连接，形成不同的转导途\n径。\ndomain)简称，其中\n●SH2结构域选择性紧密结合磷酸化的酪氨酸残基，\n形成多蛋白复合体参与细胞信号转导。\n●SH3识别并结合富含Pro(脯氨酸) 的蛋白序列，介\n导蛋白与蛋白间的相互作用。\n注：Src是一种原癌基因，最早在Rous肉瘤病毒\n(Rous sarcoma virus)中发现","page":26,"level":"掌握","img":"assets/img/ch11/p026.jpg","anim":null,"fig":null,"points":["SH结构域是Src同源结构域 (Src homology"],"check":{"q":"关于信号分子间的SH结构域，叙述正确的是（　）","o":["A. SH结构域又称酪氨酸激酶结构域，均具催化活性","B. SH2识别并结合富含脯氨酸的蛋白序列","C. SH3选择性结合磷酸化的酪氨酸残基","D. SH2选择性结合磷酸化酪氨酸残基，介导多蛋白复合体形成"],"a":"D","e":"SH结构域即Src同源结构域，介导信号分子的相互识别和连接；SH2选择性结合磷酸化酪氨酸残基、形成多蛋白复合体，SH3则识别富含脯氨酸序列介导蛋白间相互作用。","oe":["错误：SH为Src同源结构域，主要介导识别连接，并非均具催化活性。","错误：识别并结合富含Pro序列的是SH3，而非SH2。","错误：SH3识别富含Pro序列，不结合磷酸化酪氨酸残基。","正确：SH2选择结合磷酸化酪氨酸残基，形成多蛋白复合体。"]},"cards":null,"mem":"SH2挽磷酸化Tyr，SH3抓富Pro序列，介导蛋白互作","big":"assets/img/ch11/big/p026.jpg"},{"i":26,"sec":"4.2 酶联受体","title":"Ras 蛋白：大鼠肉瘤(rat sarcoma, Ras)的英文缩写，是原癌基","notes":"因Ras的表达产物，分子量21kDa，属单体小G-蛋白，具弱\nGTPase活性，通过结合GTP/GDP相互转换被激活、灭活。\nSOS (son of sevenless):\n是Ras(一种小G蛋白)的激活蛋白－GEF\n即Sos是一种鸟苷酸释放因子，刺激GDP从Ras中释放出来，\n细胞溶质中的GTP进而与之结合，活化Ras。\nSevenless: 果蝇中鉴定出的一种与光受体分化有关的基因","page":27,"level":"掌握","img":"assets/img/ch11/p027.jpg","anim":null,"fig":null,"points":["Ras是大鼠肉瘤(rat sarcoma)的英文缩写，是原癌基因Ras的表达产物","分子量21kDa，属单体小G-蛋白，具弱GTPase活性，通过结合GTP/GDP相互转换被激活或灭活","SOS是Ras的激活蛋白(GEF)，刺激GDP从Ras释放、GTP进而结合，活化Ras"],"check":{"q":"关于Ras蛋白的叙述，正确的是？","o":["A. 属异三聚体G蛋白，分子量约21kDa","B. 属单体小G蛋白，具弱GTPase活性，通过GTP/GDP转换激活","C. 由SOS直接磷酸化而激活","D. 与GTP结合时失活，与GDP结合时激活"],"a":"B","e":"Ras是原癌基因产物，分子量21kDa，为单体小G蛋白，具弱GTPase活性，GTP结合态为激活态。","oe":["Ras是单体小G蛋白，不是异三聚体G蛋白。","21kDa单体小G蛋白，靠GTP/GDP转换，正确。","SOS是GEF，促GDP/GTP交换而非磷酸化Ras。","结合GTP为激活态、结合GDP为失活态，说反了。"]},"cards":null,"mem":"Ras=21kDa小G蛋白原癌基因；SOS为GEF","big":"assets/img/ch11/big/p027.jpg","terms":[{"t":"Ras","en":"rat sarcoma, Ras","d":"21kDa的单体小G蛋白，原癌基因Ras的产物，结合GTP时激活、结合GDP时失活。"},{"t":"SOS","en":"son of sevenless","d":"Ras的鸟苷酸交换因子(GEF)，催化GDP从Ras释放、GTP结合而激活Ras。"}]},{"i":27,"sec":"4.2 酶联受体","title":"Ras 蛋白","notes":"Ras：rat sarcoma；GTPase 开关蛋白\n分子单体GTP 结合蛋白，具有GTPase 活性，分布于质膜胞质一侧，\n结合GTP 时呈活化态，而结合GDP 时呈失活态\nGDP 的释放需要鸟苷酸交换因子（GEF）参与；\n【结合课本/笔记】核孔复合体的功能●核质交换的双向性亲水通道核孔复合体物质运输功能示意图爪蟾卵母细胞核质蛋白注射实验●通过核孔复合体的主动运输●亲核蛋白与核定位信号●亲核蛋白入核转运的步骤●转录产物RNA的核输出通过核孔复合体的主动运输生物大分子的核质分配主要是通过核孔复合体的主动运输完成的，具有高度的选择性，并且是双向的。选择性表现在以下三个方面：●对运输颗粒大小的限制：有效功能直径可被调节约10～20nm，甚至可达26nm，●主动运输是一个信号识别与载体介导的过程，需要消耗能量，并表现出饱和动力学特征●主动运输具有双向性，即核输入与核输出亲核蛋白与核定位信号●亲核蛋白（karyophilic protein）在细胞质内合成后，需要或能够进入细胞核","page":28,"level":"掌握","img":"assets/img/ch11/p028.jpg","anim":null,"fig":null,"points":["Ras 蛋白（21KD）是Ras 基因表达产物，是由190 个氨基酸残基组成的小","Ras 蛋白从失活态到活化态的转变，先要GDP 释放才有GTP 的结合，","Ras 蛋白从活化态到失活态的转变，则要GTP 酶活化蛋白（GAP）的促进"],"check":{"q":"关于Ras蛋白的叙述，正确的是（　）","o":["A. 由α、β、γ三亚基组成，位于细胞核内","B. 结合GDP时呈活化态，GTP水解使其活化","C. 结合GTP时呈活化态，其GDP的释放需要鸟苷酸交换因子参与","D. 无内源GTPase活性，活化后不能自行失活"],"a":"C","e":"Ras是单体GTP结合蛋白（GTPase开关蛋白），分布于质膜胞质一侧；结合GTP时活化、结合GDP时失活，GDP的释放需鸟苷酸交换因子（GEF）参与。","oe":["错误：Ras为单体G蛋白，分布于质膜胞质一侧而非核内。","错误：Ras结合GDP时失活，结合GTP时才呈活化态。","正确：Ras结合GTP为活化态，GDP释放需鸟苷酸交换因子（GEF）参与。","错误：Ras具GTPase活性，GAP可促进其水解GTP而失活。"]},"cards":null,"mem":"Ras：GTP活/GDP静，GEF释放、GAP水解失活","big":"assets/img/ch11/big/p028.jpg"},{"i":28,"sec":"4.2 酶联受体","title":"Grb2-Sos诱导Ras上GTP与GDP交换","notes":"exchange of GTP for GDP\non Ras/GDP→Ras-GTP.\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页为Ras激活步骤第4步：Grb2-Sos诱导Ras上的GDP与GTP交换，使Ras-GDP转变为Ras-GTP。衔接蛋白Grb2通过SH2结合活化RTK的磷酸化酪氨酸，再借助其所结合的Sos（一种鸟苷酸交换因子）催化Ras释放GDP、结合GTP而被激活。Ras是重要的原癌基因产物，该活化是RTK-Ras-MAPK通路的枢纽，属高频考点。","page":29,"level":"掌握","img":"assets/img/ch11/p029.jpg","anim":null,"fig":null,"points":["Grb2-Sos诱导Ras上GTP与GDP的交换","使Ras-GDP转变为Ras-GTP而激活"],"check":{"q":"Ras激活第4步中，Grb2-Sos的作用是？","o":["A. 将Ras募集到细胞核内","B. 直接磷酸化Ras使其激活","C. 使Ras上GDP被GTP交换，Ras-GDP转为Ras-GTP","D. 使Ras上GTP被GDP交换，使Ras失活"],"a":"C","e":"衔接蛋白Grb2经SH2结合活化RTK，其所结合的Sos是鸟苷酸交换因子，催化Ras释放GDP并结合GTP而被激活。","oe":["Ras活化在质膜内侧进行，并非入核。","Ras激活靠核苷酸交换，不是被磷酸化。","Sos催化GDP/GTP交换生成活化Ras-GTP，正确。","交换方向相反，Sos促使GTP取代GDP。"]},"cards":null,"mem":"Grb2-Sos催化Ras-GDP换成Ras-GTP","big":"assets/img/ch11/big/p029.jpg"},{"i":29,"sec":"4.2 酶联受体","title":"Raf 蛋白","notes":"MAPKKK\nMAPKK\n5. 激活的Ras进入一系列\n与有丝分裂原活化蛋白激\n酶(mitogen-activated\nprotein kinase, MAPK) 的   MAPK\n磷酸化的联级放大反应\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页讲解】\n本页讲解Raf蛋白及MAPK级联信号通路。图中标注MAPKKK、MAPKK、MAPK三个层级，Raf属于MAPKKK。当Ras被激活后，进入一系列与有丝分裂原活化蛋白激酶（mitogen-activated protein kinase, MAPK）相关的磷酸化级联放大反应。该通路是酶联受体（受体酪氨酸激酶）下游的经典增殖信号。考点联系翟中和《细胞生物学》第九章第四节酶联受体介导的信号转导，需掌握Ras→Raf（MAPKKK）→MAPKK→MAPK的级联顺序及逐级放大意义。","page":30,"level":"掌握","img":"assets/img/ch11/p030.jpg","anim":null,"fig":null,"points":["激活的Ras启动Raf(MAPKKK)→MAPKK→MAPK的磷酸化联级放大反应","该通路与有丝分裂原活化蛋白激酶(MAPK)相关"],"check":{"q":"在Ras-MAPK级联通路中，Raf蛋白属于？","o":["A. MAPK","B. MAPKKK","C. MAPKK","D. 鸟苷酸交换因子"],"a":"B","e":"Raf属于MAPKKK，该级联顺序为Ras→Raf(MAPKKK)→MAPKK→MAPK，逐级磷酸化并放大信号。","oe":["MAPK是最下游被MAPKK磷酸化的激酶。","Raf属MAPKKK，位于级联最上游，正确。","MAPKK在Raf下游，由Raf磷酸化激活。","Raf是蛋白激酶，不是鸟苷酸交换因子。"]},"cards":null,"mem":"Ras→Raf→MAPKK→MAPK级联放大","big":"assets/img/ch11/big/p030.jpg","terms":[{"t":"Raf","en":"Raf","d":"丝氨酸/苏氨酸激酶(MAPKKK)，被Ras激活后启动MAPK级联。"},{"t":"MAPK","en":"mitogen-activated protein kinase","d":"有丝分裂原活化蛋白激酶，级联末端激酶，可入核调节基因表达。"}]},{"i":30,"sec":"4.2 酶联受体","title":"Cells seem to require two types of signals to proliferate.","notes":"In order to multiply successfully, most\nnormal cells require both extracellular\nsignals that drive cell-cycle\nprogression(mitogen) and extracellular\nsignals that drive cell growth (growth\nfactor)\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页标题说明细胞增殖似乎需要两类信号。原文指出：大多数正常细胞要成功增殖，既需要驱动细胞周期推进的胞外信号，即促分裂原/有丝分裂原（mitogen），也需要驱动细胞生长的胞外信号，即生长因子（growth factor）。二者功能不同：促分裂原推动细胞周期运行，生长因子促进细胞体积增大与物质积累，正常细胞需同时具备两类信号才能完成分裂。","page":31,"level":"掌握","img":"assets/img/ch11/p031.jpg","anim":null,"fig":null,"points":["大多数正常细胞成功增殖需要两类细胞外信号","一类驱动细胞周期进程(有丝分裂原mitogen)，一类驱动细胞生长(生长因子growth factor)"],"check":{"q":"大多数正常细胞成功增殖需要哪两类胞外信号？","o":["A. 两类信号均为生长因子，作用完全相同","B. 仅需促分裂原一种信号即可完成增殖","C. 促分裂原驱动细胞周期，生长因子驱动细胞生长","D. 促分裂原驱动细胞生长，生长因子驱动细胞周期"],"a":"C","e":"正常细胞既需促分裂原(mitogen)推动细胞周期运行，又需生长因子(growth factor)促进细胞生长与物质积累。","oe":["两类信号功能不同，生长因子不能等同看待。","仅有促分裂原不足，还必需生长因子。","促分裂原管周期、生长因子管生长，正确。","两者功能说反，促分裂原才推动细胞周期。"]},"cards":null,"mem":"增殖需mitogen推周期+生长因子促生长","big":"assets/img/ch11/big/p031.jpg","terms":[{"t":"促分裂原","en":"mitogen","d":"驱动细胞周期进程的细胞外信号；正常细胞增殖既需促分裂原又需生长因子。"}]},{"i":31,"sec":"4.2 酶联受体","title":"RTK-Ras影响细胞的生长、增殖","notes":"白磷酸化，其中包括一种重要的有丝分裂原活化的蛋\n白激酶(mitogen-activated protein kinase, MAPK) 。\n(Myc等)，增强特异基因的转录来调节细胞的生长、\n增殖。\nMyc is thought to promote cell-cycle entry by several\nmechanisms, one is to increase the expression of genes\nencoding G1 cyclins (cyclin D)，thereby increasing G1-\nCdk (cyclin D/Cdk4) activity.\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。\n\n【本页英文讲解】\n本页讲RTK-Ras影响细胞的生长、增殖。活化的Ras-GTP通过其他信号分子使下游许多蛋白磷酸化，其中包括有丝分裂原活化的蛋白激酶（MAPK）。活化MAPK进入细胞核，磷酸化转录因子（如Myc等），增强特异基因转录以调节生长、增殖。原文还指出Myc可增加编码G1期周期蛋白（cyclin D）基因表达，提高G1-Cdk（cyclin D/Cdk4）活性。","page":32,"level":"掌握","img":"assets/img/ch11/p032.jpg","anim":null,"fig":null,"points":["活化的Ras-GTP通过其它信号分子使下游的许多蛋","活化的MAPK进入细胞核，通过磷酸化转录因子"],"check":{"q":"RTK-Ras信号通路促进细胞生长与增殖，其机制正确的是（　）","o":["A. MAPK在胞质中降解cyclin D从而促进细胞周期","B. 活化的MAPK进入细胞核，磷酸化Myc等转录因子增强基因转录","C. 活化Ras直接进入细胞核与DNA结合启动转录","D. Ras-GTP抑制MAPK，阻断有丝分裂原活化的蛋白激酶"],"a":"B","e":"活化的Ras-GTP使下游许多蛋白磷酸化，其中包括MAPK；活化MAPK进入细胞核磷酸化Myc等转录因子，增强特异基因转录，Myc还能增加cyclin D表达提高G1-Cdk活性。","oe":["错误：Myc增加cyclin D表达，MAPK并非降解cyclin D。","正确：活化MAPK入核，磷酸化Myc等转录因子，增强特异基因转录。","错误：入核发挥作用的是MAPK，Ras在质膜内侧传递信号，不直接结合DNA。","错误：Ras活化后激活而非抑制MAPK。"]},"cards":null,"mem":"活化MAPK入核→磷酸化Myc→增G1-cyclinD","big":"assets/img/ch11/big/p032.jpg"},{"i":32,"sec":"4.2 酶联受体","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• mitogen receptor —— 促分裂原受体\n• Ras / MAP kinase —— Ras / MAP激酶\n• activation of transcription regulatory protein —— 转录调节蛋白激活\n• immediate early gene expression (Myc) —— 即刻早期基因表达(Myc)\n• delayed-response gene expression —— 延迟反应基因表达\n• active G1-Cdk / G1/S-Cdk / S-Cdk —— 活化G1-Cdk / G1/S-Cdk / S-Cdk\n• Rb / E2F / P —— Rb / E2F / 磷酸化\n• positive feedback —— 正反馈\n• S-phase gene transcription / DNA synthesis —— S期基因转录 / DNA合成\n【读图讲解】\n信号级联图：丝裂原受体→Ras→MAP激酶→转录调节蛋白→早期即刻基因(Myc)→迟反应基因→G1-Cdk；活化的 G1-Cdk 磷酸化 Rb 释放 E2F，经正反馈启动 S 期基因转录(cyclin E/A、S-Cdk)。考点：G1/S 转换与 Rb-E2F 正反馈。","page":33,"level":"掌握","img":"assets/img/ch11/p033.jpg","anim":null,"fig":null,"points":["mitogenreceptor","Ras","MAPkinase","CYTOSOL","NUCLEUS","immediateearly","geneexpression","transcription"],"check":{"q":"在丝裂原-Ras-MAPK通路中，活化的G1-Cdk如何推动G1/S转换？","o":["A. 去磷酸化Rb使其结合E2F，启动S期基因转录","B. 抑制Myc等即刻早期基因的表达","C. 直接磷酸化E2F使其失活","D. 磷酸化Rb使其释放E2F，启动S期基因转录"],"a":"D","e":"活化的G1-Cdk磷酸化Rb，使E2F释放，经正反馈启动S期基因(cyclin E/A、S-Cdk)转录，推动G1/S转换。","oe":["低磷酸化Rb才结合E2F，磷酸化后释放E2F。","该通路促进而非抑制Myc等即刻早期基因。","E2F被释放而激活，不是被磷酸化失活。","Cdk磷酸化Rb、释放E2F、启动S期基因，正确。"]},"cards":null,"mem":"Ras→MAPK→Myc→G1-Cdk→Rb→E2F","big":"assets/img/ch11/big/p033.jpg","terms":[{"t":"Myc","en":"Myc","d":"即刻早期基因编码的转录因子，促进细胞增殖，是重要的原癌基因产物。"}]},{"i":33,"sec":"4.2 酶联受体","title":"(原癌基因)","notes":"Ras, small GTPase (G-protein)\n12或61位残基发生点突变），抑制Ras本身GTPase\n的活性，不能使Ras-GTP水解转化为Ras-GDP,导致\nRas长期处于活性状态，不停地激活下游信号，引起\n细胞异常增殖。●编码Ras蛋白的ras基因为原癌基因。\nThe ras gene is known to be mutated in about\none in five human cancers.\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 原癌基因（proto-oncogene）：正常细胞基因组中存在与病毒癌基因相似的一类基因，\f产物是正常细胞增殖所必不可少的，突变为癌基因则导致细胞生长失控。\n\n【本页讲解】\n本页讲解小G蛋白Ras与原癌基因（proto-oncogene）。Ras是small GTPase（G蛋白），也是第一个被分离并测序的原癌基因。在约25%~30%的人肿瘤中可发现异常Ras蛋白，其第12或61位残基发生点突变，抑制Ras本身的GTPase活性，使Ras-GTP不能水解转化为Ras-GDP，导致Ras长期处于活性状态，持续激活下游信号，引起细胞异常增殖。原文还指出约五分之一的人类癌症中ras基因发生突变。考点联系翟中和《细胞生物学》第十四章细胞增殖调控与癌细胞。","page":34,"level":"掌握","img":"assets/img/ch11/p034.jpg","anim":null,"fig":null,"points":["the first isolated and sequenced proto-oncogene","在25％~30％的人肿瘤中，发现异常的Ras蛋白（其"],"check":{"q":"ras原癌基因突变导致细胞异常增殖的机制是（　）","o":["A. 第12或61位残基点突变使Ras持续处于GTP结合的活性状态","B. 突变增强Ras的GTPase活性，加速GTP水解","C. 突变使Ras转变为肿瘤抑制基因的产物","D. 突变使Ras无法结合GTP，信号通路被关闭"],"a":"A","e":"Ras蛋白第12或61位残基发生点突变后，其GTPase活性被抑制，Ras-GTP不能水解为Ras-GDP，Ras长期处于活性状态，持续激活下游信号引起细胞异常增殖。","oe":["正确：点突变抑制Ras的GTPase活性，使Ras长期保持GTP结合的活性态。","错误：突变是抑制而非增强Ras的GTPase活性。","错误：ras为原癌基因，突变后成为癌基因，不变成抑癌基因。","错误：突变使Ras不能水解GTP，持续激活下游信号而非关闭。"]},"cards":null,"mem":"Ras第12/61位突变→GTPase失活→持续活化致癌","big":"assets/img/ch11/big/p034.jpg"},{"i":34,"sec":"4.2 酶联受体","title":"胰岛素受体(RTK)经IRS激活下游信号","notes":"胰岛素受体是受体酪氨酸激酶(RTK)，呈2α2β四聚体，被激活后自身磷酸化；同时将胰岛素受体底物(insulin receptor substrate, IRS)磷酸化。磷酸化的IRS结合或激活含有SH2结构域的蛋白质，其中包括Grb2，从而启动下游信号途径。","page":35,"level":"掌握","img":"assets/img/ch11/p035.jpg","anim":null,"fig":null,"points":["胰岛素受体是RTK，为2α2β四聚体，被激活后自身磷酸化","同时将胰岛素受体底物(IRS)磷酸化","IRS结合或激活含SH2结构域的蛋白质，其中包括Grb2"],"check":{"q":"关于胰岛素受体的叙述，正确的是？","o":["A. 是胞内受体，与胰岛素结合后入核","B. 属RTK，为2α2β四聚体，自身磷酸化后磷酸化IRS","C. 激活后直接结合SOS，不依赖接头蛋白","D. 属G蛋白偶联受体，为7次跨膜单体"],"a":"B","e":"胰岛素受体是受体酪氨酸激酶，呈2α2β四聚体，配体结合后自身磷酸化，并磷酸化胰岛素受体底物IRS，进而招募含SH2的蛋白。","oe":["胰岛素受体是膜受体，并非胞内受体。","2α2β四聚体RTK自身磷酸化并磷酸化IRS，正确。","需IRS及含SH2接头蛋白如Grb2参与，不直接结合SOS。","胰岛素受体是RTK，不是G蛋白偶联受体。"]},"cards":null,"mem":"胰岛素受体2α2β自磷酸化→磷酸化IRS→招Grb2","big":"assets/img/ch11/big/p035.jpg","terms":[{"t":"IRS","en":"insulin receptor substrate","d":"胰岛素受体底物，被胰岛素受体磷酸化后招募含SH2结构域的蛋白。"}]},{"i":35,"sec":"4.2 酶联受体","title":"Insulin胰岛素受体也属于酪氨酸激酶受体","notes":"IRS： insulin receptor substrate, 胰岛素受体底物\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。\n\n【本页讲解】\n本页讲解胰岛素受体（Insulin receptor）属于酪氨酸激酶受体（RTK）及RTK信号转导。胰岛素受体本身具有酪氨酸激酶活性，与胰岛素结合后被激活，进而招募并磷酸化胰岛素受体底物（IRS，insulin receptor substrate）。IRS作为接头蛋白继续向下游传递信号，是胰岛素信号通路的关键环节。考点联系翟中和《细胞生物学》第九章第四节酶联受体介导的信号转导，需掌握RTK的配体结合、二聚化与自磷酸化、底物招募等步骤，理解胰岛素受体介导的代谢调控。","page":36,"level":"掌握","img":"assets/img/ch11/p036.jpg","anim":null,"fig":null,"points":["RTK signal"],"check":{"q":"胰岛素受体介导信号转导的过程，正确的是（　）","o":["A. IRS是一种GTP酶，水解GTP后终止信号","B. 受体具酪氨酸激酶活性，激活后招募并磷酸化IRS","C. 受体为G蛋白偶联受体，激活后产生cAMP","D. 胰岛素受体属胞内受体，可直接调控基因转录"],"a":"B","e":"胰岛素受体属于酪氨酸激酶受体（RTK），本身具酪氨酸激酶活性，与胰岛素结合后被激活，进而招募并磷酸化胰岛素受体底物（IRS），IRS作为接头蛋白继续向下游传递信号。","oe":["错误：IRS是胰岛素受体底物、接头蛋白，并非GTP酶。","正确：胰岛素受体本身具酪氨酸激酶活性，激活后招募并磷酸化IRS。","错误：胰岛素受体属酪氨酸激酶受体（RTK），并非GPCR。","错误：胰岛素受体位于细胞膜上，并非胞内受体。"]},"cards":null,"mem":"胰岛素受体属RTK，磷酸化IRS接头向下游传信号","big":"assets/img/ch11/big/p036.jpg"}],"mcq":[{"id":"ch11_mcq_2","mod":"4.2 酶联受体","modI":2,"q":"不属于蛋白酪氨酸激酶类型的受体是（            ）。","o":["A．EGF 受体","B．PDGF 受体","C．TGFβ受体","D．IGF-1 受体"],"a":"C","e":"TGFβ受体即转化生长因子β受体，为受体丝氨酸／苏氨丝氨激酶。","kp":"ch11_s2_35","oe":["EGF受体属受体酪氨酸激酶，故不符合题意。","PDGF受体属受体酪氨酸激酶，故不符合题意。","TGFβ受体为丝氨酸/苏氨酸激酶受体，不属酪氨酸激酶，故正确。","IGF-1受体属受体酪氨酸激酶，故不符合题意。"]}],"judge":[{"id":"ch11_judge_5","modI":2,"q":"酪氨酸磷酸化用来构建结合部位，用于其他蛋白质与受体酪氨酸激酶的结合。（         ）","a":"对","e":"","kp":"ch11_s2_35","oe":["受体酪氨酸激酶自磷酸化形成SH2等结合位点，供下游蛋白识别结合。","误以为酪氨酸磷酸化与蛋白结合无关，其实它正是构建停泊位点的方式。"]},{"id":"ch11_judge_10","modI":2,"q":"Ras 蛋白被 SOS 激活后，可激活其下游的 MEK 激酶，再通过激活的 MEK 激酶将 Raf 激 酶激活，引起级联反应。（                ）","a":"错","e":"叙述该信号转导的顺序有误，应为 Ras→Raf→MEK。","kp":"ch11_s2_29","oe":["误把Ras下游顺序记为Ras→MEK→Raf，故判对。","正确的MAPK级联顺序为Ras→Raf→MEK→ERK，题干顺序颠倒。"]}],"fill":[{"id":"ch11_fill_8","modI":2,"q":"生长因子属于______信号分子，不能穿过靶细胞质膜的______。通过与靶细胞表面的 ______结合再经信号转导机制，在细胞内产生______或激活______或______的活性，引起细 胞的应答反应。","a":"亲水性；脂双分子层；受体；第二信使；蛋白激酶；蛋白磷酸酶","kp":"ch11_s2_17","oe":["生长因子是亲水性信号分子，不能直接进入细胞","它不能穿过靶细胞质膜的脂双分子层","需与靶细胞膜表面的特异性受体结合","经信号转导在细胞内产生第二信使","或激活蛋白激酶的活性来传递信号","或激活蛋白磷酸酶，从而引起细胞应答"]},{"id":"ch11_fill_10","modI":2,"q":"30％的人类恶性肿瘤是因为突变的______蛋白能与______合，但不能将其水解为______， 而使这种突变的蛋白一直处于开启状态。","a":"Ras；GTP；GDP","kp":"ch11_s2_33","oe":["突变的是Ras蛋白，属原癌基因产物","突变Ras能与GTP结合但丧失GTPase活性","不能将GTP水解为GDP，故持续处于开启状态"]},{"id":"ch11_fill_11","modI":2,"q":"酪氨酸蛋白激酶联系的受体______，但是它的胞内区域具有______，也就是说它的活性 依赖于______。","a":"本身不具备酶活性；酪氨酸蛋白激酶的结合位点；非受体酪氨酸蛋白激酶","kp":"ch11_s2_18","oe":["酪氨酸蛋白激酶联系的受体本身不具备酶活性","其胞内区具有酪氨酸蛋白激酶的结合位点","其活性依赖于非受体酪氨酸蛋白激酶"]},{"id":"ch11_fill_14","modI":2,"q":"受体修饰是细胞适应的一种方式，机理是：①______；或是②______。","a":"受体被磷酸化后失去与信号分子结合的能力；受体被磷酸化易与抑制物结合而失去 与信号分子结合的能力","kp":"ch11_s2_26","oe":["受体被磷酸化后失去与信号分子结合的能力","受体磷酸化后易与抑制物结合而失去结合能力"]},{"id":"ch11_fill_15","modI":2,"q":"cGMP 信号通路是酶联受体的一种，受体本身就是______酶。其细胞外部分有信号分子 结合的位点，细胞内部分有一______酶结构域，活化后可催化 GTP 生成 cGMP。 在这个系统中，cGMP 与______系统中的 cAMP 一样都充当第二信使。另外一个研究得比较 清楚的酶联受体信号系统就是 EGF 信号通路。EGF 受体是一种______，分子质量为 170 kDa， 广泛分布于哺乳动物细胞的上皮细胞、人成纤维细胞、胶质细胞、角质细胞等。EGF 受体 是一条含有 1186 个氨基酸的多肽链，由______个结构域组成：即 EGF 结合结构域、______ 和蛋白激酶活性区域。EGF 信号解除是通过胞吞作用进行的，EGF 被吞入后，      再运送至______。 Ras 蛋白的激活与 EGF 信号有关。Ras 蛋白是原癌基因 c-ras 表达的产物，也是一种______ 蛋白，具有鸟苷结合位点。对细胞的生长、分化、细胞骨架、蛋白质运输和分泌等功能产生 调节和影响。在正常情况下，Ras 蛋白基本上都与______结合在一起，定位在细胞膜内表面 上。当 EGF 与受体结合后，受体细胞质面的酪氨酸蛋白激酶被激活后______作用于 Ras 蛋 白，使 Ras 蛋白立即解离______，而与______结合，处于活化状态并发出刺激细胞生长的信 号。","a":"鸟苷环化；鸟苷环化；PKA；糖蛋白；三；跨膜区；溶酶体；G；GDP；间接；GDP； GTR","kp":"ch11_s2_17","oe":["cGMP通路中受体本身即鸟苷环化酶","其胞内部分含鸟苷环化酶结构域，催化GTP生成cGMP","cGMP与PKA通路中的cAMP一样充当第二信使","EGF受体是一种跨膜糖蛋白，分布广泛","EGF受体由三个结构域组成，各司其职","即EGF结合结构域、跨膜区和蛋白激酶活性区","EGF被吞入后经胞吞运送至溶酶体降解","Ras是原癌基因表达的G蛋白（GTP结合蛋白）","正常情况下Ras与GDP结合，定位在膜内表面","活化的受体经接头蛋白间接作用于Ras","使Ras蛋白立即解离所结合的GDP","Ras转而与GTP结合，处于活化状态"]}],"short":[{"id":"ch11_short_10","modI":2,"q":"概述酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点和功能。","a":"（1）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点 ①受体酪氨酸蛋白激酶：是由 50 多种跨膜受体组成的超家族，其胞外配体是可溶性或膜结 合的多肽或蛋白类激素，包括胰岛素和多种生长因子。胞外配体与受体胞外区结合后，受体 发生二聚化并催化胞内区酪氨酸残基自身磷酸化，进而活化 RTK。磷酸化的酪氨酸可被一 类含有 SH2 结构域的胞内信号蛋白识别，通过级联反应向细胞内进行信号转导。 ②RTK-Ras 信号通路：配体→活化酪氨酸激酶 RTK→活化的酪氨酸激酶 RTK 结合接头蛋白 adaptor-GRF（鸟苷酸释放因子）→促进 GDP 释放→Ras（GTP 结合蛋白）活化，诱导下游 事件：Raf 丝氨酸／苏氨酸蛋白激酶（又称 MAPKKK）活化（使蛋白上的丝氨酸／苏氨酸 残基磷酸化）→活化的 Raf 结合并磷酸化另一种蛋白激酶 MAPKK，导致 MAPKK 活化 （MAPKK 是一种具双重特异的蛋白激酶，它能磷酸化 MAPK 的苏氨酸和酪氨酸残基使之 激活）→MAPK 活化→进入细胞核→其他激酶或基因调控蛋白（转录因子）的磷酸化修饰。 （2）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的功能 调节细胞的增殖与分化，促进细胞存活，以及细胞代谢过程中的调节与校正作用。","kp":"ch11_s2_18"}],"calc":[{"id":"ch11_calc_4","modI":2,"q":"概述受体酪氨酸激酶介导的信号通路的组成、特点及其主要功能。","a":"（1）受体酪氨酸激酶介导的信号通路的组成 ①受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要的受体家族， 包括 6 个亚族。 ②胞外配体是可溶性或膜结合的多肽或蛋白类激素，包括胰岛素和多种生长因子。 ③接头蛋白，如生长因子受体结合蛋白 2（GRB2）。 ④信号通路中有关的酶，如 GTP 酶活化蛋白（GAP）、与肌醇磷脂代谢有关的酶、蛋白磷 酸酯酶（SyP）以及 Src 类的非受体酪氨酸蛋白激酶等。 ⑤Ras 蛋白，具有 GTPase 活性，结合 GTP 活化，结合 GDP 失活，是一种分子开关。 ⑥鸟苷酸释放因子（GRF）。 ⑦Raf 又称 MAPKKK，是 Ser/Thr 蛋白激酶。 ⑧MAPKK 蛋白激酶和 MAPK。 （2）受体酪氨酸激酶介导的信号通路的特点 ①激活机制为受体之间的二聚体化→自磷酸化→活化自身； ②没有特定的第二信使，要求信号有特定的结构域； ③有 Ras 分子开关的参与； ④介导下游 MAPK 的激活。 （3）受体酪氨酸激酶介导的信号通路的主要功能 该信号通路是这类受体所介导的重要信号通路，具有广泛的功能，包括调节细胞的增殖与分 化，促进细胞的存活，以及细胞代谢过程中的调节与校正等。","kp":"ch11_s2_35"}],"term":[{"id":"ch11_term_2","modI":2,"term":"受体酪氨酸磷酸酯酶（receptor tyrosin phospatases）。","def":"受体酪氨酸磷酸酯酶（receptor tyrosin phosphatases）是一次性跨膜蛋白受体，受体胞内 区具有蛋白酪氨酸磷酸酯酶活性，结合配体后，使磷酸化的酪氨酸去磷酸化，可逆转 RTK 的作用，在细胞周期调控中也发挥着重要作用。","kps":"","kp":"ch11_s2_20"},{"id":"ch11_term_4","modI":2,"term":"Ras 蛋白（rat sarcoma，Ras）。","def":"是原癌基因 c-ras 的产物，相对分子质量为 21kDa，属单体 G 蛋白，具有弱的 GTP 酶活 性，Ras 蛋白常与 GDP 结合，定位于细胞质膜内表面，当特异配体与受体酪氨酸激酶或其 他细胞表面受体结合后会将其激活。在信号从细胞表面受体传递到细胞核内的过程中发挥重 要作用。","kps":"","kp":"ch11_s2_26"},{"id":"ch11_term_5","modI":2,"term":"enzyme-linked receptor","def":"enzyme-linked receptor 的中文名称是酶联受体。通常与酶连接的细胞表面受体又称催化 性受体，目前已知的酶联受体都是跨膜蛋白，当胞外信号（配体）与受体结合即激活受体胞 内段的酶活性。主要包括①受体酪氨酸激酶；②受体丝氨酸／苏氨酸激酶；③受体酪氨酸磷 酸酯酶；④受体鸟苷酸环化酶；⑤酪氨酸蛋白激酶联系的受体。","kps":"","kp":"ch11_s2_17"}]},{"i":3,"name":"五 Ca2+ 重要的","slides":[{"i":36,"sec":"4.2 酶联受体","title":"Ca2+信号概况","notes":"胞内信号分子\nCa2+的多功能性：\n(静息态细胞胞质溶胶中浓度很低，低于10-7M；ER和植物液\n泡/线粒体Ca2+浓度髙10000倍: 10-3M)\nThe concentration of Ca2+ free in the cytosol usually must be\nkept below 0.1-0.2 μM.\n【结合课本/笔记】用秋水仙素处理细胞破坏微管,导致细胞变圆,说明微管对维持细胞的不对称形状是重要的。对于细胞突起部分,如纤毛、鞭毛、轴突的形成和维持, 微管亦起关键作用。细胞内物质的运输真核细胞内部是高度区域化的体系, 细胞中合成的物质、一些细胞器等必须经过细胞内运输过程。这种运输过程与细胞骨架体系中的微管及其Motor protein有关。","page":37,"level":"掌握","img":"assets/img/ch11/p037.jpg","anim":null,"fig":null,"points":["促进细胞粘合和胞间通讯","受精作用、肌肉收缩、细胞运动、神经细胞信号传递等","高浓度Ca2+ 导致细胞死亡"],"check":{"q":"关于细胞内Ca2+的分布，叙述正确的是？","o":["A. 静息时胞质Ca2+高于细胞外液","B. Ca2+浓度过高与细胞死亡无关","C. 胞内钙库浓度低于胞质溶胶","D. 静息时胞质溶胶Ca2+低于10-7M，ER等钙库浓度高"],"a":"D","e":"静息态胞质游离Ca2+低于10-7M，而ER/线粒体等钙库可达10-3M。","oe":["胞质Ca2+浓度远低于细胞外液。","过高浓度Ca2+可导致细胞死亡。","钙库中Ca2+浓度远高于胞质溶胶。","正确，胞质游离Ca2+很低，ER、线粒体等钙库高约万倍。"],"basis":"静息态胞质Ca2+低于10-7M，ER钙库浓度高10000倍。"},"cards":null,"mem":"Ca2+第二信使：胞质<10⁻⁷M，钙库高万倍，多功能","big":"assets/img/ch11/big/p037.jpg"}],"mcq":[],"judge":[{"id":"ch11_judge_4","modI":3,"q":"内分泌是细胞对自身分泌的物质产生反应。(        )","a":"错","e":"内分泌是由无导管腺体产生的一种或几种激素，直接分泌到血液中，通过血液循环 运输到靶细胞，促进其生理、生化应答的现象。","kp":"ch11_s3_36","oe":["误将内分泌理解为细胞对自身分泌物反应，其实那是自分泌。","内分泌指无导管腺体将激素分泌入血，经血液循环作用于靶细胞。"]}],"fill":[],"short":[],"calc":[],"term":[]},{"i":4,"name":"5.1 细胞质中低Ca2+浓度(10-7M)的控制机制","slides":[{"i":37,"sec":"5.1 细胞质中低Ca2+浓度(10-7","title":"5.1 细胞质中低Ca2+浓度(10-7M)的控制机制","notes":"●通常，细胞膜对其高度不通透；\n●质膜、内质网膜上含有Ca2+泵(Ca2+ pump)\n&植物细胞液泡膜\n●线粒体膜上也有Ca2+转运蛋白，能将细胞质中的\nCa2+运到线粒体基质中。\n－但相比而言，亲和力较低。辅助、只有胞质内浓度\n很高时才显示运输能力。\n当细胞遇到刺激时，主要是通过打开质膜和内质网\n膜上的Ca2+通道(Ca2+ channel)，使膜外的Ca2+快\n速进入细胞内，使胞质溶胶中的Ca2+浓度迅速升高。","page":38,"level":"掌握","img":"assets/img/ch11/p038.jpg","anim":null,"fig":null,"points":["细胞质中游离Ca2+浓度很低(约10⁻⁷M)，细胞膜对其高度不通透","质膜、内质网膜上含Ca2+泵，线粒体膜上也有Ca2+转运蛋白(亲和力较低)","受刺激时主要通过打开质膜和内质网膜上的Ca2+通道，使Ca2+迅速进入胞质"],"check":{"q":"细胞受到刺激使胞质Ca2+迅速升高，主要通过下列哪种方式？","o":["A. 打开质膜和内质网膜上的Ca2+通道","B. 抑制线粒体的Ca2+转运","C. 由细胞核释放储存的Ca2+","D. 关闭质膜上的Ca2+泵"],"a":"A","e":"刺激时打开质膜和内质网膜上的Ca2+通道，使胞质Ca2+迅速升高。","oe":["正确，刺激打开Ca2+通道，膜外Ca2+快速内流。","线粒体转运是低亲和力辅助方式。","Ca2+来自膜外与内质网钙库，非细胞核。","Ca2+泵负责排出Ca2+，关闭它并非主要升钙机制。"],"basis":"主要通过打开质膜和内质网膜上的Ca2+通道，使膜外的Ca2+快速进入细胞内。"},"cards":null,"mem":"胞质低钙：膜不通透+钙泵泵出+钙库储存，刺激开通道","big":"assets/img/ch11/big/p038.jpg"},{"i":38,"sec":"5.1 细胞质中低Ca2+浓度(10-7","title":"细胞内","notes":"质膜上\nCa2+ is actively pumped out of\nthe cytosol to the cell exterior.\nThe main ways in which eucaryotic cells maintain a\nvery low concentration of free Ca2+ in the cytosol.\n【中文讲解·对照课本/考点】\n考点：5.1 细胞质中低Ca2+浓度(10-7M)的控制机制 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页讲细胞内钙的维持，分“细胞内”与“质膜上”两部分。原文指出Ca2+被主动泵出胞质到细胞外（actively pumped out of the cytosol），这是真核细胞将胞质游离Ca2+维持在极低水平的主要方式。考点：细胞借质膜钙泵及内质网、线粒体等钙库的主动转运，使胞质游离Ca2+保持很低，作为第二信使才能灵敏开关信号。","page":39,"level":"掌握","img":"assets/img/ch11/p039.jpg","anim":null,"fig":null,"points":["质膜上Ca2+被主动泵出到细胞外","真核细胞通过多种方式维持胞质中很低浓度的游离Ca2+"],"check":{"q":"真核细胞将胞质游离Ca2+维持在极低水平的主要方式是？","o":["A. 让Ca2+自由扩散进入细胞核储存","B. 将Ca2+转化为不溶钙盐沉淀于胞质","C. 靠胞质内游离Ca2+自然降解","D. 将Ca2+主动泵出胞质到细胞外"],"a":"D","e":"真核细胞主要靠钙泵将Ca2+从胞质主动泵出到细胞外，并配合内质网、线粒体等钙库的摄取，使胞质游离Ca2+保持很低。","oe":["细胞核并非钙库，不能靠扩散入核储钙。","胞质并非以沉淀钙盐的方式清除Ca2+。","Ca2+是离子不能自然降解，只能被转运。","主动将Ca2+泵出胞质是主要维持方式，正确。"]},"cards":null,"mem":"质膜钙泵主动泵Ca2+出胞，维持胞质游离钙极低","big":"assets/img/ch11/big/p039.jpg"},{"i":39,"sec":"5.1 细胞质中低Ca2+浓度(10-7","title":"An overview of Ca2+ regulatory in cells","notes":"【结合课本/笔记】（五）Signal Transduction           （问答英文）ReceptorsDefinition: Any protein that specifically binds to another molecules tomediate cell-cell signaling, adhesion, endocytosis or other cellularprocess. Mostly commonly denotes a protein located in the plasma membraneor cytoplasm that is activated by binding a specific extrace\n【中文讲解·对照课本/考点】\n考点：5.1 细胞质中低Ca2+浓度(10-7M)的控制机制 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页标题为“细胞内Ca2+调控概览”（An overview of Ca2+ regulatory in cells）。原文仅给出标题，说明该图综合展示细胞对钙离子的调控机制，包括质膜钙泵与Na+/Ca2+交换器排出Ca2+、内质网与线粒体等钙库的摄取与释放，使胞质游离Ca2+维持低浓度，并在需要时迅速升高发挥第二信使作用。","page":40,"level":"掌握","img":"assets/img/ch11/p040.jpg","anim":null,"fig":null,"points":["细胞内Ca2+的调控涉及质膜、内质网和线粒体等","维持胞质低Ca2+、刺激时迅速升高"],"check":{"q":"细胞内Ca2+调控概览中，细胞排出Ca2+并维持低胞质钙依靠？","o":["A. 靠细胞核大量吸收Ca2+以降低胞质浓度","B. 质膜钙泵与Na+/Ca2+交换器排钙，内质网和线粒体作钙库","C. 仅靠线粒体钙库储存，质膜不参与","D. 仅靠内质网钙泵，与质膜无关"],"a":"B","e":"细胞借质膜钙泵和Na+/Ca2+交换器将Ca2+排出胞外，并靠内质网、线粒体等钙库的摄取与释放调控胞质钙。","oe":["细胞核不是钙库，不靠吸钙降低胞质浓度。","质膜排钙加内质网/线粒体钙库共同调控，正确。","质膜钙泵与交换器是排钙的重要途径，说不参与错误。","质膜同样参与排钙，并非只靠内质网。"]},"cards":null,"mem":"钙调控总览：泵出、储存、通道开，保低钙灵敏开关","big":"assets/img/ch11/big/p040.jpg"},{"i":40,"sec":"5.1 细胞质中低Ca2+浓度(10-7","title":"Ca2+ wave in a Starfish egg induced by a fertilizing","notes":"sperm\nThe release of Ca2+ Is seen to spread from the point\n(arrow) of sperm entry throughout the entire Egg.\n【中文讲解·对照课本/考点】\n考点：5.1 细胞质中低Ca2+浓度(10-7M)的控制机制 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装\n\n【本页英文讲解】\n本页标题为受精精子诱导的海星卵Ca2+波（Ca2+ wave in a Starfish egg induced by a fertilizing sperm）。原文指出：Ca2+的释放从精子进入点（箭头处）向整个卵扩散。考点：受精时精子入卵触发卵内Ca2+，以波的形式自入卵点传遍全卵，即“钙波”，是卵激活的重要事件，体现Ca2+第二信使可形成空间传播信号。","page":41,"level":"掌握","img":"assets/img/ch11/p041.jpg","anim":null,"fig":null,"points":["海星卵受精诱导Ca2+波","Ca2+释放从精子进入点(箭头处)向整个卵扩散"],"check":{"q":"受精精子诱导海星卵Ca2+波的特点是？","o":["A. Ca2+释放仅局限于精子入卵点","B. Ca2+在整个卵同时均匀释放","C. Ca2+由卵的植物极向动物极单向扩散","D. Ca2+自精子入卵点向整个卵扩散"],"a":"D","e":"受精时精子入卵触发卵内Ca2+释放，并以波的形式从入卵点向整个卵传播，即钙波，是卵激活的重要事件。","oe":["释放不局限一点，而是传遍整个卵。","并非同时均匀释放，而是呈波状传播。","扩散起点是精子入卵点，不是植物极。","钙波从精子入卵点向全卵扩散，正确。"]},"cards":null,"mem":"受精触发钙波：自精子入点扩散全卵，激活卵","big":"assets/img/ch11/big/p041.jpg"}],"mcq":[],"judge":[{"id":"ch11_judge_9","modI":4,"q":"Ca2 是细胞内广泛存在的信使，细胞质中游离的 Ca2 浓度比胞外高。（ ＋                                     ＋ ）","a":"错","e":"细胞质基质中 Ca2 的浓度是严格受控的。钙泵主要存在于细胞膜和内质网膜上， ＋   它将 Ca2 输出细胞或泵入内质网腔中储存起来，以维持细胞内低浓度的游离 Ca2 （一般细 ＋                                              ＋   胞内游离浓度 Ca2 约 10-7mol/L，细胞外 Ca2 为 10-3mol/L）。 ＋                   ＋","kp":"ch11_s4_37","oe":["误以为胞质游离Ca2+浓度高于胞外，故判对。","胞内游离Ca2+约10-7mol/L，胞外约10-3mol/L，胞外明显高于胞内。"]}],"fill":[],"short":[{"id":"ch11_short_8","modI":4,"q":"肌细胞中的肌球蛋白／肌动蛋白系统的收缩是由胞内 Ca2+浓度的增加来触发的。肌细胞 具有特殊的 Ca2+释放通道-里阿诺碱(ryanodine)受体，因为它对药物中的里阿诺碱敏感。里阿 诺碱受体位于肌质网的膜中，与内质网中的 IP3 门控 Ca2+通道相反，操纵里阿诺碱受体的配 体就是 Ca2+。试讨论里阿诺碱受体通道对肌细胞收缩的重要性。","a":"Ca2+激活的 Ca2+通道产生一个正反馈回路：Ca2+释放的越多，就有更多的 Ca2+通道开放。 因此，胞质溶胶内的 Ca2+信号爆发式地被传送到整个肌细胞，从而确保所有的肌球蛋白／ 肌动蛋白纤维几乎同时收缩。","kp":"ch11_s4_37"}],"calc":[],"term":[]},{"i":5,"name":"5.2 Calcium-binding protein 钙结合蛋白","slides":[{"i":41,"sec":"5.2 Calcium-binding ","title":"5.2 Calcium-binding protein 钙结合蛋白","notes":"Calmodulin, CaM 钙调素、钙调蛋白\nCa2+行使功能时往往不是直接单独作用，而是通过\n结合一些钙结合蛋白，研究最多的是CaM。60年代末，\n钙调素(CaM)发现。\n胶中。 CaM is found in all eukaryotic cells.\n内Ca2+浓度升高，CaM、Ca2+形成复合物。","page":42,"level":"掌握","img":"assets/img/ch11/p042.jpg","anim":null,"fig":null,"points":["Calmodulin存在于真核生物，水溶性，存在胞质溶","静息态细胞中，Ca2+与CaM亲和力很低；刺激后胞"],"check":{"q":"关于钙调素(CaM)的叙述，正确的是？","o":["A. 是细胞膜上的Ca2+通道","B. 存在于真核细胞胞质，Ca2+浓度升高时与其形成复合物","C. 只存在于原核细胞中","D. 本身即为一种蛋白激酶"],"a":"B","e":"CaM为水溶性钙结合蛋白，存在于真核细胞胞质，Ca2+升高时形成Ca2+-CaM复合物。","oe":["CaM是钙结合蛋白，不是Ca2+通道。","正确，CaM存在于所有真核细胞，与Ca2+形成复合物发挥作用。","CaM存在于真核生物，而非原核生物。","CaM结合Ca2+后调节靶蛋白，本身不是激酶。"],"basis":"CaM存在于所有真核细胞，Ca2+升高时与其形成复合物。"},"cards":null,"mem":"CaM广泛存在胞质、含4个Ca2+位点，静息低亲和","big":"assets/img/ch11/big/p042.jpg"},{"i":42,"sec":"5.2 Calcium-binding ","title":"⎯CaM is a widely distributed","notes":"cytosolic protein that contains 4\nCa2+-binding sites.\nCa2+/CaM wraps around exposed\nhelices of various target proteins,\nthereby altering their activity.\n【中文讲解·对照课本/考点】\n考点：5.2 Calcium-binding protein 钙结合蛋白 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 形成；● 正确折叠涉及驻留蛋白：具有KDEL or HDEL信号蛋白二硫键异构酶（protein disulfide isomerase，PDI）切断二硫键，帮助新合成的蛋白重新形成二硫键并处于正确折叠的状态● 结合蛋白（Binding protein，Bip，chaperone）识别错误折叠的蛋白或未装配好的蛋白亚单位，并促进重新折叠与装配。\n\n【本页英文讲解】\n本页讲钙调蛋白CaM。原文指出CaM是一种广泛分布的胞质蛋白，含有4个Ca2+结合位点。结合Ca2+后形成Ca2+/CaM复合物，其构象发生变化，环绕并结合多种靶蛋白暴露的螺旋，从而改变靶蛋白的活性。考点：钙调蛋白（calmodulin, CaM）是重要的Ca2+感受器，通过4个钙结合位点感知钙信号并调节下游靶蛋白，是翟中和教材钙信号转导的关键分子。","page":43,"level":"掌握","img":"assets/img/ch11/p043.jpg","anim":null,"fig":null,"points":["The resulting conformation"],"check":{"q":"钙调蛋白（CaM）发挥调节作用的结构基础是（　）","o":["A. 含1个Ca2+结合位点，以酶活性直接水解靶蛋白","B. 含4个Ca2+结合位点，结合Ca2+后环绕靶蛋白螺旋改变其活性","C. 是一种GTP结合蛋白，通过GTP水解调节靶蛋白","D. 位于线粒体内膜，通过传递电子调节靶蛋白"],"a":"B","e":"CaM是广泛分布的胞质蛋白，含4个Ca2+结合位点；结合Ca2+后形成Ca2+/CaM复合物，构象改变而环绕结合多种靶蛋白暴露的螺旋，从而改变靶蛋白活性。","oe":["错误：CaM含4个而非1个钙结合位点，且不水解靶蛋白。","正确：CaM含4个Ca2+结合位点，Ca2+/CaM环绕靶蛋白螺旋改变其活性。","错误：CaM是钙结合蛋白，并非GTP结合蛋白。","错误：CaM为胞质可溶性蛋白，不位于线粒体内膜传递电子。"]},"cards":null,"mem":"Ca2+/CaM环绕靶蛋白螺旋，改变其活性","big":"assets/img/ch11/big/p043.jpg"},{"i":43,"sec":"5.2 Calcium-binding ","title":"钙调蛋白激酶","notes":"Activation of Ca2+/CaM-dependent kinase (CaM-kinase II)\n【中文讲解·对照课本/考点】\n考点：5.2 Calcium-binding protein 钙结合蛋白 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• ●信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系\n\n【本页英文讲解】\n本页标题为“钙调蛋白激酶”，原文为活化Ca2+/CaM依赖的激酶（CaM-kinase II）。CaM-kinase II即钙/钙调蛋白依赖的蛋白激酶II，当Ca2+/CaM复合物结合后该激酶被激活，进而磷酸化多种底物蛋白。考点：Ca2+信号常经钙调蛋白再激活下游激酶传递，CaM-kinase II是神经系统中重要的多功能激酶，可联系第九章钙信号。","page":44,"level":"掌握","img":"assets/img/ch11/p044.jpg","anim":null,"fig":null,"points":["钙调蛋白激酶(CaM-kinase II)由Ca2+/CaM激活"],"check":{"q":"钙/钙调蛋白依赖的激酶II(CaM-kinase II)如何被激活？","o":["A. 被膜脂DAG直接激活","B. 被GTP结合而激活","C. 被Ca2+/CaM复合物结合而激活","D. 被cAMP直接结合而激活"],"a":"C","e":"CaM-kinase II是钙/钙调蛋白依赖的蛋白激酶，当Ca2+与钙调蛋白结合形成Ca2+/CaM复合物后该激酶被激活，进而磷酸化多种底物。","oe":["DAG激活的是PKC，不是CaM-kinase II。","它不靠GTP结合激活，与GTPase无关。","Ca2+/CaM复合物结合后激酶被激活，正确。","CaM-kinase II由Ca2+/CaM激活，而非cAMP。"]},"cards":null,"mem":"Ca2+/CaM激活CaM激酶II→磷酸化底物传信号","big":"assets/img/ch11/big/p044.jpg"}],"mcq":[],"judge":[{"id":"ch11_ajudge_4","modI":5,"q":"Calmodulin存在于真核生物，水溶性，存在胞质溶","a":"对","e":"本页要点：Calmodulin存在于真核生物，水溶性，存在胞质溶","kp":"ch11_s5_41","oe":["钙调蛋白存在于真核生物，为水溶性蛋白，分布于胞质溶胶中。","误以为钙调蛋白是膜结合蛋白或原核特有，与其实际性质不符。"]}],"fill":[],"short":[],"calc":[],"term":[]},{"i":6,"name":"六、 不同信号体系间的相互作用","slides":[{"i":44,"sec":"六、 不同信号体系间的相互作用","title":"六、 不同信号体系间的相互作用","notes":"Interaction and regulation of signaling pathway\n征\n间的crosstalking\n【中文讲解·对照课本/考点】\n考点：六、 不同信号体系间的相互作用 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 信号趋异（divergence）：是指同一种信号与受体作用后在细胞内分成几个不同的信号途径进行传播，最典型的是受体酪氨酸激酶的信号转导。\n\n【本页讲解】\n本页讲解不同信号体系间的相互作用（Interaction and regulation of signaling pathway），归纳信号传递的主要特征：收敛（convergence）、发散（divergence），以及通路间的crosstalking。收敛指不同信号汇聚到同一通路或共同效应分子；发散指同一信号与受体作用后分成几个不同途径传播；crosstalking强调通路间相互影响与整合。考点联系翟中和《细胞生物学》第九章细胞信号转导，需理解信号网络的整体性。","page":45,"level":"掌握","img":"assets/img/ch11/p045.jpg","anim":null,"fig":null,"points":["细胞信号传递的主要特","收敛（convergence）","发散（divergence）","信号转导具有作用通路"],"check":{"q":"关于细胞信号转导的收敛、发散与crosstalking，叙述正确的是（　）","o":["A. 收敛的典型例子是受体酪氨酸激酶信号转导","B. 发散指同一信号经受体作用后分成几条不同途径传播","C. 收敛指同一信号分成多条途径分别传递","D. 信号通路彼此独立，相互之间不存在crosstalking"],"a":"B","e":"信号传递的主要特征包括收敛、发散和通路间crosstalking；发散指同一信号与受体作用后分成几个不同途径传播（典型如受体酪氨酸激酶），收敛指不同信号汇聚到同一通路或共同效应分子。","oe":["错误：受体酪氨酸激酶信号转导是发散的典型例子。","正确：发散指同一信号与受体作用后分成几个不同途径传播。","错误：收敛指不同信号汇聚到同一通路或共同效应分子。","错误：通路之间存在crosstalking，相互影响与整合。"]},"cards":null,"mem":"信号网络：收敛、发散、crosstalk交叉整合","big":"assets/img/ch11/big/p045.jpg"},{"i":45,"sec":"六、 不同信号体系间的相互作用","title":"cross talking","notes":"【结合课本/笔记】细胞信号传递的基本特征与蛋白激酶的网络整合信息●细胞信号传递的基本特征：●具有收敛（convergence）或发散（divergence）的特点●细胞的信号传导既具有专一性又有作用机制的相似性●信号的放大作用和信号所启动的作用的终止并存●细胞以不同的方式产生对信号的适应(失敏与减量调节)●蛋白激酶的网络整合信息与信号网络系统中的cross talk","page":46,"level":"掌握","img":"assets/img/ch11/p046.jpg","anim":null,"fig":null,"points":["不同的细胞信号通路之间存在交叉对话(cross talking)"],"check":{"q":"关于细胞信号传递的基本特征，正确的是？","o":["A. 信号传递只有专一性，不存在机制相似性","B. 细胞不能对信号产生适应","C. 既有专一性又有作用机制的相似性，并存在信号放大与终止","D. 信号一旦启动便不可终止"],"a":"C","e":"细胞信号传递具有收敛与发散特点，既具专一性又有机制相似性，且放大作用与终止并存，细胞还可通过失敏与减量调节产生适应。","oe":["信号传递专一性与机制相似性并存，非只有专一性。","细胞可通过失敏和减量调节适应信号。","专一性与相似性并存，且有放大和终止，正确。","信号启动后可通过负反馈等机制终止。"]},"cards":null,"mem":"信号特征：专一又相似、放大与终止并存、可适应失敏","big":"assets/img/ch11/big/p046.jpg","terms":[{"t":"收敛","en":"convergence","d":"不同信号通路汇聚到共同效应分子的现象。"},{"t":"交叉对话","en":"cross talking","d":"不同细胞信号通路之间相互影响、相互调节。"}]},{"i":46,"sec":"六、 不同信号体系间的相互作用","title":"Simplified representation of major signal","notes":"transduction pathways in mammals\n【中文讲解·对照课本/考点】\n考点：六、 不同信号体系间的相互作用 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页标题为“哺乳动物主要信号转导通路简图”（Simplified representation of major signal transduction pathways in mammals）。该图概括哺乳动物细胞中几条主要信号通路，如RTK-Ras-MAPK通路、G蛋白及第二信使（cAMP、IP3/DAG、Ca2+）通路等，可作第九章整体框架图。","page":47,"level":"掌握","img":"assets/img/ch11/p047.jpg","anim":null,"fig":null,"points":["本页以简化图展示哺乳动物主要信号转导通路"],"check":{"q":"哺乳动物主要信号转导通路简图概括了下列哪些通路？","o":["A. 仅RTK-Ras-MAPK通路","B. 仅核受体介导的基因表达通路","C. 仅G蛋白偶联受体通路","D. RTK-Ras-MAPK通路及G蛋白、第二信使(cAMP、IP3/DAG、Ca2+)通路"],"a":"D","e":"该图概括哺乳动物主要信号通路，包括RTK-Ras-MAPK通路以及G蛋白和第二信使(cAMP、IP3/DAG、Ca2+)通路等。","oe":["图中不止RTK-Ras-MAPK一条通路。","核受体通路并非该图概括的主要对象。","还包括RTK等通路，不仅G蛋白偶联受体。","包含RTK-Ras-MAPK及G蛋白、第二信使通路，正确。"]},"cards":null,"mem":"主要通路：RTK-Ras-MAPK与cAMP/Ca2+","big":"assets/img/ch11/big/p047.jpg"}],"mcq":[],"judge":[{"id":"ch11_judge_6","modI":6,"q":"参与信号转导的受体都是膜蛋白。（         ）","a":"错","e":"细胞内受体则是胞浆蛋白。","kp":"ch11_s6_44","oe":["误以为参与信号转导的受体都是膜蛋白，故判对。","胞内受体一般为胞浆蛋白，并非膜蛋白，故“都”的说法错误。"]}],"fill":[{"id":"ch11_fill_3","modI":6,"q":"细胞以三种方式进行通讯：______、______和______。","a":"分泌化学信号；细胞间接触性依赖；细胞间形成间隙连接","kp":"ch11_s6_45","oe":["细胞通过分泌化学信号进行远距离或旁分泌通讯","通过细胞表面分子直接接触、相互识别来通讯","相邻细胞形成间隙连接，直接交换小分子和离子"]},{"id":"ch11_fill_16","modI":6,"q":"介导细胞信号传递的受体分为________、__________、_________、和__________。","a":"细胞内受体；离子通道偶联的受体；G 蛋白偶联受体；酶连接的受体","kp":"ch11_s6_44","oe":["细胞内受体位于胞内，结合亲脂性信号分子","离子通道偶联受体配体门控，改变膜电位","G蛋白偶联受体经G蛋白调节效应器","酶连接受体胞内具酶活性或直接招募酶"]}],"short":[{"id":"ch11_short_1","modI":6,"q":"什么是“交叉对话”（cross talking）现象（举例说明）？对此研究有何意义？","a":"（1）细胞信号传递最重要的特征之一是构成一个复杂的信号网络系统，不同的信号可 能包含有相同的中间信号分子，因而在不同信号通路之间可能产生“交叉对话”（cross talking）。 通过蛋白激酶的网络整合信息是调控复杂的细胞行为使不同信号通路之间实现 cross talking 的一种重要方式。例如，磷脂酶 C 既是 G 蛋白偶联受体信号途径的效应酶，又是 RTK 信号 途径的效应酶，并可最终激活蛋白激酶 C（PKC）。 （2）对信号传递过程中 cross talking 的研究有助于加深对信号传递过程非线性内涵的认识， 对此研究将对深入了解多基因表达调控机制、发育机制、病理过程及疾病控制产生十分重要 的影响。","kp":"ch11_s6_44"},{"id":"ch11_short_2","modI":6,"q":"整联蛋白在信号传递过程中发挥什么样的作用？","a":"（1）整联蛋白是细胞表面的跨膜蛋白，由α、β两个亚基组成二聚体，其胞外段具有多 种胞外基质组分的结合位点，包括纤连蛋白、胶原和蛋白聚糖的结合位点。 （2）整联蛋白不仅介导细胞附着到细胞外基质上，更重要的是提供了一种细胞外环境调控 细胞内活性的渠道。整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞 质基质，肌醇第二信使的合成，胞内酪氨酸残基的磷酸化等。这些信号对细胞具有深远影响， 诸如细胞生长、迁移、分化乃至生存。","kp":"ch11_s6_45"},{"id":"ch11_short_5","modI":6,"q":"细胞是如何实现对信号的适应的？","a":"细胞以不同的方式产生对信号的适应：（1）逐渐降低表面受体的数目，游离受体的减 少降低了对外界信号的敏感度；（2）快速钝化受体(受体本身脱敏)，从而降低受体和配体 的亲和力，降低受体对胞外微量配体的敏感性；（3）在受体已被激活的情况下，其下游信 号蛋白发生变化，使通路受阻，这种适应是通过副反馈实现的，即强反应调节使其自身反应 关闭。","kp":"ch11_s6_45"}],"calc":[{"id":"ch11_calc_1","modI":6,"q":"请比较神经细胞与分泌激素的内分泌细胞信号传导的异同。并讨论两种机制的优点。","a":"（1）相同点：两类细胞产生的信号都能够长距离传导：神经元能够沿着长轴突传递动 作电位，而激素则通过循环系统到达机体各处。 （2）不同点：由于在一个突触处神经元分泌大量的神经递质，因此浓度非常高，从而神经 递质受体只需以低亲和力与神经递质结合。相反，激素在血液中被极大地稀释，它们以很低 的浓度进入循环。因此，激素受体一般以极高的亲和力与相应激素结合。 （3）靶细胞通过感受血液中激素的水平作出应答；而一个神经元通过特定的突触联系与选 定的靶细胞通讯。神经信号传递速度很快，仅受动作电位的传播速度与突触的工作情况所限 制；而激素信号则比较慢，其限制因素是循环速度和远距离的扩散。","kp":"ch11_s6_45"},{"id":"ch11_calc_2","modI":6,"q":"试分析信号转导(transduction)的几条通路的共性与特性。","a":"cAMP 信号通路，磷脂酰肌醇信号通路，受体酪氨酸激]醛}-Ras 信号通路是细胞信号转 导研究比较多的信号通路。 他们的共性与特性有：（1）多途径、多层次的细胞信号传递通路具有收敛或发散的特点； （2）细胞的信号转导既具有专一性又有作用机制的相似性；（3）信号转导过程具有信号放 大作用，其放大作用又必须受到适度的控制，表现为信号的放大作用和信号的终止作用并存， 例如，各条信号通路中蛋白质或酶的磷酸化与去磷酸化起信号的传递，级联放大以及终止等 类似作用；（4）细胞对长期的信号刺激反应能进行自身调节。","kp":"ch11_s6_46"},{"id":"ch11_calc_5","modI":6,"q":"概述细胞信号的整合方式与控制机制。","a":"（1）细胞信号的整合方式 细胞的信号转导是多通路、多环节、多层次和高度复杂的可控过程。细胞对信号的应答反应 具有收敛或发散的特点，细胞信号的整合方式分为以下 3 种： ①信号的强度和持续的时间不同控制反应的性质。每种受体都能识别和结合各自的特异性配 体，来自各种非相关受体的信号可以在细胞内收敛成激活一个共同的效应器的信号，从而引 起细胞生理、生化反应和细胞行为的改变。另外，来自相同配体的信号又可发散激活各种不 同的效应器，导致多样化的细胞应答。 ②在不同的细胞中，相同受体因不同的胞内信号蛋白可引发不同的下游通路。细胞的信号转 导既具有专一性又有作用机制的相似性。不同的细胞中，因为转录因子组分不同，即使受体 相同而其下游的通路也是不同的。 ③形成蛋白激酶的网络整合信息。细胞各种不同的信号通路提供了信号途径本身的线性特征， 信号转导最重要的特征之一是构成复杂的信号网络系统，具有高度的非线性特点。因此细胞 需要对各种信号进行整合和精确控制，在各信号通路之间进行“交叉对话”并作出适宜的应答。 整合信号会聚其他信号通路的输入从而修正细胞对信号的反应。 （2）细胞信号的控制机制 ①细胞对外界信号适度的反应既涉及信号的有效刺激和启动，也依赖信号的解除与细胞的反 应终止； ②信号放大与信号终止并存； ③当细胞长期暴露在某种形式的刺激下时，细胞对刺激的反应将会降低； ④细胞以不同的方式对信号进行适应： a．受体没收：细胞通过配体依赖性的受体介导的内吞作用暂时减少细胞表面可利用受体的 数目，但在需要时可以重新释放得以利用。 b．受体下调：细胞通过表面自由受体数目减少和配体的清除机制导致细胞对信号敏感性下 调。 c．信号蛋白失活：受体蛋白未发生改变及影响，而体内的信号蛋白自身发生变化使得信号 通路受阻。 d．抑制性蛋白产生：受体结合配体而被激活后，在下游反应中（如对基因表达的调控）产 生抑制性蛋白并形成负反馈环从而降低或阻断信号转导途径。 e．受体失活：抑制蛋白与受体结合而使得配体无法与受体结合，从而丧失信号通路。","kp":"ch11_s6_45"}],"term":[{"id":"ch11_term_1","modI":6,"term":"信号转导（signal transduction）。","def":"信号转导（signal transduction）是指外界信号（如光、电、化学分子）作用于细胞表面 受体，引起胞内信使的浓度变化，进而导致细胞应答反应的一系列过程。","kps":"","kp":"ch11_s6_46"}]}],"mcq":[{"id":"ch11_mcq_1","mod":"4.1.3 G蛋白偶联受体","modI":1,"q":"细胞内信号蛋白的相互作用是靠（            ）所特异性介导的。","o":["A．蛋白质模式结合域","B．受体蛋白","C．G 蛋白偶联受体","D．疏水性分子相互作用"],"a":"A","e":"靠信号蛋白具有不同的模式结合域与另一相匹配的基序识别与结合，在细胞内组装 成不同信号转导复合物，构成细胞内信号传递通路的基础。","kp":"ch11_s2_8","oe":["信号蛋白靠模式结合域与相匹配基序识别结合，组装信号复合物，正确。","受体蛋白位于膜上识别胞外信号，非胞内信号蛋白互作的介导者。","G蛋白偶联受体为膜受体，不是胞内信号蛋白互作的基础。","疏水性分子间的相互作用不具特异性识别功能。"]},{"id":"ch11_mcq_2","mod":"4.2 酶联受体","modI":2,"q":"不属于蛋白酪氨酸激酶类型的受体是（            ）。","o":["A．EGF 受体","B．PDGF 受体","C．TGFβ受体","D．IGF-1 受体"],"a":"C","e":"TGFβ受体即转化生长因子β受体，为受体丝氨酸／苏氨丝氨激酶。","kp":"ch11_s2_1","oe":["EGF受体属受体酪氨酸激酶，故不符合题意。","PDGF受体属受体酪氨酸激酶，故不符合题意。","TGFβ受体为丝氨酸/苏氨酸激酶受体，不属酪氨酸激酶，故正确。","IGF-1受体属受体酪氨酸激酶，故不符合题意。"]},{"id":"ch11_mcq_3","mod":"4.1.2 G-蛋白偶联受体","modI":0,"q":"在 cAMP 信号中，G 蛋白的偶联作用表现为（            ）。","o":["A．受体的活化导致 G 蛋白的α、β、γ三个亚单位的偶联","B．受体的活化通过 G 蛋白与 MAPK 激酶级联反应通路偶联","C．受体的活化通过 G 蛋白与 PKA(cAMP-dependent protein kinase A)的活化偶联 n 受体的活 化通过 G 蛋白与 AC(adenyl cyclase)的活化偶联","D．受体的活化通过 G 蛋白与 cAMP 偶联"],"a":"D","e":"在 cAMP 信号通路中，三聚体 G 蛋白由α、β、γ三个亚单位组成，受体的活化导致 与 G 蛋白α亚单位相结合的 GDP 被 GTP 交换，而β、γ二聚体共价结合锚于内膜。在 cAMP 信号通路中，处于活化状态的三聚体 G 蛋白亚单位α—GTP 作用于 AC。活化的 AC 使 ATP 环化，生成 cAMP。","kp":"ch11_s0_1","oe":["受体活化使G蛋白α亚基结合GTP并与βγ解离，而非使三亚基偶联。","cAMP通路不经过MAPK级联，MAPK属RTK-Ras通路。","G蛋白不直接与PKA偶联，PKA由cAMP激活，故C表述错误。","受体活化经G蛋白α亚基与AC偶联，催化生成cAMP，表述正确。"]},{"id":"ch11_mcq_4","mod":"4.1.3 G蛋白偶联受体","modI":1,"q":"与细胞内钙离子浓度调控直接相关的信号为（                ）。","o":["A．DAG","B．PKC","C．CaM","D．IP3"],"a":"D","e":"IP3 通过细胞质基质扩散，结合并打开内质网膜上 IP3 敏感的钙通道，引起钙离子顺 电化学梯度从钙库释放进入细胞质基质，通过钙调蛋白引起细胞反应。","kp":"ch11_s1_2","oe":["DAG主要激活蛋白激酶C，不直接引起胞内Ca2+释放。","PKC是DAG和Ca2+激活的激酶，并非直接调控钙浓度者。","CaM是钙结合蛋白，感受Ca2+信号而非直接引起其释放。","IP3结合内质网IP3受体钙通道，促使Ca2+从钙库释放，正确。"]},{"id":"ch11_mcq_5","mod":"4.1.2 G-蛋白偶联受体","modI":0,"q":"一氧化氮受体是（            ）。[南开大学 2011 研]","o":["A．G 蛋白偶联受体","B．鸟苷酸环化酶","C．腺苷酸环化酶","D．受体酪氨酸激酶"],"a":"B","e":"NO 是种可溶性气体，可作为局部介质在许多组织中发挥作用，靶细胞内可溶性鸟 苷酸环化酶（G-cyclase，GC）的激活是 NO 发挥作用的主要机制。","kp":"ch11_s2_1","oe":["NO不通过G蛋白偶联受体发挥其信号作用。","可溶性鸟苷酸环化酶是NO的靶分子，激活后生成cGMP，正确。","腺苷酸环化酶催化生成cAMP，不是NO的受体。","受体酪氨酸激酶与NO的信号作用无关。"]},{"id":"ch11_mcq_6","mod":"4.1.2 G-蛋白偶联受体","modI":0,"q":"有关 cAMP 信号通路，下列说法错误的是（              ）。[南开大学 2007 研]","o":["A．被激活的蛋白激酶 A 的催化亚基转位进入细胞核，使基因调控蛋白磷酸化","B．结合 GTP 的α亚基具有活性，而βγ亚基复合物没有活性","C．βγ亚基复合物与游离的 Gs 的α亚基结合，可使 Gs 的α亚基失活","D．这一通路的首要效应酶是腺苷酸环化酶，cAMP 被环腺苷磷酸二酯酶消除"],"a":"B","e":"当细胞没有受到激素刺激，Gs 处于非活化态时，Gs 蛋白为异聚体，α亚基与 GDP 结合，此时腺苷酸环化酶没有活性；当激素配体与 Rs 受体结合，导致受体构象改变，暴露 出与 Gs 结合的位点，膜的流动性使激素-受体复合物与 Gs 结合，Gs 的α亚基构象改变，从 而排斥 GDP，结合 GTP 而活化，使三聚体 Gs 蛋白解离出α亚基和βγ亚基复合物，并暴露出 α亚基与腺苷酸环化酶的结合位点，结合 GTP 的α亚基与腺苷酸环化酶结合，使之活化，并 将 ATP 转化为 cAMP。当 Gi 与 GTP 结合，Gi 的α亚基与βγ亚基解离后，一是通过α亚基与 腺苷酸环化酶结合，直接抑制酶的活性，二是通过βγ亚基复合物与游离的 Gs α亚基结合， 阻断的α亚基对腺苷酸环化酶的活化。","kp":"ch11_s0_1","oe":["PKA催化亚基可进入细胞核使基因调控蛋白磷酸化，说法正确。","βγ亚基复合物并非没有活性，仍可调节效应器，故B错误。","βγ复合物结合游离Gs的α亚基可使Gs失活，说法正确。","该通路首要效应酶是AC，cAMP由磷酸二酯酶降解，说法正确。"]}],"judge":[{"id":"ch11_judge_1","modI":1,"q":"与胞内受体结合的信号分子多为亲脂性分子。（         ）","a":"对","e":"亲脂性分子疏水性较强，可穿过细胞膜进入细胞。","kp":"ch11_s0_0","oe":["亲脂性分子疏水性强，易穿过细胞膜进入胞内与胞内受体结合。","误以为胞内受体的配体都是亲水分子，忽视了其需穿膜的特性。"]},{"id":"ch11_judge_2","modI":0,"q":"G 蛋白偶联受体中，霍乱毒素使 G 蛋白α亚基不能活化，百日咳毒素使 G 蛋白α亚基持续 活化。（      ）","a":"错","e":"霍乱毒素，使α亚基丧失 GTP 酶的活性并处于持续活化状态；百日咳毒素抑制 Gi 的活性。","kp":"ch11_s0_0","oe":["误将霍乱毒素与百日咳毒素对G蛋白的作用弄反，故判对。","霍乱毒素使Gα丧失GTP酶活性而持续活化，百日咳毒素则抑制Gi活性。"]},{"id":"ch11_judge_3","modI":1,"q":"受体都分布于质膜表面，在信息传递和细胞识别过程中起信号接收器的作用。(       )","a":"错","e":"受体分为胞内受体和胞外受体两种类型。","kp":"ch11_s0_0","oe":["误以为受体只存在于质膜表面，故判对。","受体分胞内受体和胞外（膜）受体两类，并非都分布在质膜表面。"]},{"id":"ch11_judge_4","modI":3,"q":"内分泌是细胞对自身分泌的物质产生反应。(        )","a":"错","e":"内分泌是由无导管腺体产生的一种或几种激素，直接分泌到血液中，通过血液循环 运输到靶细胞，促进其生理、生化应答的现象。","kp":"ch11_s0_0","oe":["误将内分泌理解为细胞对自身分泌物反应，其实那是自分泌。","内分泌指无导管腺体将激素分泌入血，经血液循环作用于靶细胞。"]},{"id":"ch11_judge_5","modI":2,"q":"酪氨酸磷酸化用来构建结合部位，用于其他蛋白质与受体酪氨酸激酶的结合。（         ）","a":"对","e":"","kp":"ch11_s2_3","oe":["受体酪氨酸激酶自磷酸化形成SH2等结合位点，供下游蛋白识别结合。","误以为酪氨酸磷酸化与蛋白结合无关，其实它正是构建停泊位点的方式。"]},{"id":"ch11_judge_6","modI":6,"q":"参与信号转导的受体都是膜蛋白。（         ）","a":"错","e":"细胞内受体则是胞浆蛋白。","kp":"ch11_s2_0","oe":["误以为参与信号转导的受体都是膜蛋白，故判对。","胞内受体一般为胞浆蛋白，并非膜蛋白，故“都”的说法错误。"]},{"id":"ch11_judge_7","modI":1,"q":"胞内受体一般处于受抑制状态，细胞内信号的作用是解除抑制。（       ）","a":"对","e":"","kp":"ch11_s0_0","oe":["类固醇激素胞内受体结合抑制蛋白而失活，配体结合后解除抑制被激活。","误以为胞内受体平时即活化，其实需配体解除抑制才能发挥调控作用。"]},{"id":"ch11_judge_8","modI":1,"q":"IP3 是直接由 PIP2 产生的，PIP2 是从肌醇磷脂衍生而来的，肌醇磷脂没有掺入另外的磷酸 基团。","a":"对","e":"PIP2 含有三个磷酸基团，其中一个连接糖与二酰甘油酯。IP3 通过一个简单的水解 反应产生。","kp":"ch11_s1_2","oe":["IP3由PIP2经简单水解产生，PIP2含三个磷酸基团，衍生时不再额外加磷。","误以为肌醇磷脂衍生时又掺入新的磷酸基团，其实仅是原有基团的保留。"]},{"id":"ch11_judge_9","modI":4,"q":"Ca2 是细胞内广泛存在的信使，细胞质中游离的 Ca2 浓度比胞外高。（ ＋                                     ＋ ）","a":"错","e":"细胞质基质中 Ca2 的浓度是严格受控的。钙泵主要存在于细胞膜和内质网膜上， ＋   它将 Ca2 输出细胞或泵入内质网腔中储存起来，以维持细胞内低浓度的游离 Ca2 （一般细 ＋                                              ＋   胞内游离浓度 Ca2 约 10-7mol/L，细胞外 Ca2 为 10-3mol/L）。 ＋                   ＋","kp":"ch11_s4_0","oe":["误以为胞质游离Ca2+浓度高于胞外，故判对。","胞内游离Ca2+约10-7mol/L，胞外约10-3mol/L，胞外明显高于胞内。"]},{"id":"ch11_judge_10","modI":2,"q":"Ras 蛋白被 SOS 激活后，可激活其下游的 MEK 激酶，再通过激活的 MEK 激酶将 Raf 激 酶激活，引起级联反应。（                ）","a":"错","e":"叙述该信号转导的顺序有误，应为 Ras→Raf→MEK。","kp":"ch11_s2_5","oe":["误把Ras下游顺序记为Ras→MEK→Raf，故判对。","正确的MAPK级联顺序为Ras→Raf→MEK→ERK，题干顺序颠倒。"]},{"id":"ch11_ajudge_4","modI":5,"q":"Calmodulin存在于真核生物，水溶性，存在胞质溶","a":"对","e":"本页要点：Calmodulin存在于真核生物，水溶性，存在胞质溶","kp":"ch11_s5_0","oe":["钙调蛋白存在于真核生物，为水溶性蛋白，分布于胞质溶胶中。","误以为钙调蛋白是膜结合蛋白或原核特有，与其实际性质不符。"]}],"fill":[{"id":"ch11_fill_1","modI":1,"q":"一般将胞外的信号分子称为______，将细胞内最早产生的信号分子称为______。","a":"第一信使；第二信使","kp":"ch11_s0_0","oe":["胞外信号分子称第一信使，负责携带外来信号","细胞内最早产生的信号分子称第二信使，如cAMP"]},{"id":"ch11_fill_2","modI":0,"q":"cAMP 信号通路的效应酶是______，磷脂酰肌醇信号通路的效应酶是______。","a":"腺苷酸环化酶；磷脂酶 C","kp":"ch11_s0_1","oe":["cAMP通路的效应酶是腺苷酸环化酶，催化生成cAMP","磷脂酰肌醇通路效应酶是磷脂酶C，水解PIP2"]},{"id":"ch11_fill_3","modI":6,"q":"细胞以三种方式进行通讯：______、______和______。","a":"分泌化学信号；细胞间接触性依赖；细胞间形成间隙连接","kp":"ch11_s6_0","oe":["细胞通过分泌化学信号进行远距离或旁分泌通讯","通过细胞表面分子直接接触、相互识别来通讯","相邻细胞形成间隙连接，直接交换小分子和离子"]},{"id":"ch11_fill_4","modI":0,"q":"受体的本质是______，构成______。","a":"激素激活的基因调控蛋白；细胞内受体超家族","kp":"ch11_s0_0","oe":["胞内受体的本质是激素激活的基因调控蛋白","它们结构同源，共同构成细胞内受体超家族"]},{"id":"ch11_fill_5","modI":0,"q":"G 蛋白耦联受体是细胞表面由______条多肽______次跨膜形成的受体，N 端在______，C 端在______。N 端与______结合，C 端与______作用。","a":"单；7；外；内；信号；G 蛋白","kp":"ch11_s0_0","oe":["G蛋白耦联受体由单条多肽链构成，反复穿膜","该肽链7次跨膜，形成七个跨膜α螺旋","该受体N端位于细胞膜外侧，朝向胞外","该受体C端位于细胞膜内侧，朝向胞质","N端负责与细胞外的信号分子结合","C端则与胞内的G蛋白相互作用并传递信号"]},{"id":"ch11_fill_6","modI":0,"q":"第一信使指______。","a":"细胞外信号分子","kp":"ch11_s0_0","oe":["第一信使即细胞外信号分子，是信号转导的起始携带者"]},{"id":"ch11_fill_7","modI":0,"q":"硝酸甘油能用于治疗心绞痛是因为______。","a":"硝酸甘油在体内转化为 NO，可舒张血管","kp":"ch11_s0_0","oe":["硝酸甘油在体内释放NO，NO舒张血管缓解心绞痛"]},{"id":"ch11_fill_8","modI":2,"q":"生长因子属于______信号分子，不能穿过靶细胞质膜的______。通过与靶细胞表面的 ______结合再经信号转导机制，在细胞内产生______或激活______或______的活性，引起细 胞的应答反应。","a":"亲水性；脂双分子层；受体；第二信使；蛋白激酶；蛋白磷酸酶","kp":"ch11_s2_0","oe":["生长因子是亲水性信号分子，不能直接进入细胞","它不能穿过靶细胞质膜的脂双分子层","需与靶细胞膜表面的特异性受体结合","经信号转导在细胞内产生第二信使","或激活蛋白激酶的活性来传递信号","或激活蛋白磷酸酶，从而引起细胞应答"]},{"id":"ch11_fill_9","modI":0,"q":"无活性的蛋白激酶 A 有______和______亚基，cAMP 结合它的______使其激活。","a":"调节亚基；无活性的催化；调节亚基","kp":"ch11_s0_2","oe":["无活性的蛋白激酶A含有调节亚基","同时含无活性的催化亚基，二者组成四聚体","cAMP结合调节亚基，使催化亚基释放而被激活"]},{"id":"ch11_fill_10","modI":2,"q":"30％的人类恶性肿瘤是因为突变的______蛋白能与______合，但不能将其水解为______， 而使这种突变的蛋白一直处于开启状态。","a":"Ras；GTP；GDP","kp":"ch11_s2_9","oe":["突变的是Ras蛋白，属原癌基因产物","突变Ras能与GTP结合但丧失GTPase活性","不能将GTP水解为GDP，故持续处于开启状态"]},{"id":"ch11_fill_11","modI":2,"q":"酪氨酸蛋白激酶联系的受体______，但是它的胞内区域具有______，也就是说它的活性 依赖于______。","a":"本身不具备酶活性；酪氨酸蛋白激酶的结合位点；非受体酪氨酸蛋白激酶","kp":"ch11_s2_1","oe":["酪氨酸蛋白激酶联系的受体本身不具备酶活性","其胞内区具有酪氨酸蛋白激酶的结合位点","其活性依赖于非受体酪氨酸蛋白激酶"]},{"id":"ch11_fill_12","modI":1,"q":"细胞识别作用引起三种反应：①______；②______；③______。","a":"内吞作用；细胞黏着；接触抑制","kp":"ch11_s0_0","oe":["细胞识别可触发内吞作用，摄取特定物质","细胞识别可介导细胞黏着，使细胞相互连接","细胞识别可引起接触抑制，控制细胞增殖"]},{"id":"ch11_fill_13","modI":1,"q":"胞内受体一般有三个结构域：①______；②______；③______。","a":"与信号分子结合的 C 端结构域；与 DNA 结合的中间结构域；活化基因转录的 N 端结构域","kp":"ch11_s0_0","oe":["C端为与信号分子（激素）结合的结构域","中间为与DNA结合的结构域，调控转录","N端为活化基因转录的结构域，启动表达"]},{"id":"ch11_fill_14","modI":2,"q":"受体修饰是细胞适应的一种方式，机理是：①______；或是②______。","a":"受体被磷酸化后失去与信号分子结合的能力；受体被磷酸化易与抑制物结合而失去 与信号分子结合的能力","kp":"ch11_s2_0","oe":["受体被磷酸化后失去与信号分子结合的能力","受体磷酸化后易与抑制物结合而失去结合能力"]},{"id":"ch11_fill_15","modI":2,"q":"cGMP 信号通路是酶联受体的一种，受体本身就是______酶。其细胞外部分有信号分子 结合的位点，细胞内部分有一______酶结构域，活化后可催化 GTP 生成 cGMP。 在这个系统中，cGMP 与______系统中的 cAMP 一样都充当第二信使。另外一个研究得比较 清楚的酶联受体信号系统就是 EGF 信号通路。EGF 受体是一种______，分子质量为 170 kDa， 广泛分布于哺乳动物细胞的上皮细胞、人成纤维细胞、胶质细胞、角质细胞等。EGF 受体 是一条含有 1186 个氨基酸的多肽链，由______个结构域组成：即 EGF 结合结构域、______ 和蛋白激酶活性区域。EGF 信号解除是通过胞吞作用进行的，EGF 被吞入后，      再运送至______。 Ras 蛋白的激活与 EGF 信号有关。Ras 蛋白是原癌基因 c-ras 表达的产物，也是一种______ 蛋白，具有鸟苷结合位点。对细胞的生长、分化、细胞骨架、蛋白质运输和分泌等功能产生 调节和影响。在正常情况下，Ras 蛋白基本上都与______结合在一起，定位在细胞膜内表面 上。当 EGF 与受体结合后，受体细胞质面的酪氨酸蛋白激酶被激活后______作用于 Ras 蛋 白，使 Ras 蛋白立即解离______，而与______结合，处于活化状态并发出刺激细胞生长的信 号。","a":"鸟苷环化；鸟苷环化；PKA；糖蛋白；三；跨膜区；溶酶体；G；GDP；间接；GDP； GTR","kp":"ch11_s2_1","oe":["cGMP通路中受体本身即鸟苷环化酶","其胞内部分含鸟苷环化酶结构域，催化GTP生成cGMP","cGMP与PKA通路中的cAMP一样充当第二信使","EGF受体是一种跨膜糖蛋白，分布广泛","EGF受体由三个结构域组成，各司其职","即EGF结合结构域、跨膜区和蛋白激酶活性区","EGF被吞入后经胞吞运送至溶酶体降解","Ras是原癌基因表达的G蛋白（GTP结合蛋白）","正常情况下Ras与GDP结合，定位在膜内表面","活化的受体经接头蛋白间接作用于Ras","使Ras蛋白立即解离所结合的GDP","Ras转而与GTP结合，处于活化状态"]},{"id":"ch11_fill_16","modI":6,"q":"介导细胞信号传递的受体分为________、__________、_________、和__________。[南 京师范大学 2007 研]","a":"细胞内受体；离子通道偶联的受体；G 蛋白偶联受体；酶连接的受体","kp":"ch11_s2_0","oe":["细胞内受体位于胞内，结合亲脂性信号分子","离子通道偶联受体配体门控，改变膜电位","G蛋白偶联受体经G蛋白调节效应器","酶连接受体胞内具酶活性或直接招募酶"]},{"id":"ch11_fill_17","modI":1,"q":"细胞表面受体丝氨酸∕苏氨酸激酶是_____次跨膜蛋白受体，受体胞内区具有_____活性， 它的主要配体是_____。[中科院-中科大 2005 研]","a":"1；丝氨酸∕苏氨酸蛋白激酶；转化生长因子β家族成员","kp":"ch11_s2_1","oe":["丝氨酸/苏氨酸激酶受体为单次跨膜蛋白","其胞内区具有丝氨酸/苏氨酸蛋白激酶活性","其主要配体是转化生长因子β家族成员"]}],"term":[{"id":"ch11_term_1","modI":6,"term":"信号转导（signal transduction）。","def":"信号转导（signal transduction）是指外界信号（如光、电、化学分子）作用于细胞表面 受体，引起胞内信使的浓度变化，进而导致细胞应答反应的一系列过程。","kps":"","kp":"ch11_s0_0"},{"id":"ch11_term_2","modI":2,"term":"受体酪氨酸磷酸酯酶（receptor tyrosin phospatases）。","def":"受体酪氨酸磷酸酯酶（receptor tyrosin phosphatases）是一次性跨膜蛋白受体，受体胞内 区具有蛋白酪氨酸磷酸酯酶活性，结合配体后，使磷酸化的酪氨酸去磷酸化，可逆转 RTK 的作用，在细胞周期调控中也发挥着重要作用。","kps":"","kp":"ch11_s2_1"},{"id":"ch11_term_3","modI":1,"term":"双信使系统（double messenger system）。","def":"双信使系统（double messenger system）是指磷脂酰肌醇信号通路的胞外信号被膜蛋白 受体接受后，同时产生两个胞内信使，分别启动两个信号传递途径即 IP3-Ca2+和 DG-PKC 途 径，实现细胞对外界信号的应答的一种信号系统。","kps":"","kp":"ch11_s1_2"},{"id":"ch11_term_4","modI":2,"term":"Ras 蛋白（rat sarcoma，Ras）。","def":"是原癌基因 c-ras 的产物，相对分子质量为 21kDa，属单体 G 蛋白，具有弱的 GTP 酶活 性，Ras 蛋白常与 GDP 结合，定位于细胞质膜内表面，当特异配体与受体酪氨酸激酶或其 他细胞表面受体结合后会将其激活。在信号从细胞表面受体传递到细胞核内的过程中发挥重 要作用。","kps":"","kp":"ch11_s2_9"},{"id":"ch11_term_5","modI":2,"term":"enzyme-linked receptor（Enzyme-linked receptor）","def":"enzyme-linked receptor 的中文名称是酶联受体。通常与酶连接的细胞表面受体又称催化 性受体，目前已知的酶联受体都是跨膜蛋白，当胞外信号（配体）与受体结合即激活受体胞 内段的酶活性。主要包括①受体酪氨酸激酶；②受体丝氨酸／苏氨酸激酶；③受体酪氨酸磷 酸酯酶；④受体鸟苷酸环化酶；⑤酪氨酸蛋白激酶联系的受体。","kps":"","kp":"ch11_s2_0"},{"id":"ch11_term_6","modI":0,"term":"蛋白激酶 VS 蛋白酶体（Protein kinase vs. proteasome）","def":"蛋白激酶又称蛋白质磷酸化酶，是一类催化蛋白质磷酸化反应的酶，能够特异性地在某 些蛋白质的某些氨基酸位点上添加磷酸基团。蛋白激酶在细胞内的分布遍及核、线粒体、微 粒体和胞液。一般分为 3 大类：①底物专一的蛋白激酶：如磷酸化酶激酶，丙酮酸脱氢酶激 酶等。②依赖于环核苷酸的蛋白激酶：如环腺苷酸（cAMP）蛋白激酶，环鸟苷酸（cGMP） 蛋白激酶。③其他蛋白激酶：如组蛋白激酶等。 蛋白酶体是一类能降解细胞不需要的或受到损伤蛋白质的蛋白复合物。经过蛋白酶体的作用， 蛋白质被切断为约 7～8 个氨基酸长的肽段，这些肽段可以被进一步降解为单个氨基酸分子， 然后被用于合成新的蛋白质。蛋白酶体是细胞用来调控特定蛋白质和除去错误折叠蛋白质的 主要机制。一般来说，需要被降解的蛋白质会先被一个称为泛素的小型蛋白质所标记，被标 记上的蛋白质就会被蛋白酶体降解，因此人们常把蛋白酶体和泛素结合起来，将这一过程称 为泛素依赖性蛋白酶体降解途径。","kps":"","kp":"ch11_s1_7"},{"id":"ch11_term_7","modI":1,"term":"分子开关（Molecular switch）","def":"分子开关是指通过激活机制或失活机制精确控制细胞内一系列信号传递级联反应的蛋白 质分子，可分为两类：一类分子开关蛋白的活性由磷酸化和去磷酸化控制，蛋白激酶使之磷 酸化而开放，蛋白磷酸酯酶使之去磷酸化而关闭，许多由可逆磷酸化控制的开关蛋白是蛋白 激酶本身；另一类分子开关蛋白是 GTP 结合蛋白，结合 GTP 而活化，结合 GDP 而失活。","kps":"","kp":"ch11_s1_5"},{"id":"ch11_term_8","modI":1,"term":"第二信使（Second messenger）","def":"第二信使是指受细胞外信号的作用，在细胞质溶质内形成或向细胞质溶质释放的细胞内 小分子，负责将信号传到细胞内部，如 cAMP、IP3、Ca2 等。第二信使通过其浓度变化（增 ＋   加或减少）应答胞外信号与细胞表面受体的结合，调节细胞内酶和非酶蛋白的活性，从而在 细胞信号转导途径中行使携带和放大信号的功能。","kps":"","kp":"ch11_s0_2"},{"id":"ch11_term_9","modI":1,"term":"cell recognition（Cell recognition）","def":"cell recognition 的中文名称细胞识别。细胞识别主要是指细胞表面的受体或者配体与相 邻细胞表面的配体或者受体选择性识别、结合并引起一系列下游生理生化反应的过程，对多 细胞生物体的发育具有重要意义。","kps":"","kp":"ch11_s0_0"}],"short":[{"id":"ch11_short_1","modI":6,"q":"什么是“交叉对话”（cross talking）现象（举例说明）？对此研究有何意义？","a":"（1）细胞信号传递最重要的特征之一是构成一个复杂的信号网络系统，不同的信号可 能包含有相同的中间信号分子，因而在不同信号通路之间可能产生“交叉对话”（cross talking）。 通过蛋白激酶的网络整合信息是调控复杂的细胞行为使不同信号通路之间实现 cross talking 的一种重要方式。例如，磷脂酶 C 既是 G 蛋白偶联受体信号途径的效应酶，又是 RTK 信号 途径的效应酶，并可最终激活蛋白激酶 C（PKC）。 （2）对信号传递过程中 cross talking 的研究有助于加深对信号传递过程非线性内涵的认识， 对此研究将对深入了解多基因表达调控机制、发育机制、病理过程及疾病控制产生十分重要 的影响。","kp":"ch11_s6_1","kps":"cross talking：不同通路共用相同中间信号分子；意义：认识信号非线性、基因表达调控、发育与疾病控制"},{"id":"ch11_short_2","modI":6,"q":"整联蛋白在信号传递过程中发挥什么样的作用？","a":"（1）整联蛋白是细胞表面的跨膜蛋白，由α、β两个亚基组成二聚体，其胞外段具有多 种胞外基质组分的结合位点，包括纤连蛋白、胶原和蛋白聚糖的结合位点。 （2）整联蛋白不仅介导细胞附着到细胞外基质上，更重要的是提供了一种细胞外环境调控 细胞内活性的渠道。整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞 质基质，肌醇第二信使的合成，胞内酪氨酸残基的磷酸化等。这些信号对细胞具有深远影响， 诸如细胞生长、迁移、分化乃至生存。","kp":"ch11_s6_0","kps":"整联蛋白为α、β亚基跨膜蛋白，胞外段结合纤连蛋白；介导细胞附着基质，提供调控胞内活性渠道，产生Ca2+、酪氨酸磷酸化"},{"id":"ch11_short_3","modI":0,"q":"G 蛋白偶联受体与酶联受体有什么主要不同点？","a":"蛋白偶联受体都含有 7 次跨膜的结构域，在信号转导中全部与 G 蛋白偶联；酶联受体 都属于单次跨膜受体，当该类受体与配体结合时导致受体二聚化形成同源或异源多聚化。","kp":"ch11_s2_0","kps":"G蛋白偶联受体含7次跨膜结构域，信号转导中均与G蛋白偶联；酶联受体为单次跨膜受体，与配体结合后二聚化形成同源或异源多聚体"},{"id":"ch11_short_4","modI":0,"q":"简述 cAMP 途径中的 Gs 调节模型。","a":"在该途径中由刺激型 Gs 蛋白复合物偶联刺激型受体与腺苷酸环化酶。当细胞没有接受 刺激信号时，Gs 处于非活化状态，Gs 蛋白为异三聚体，α亚基与 GDP 结合，这时腺苷酸环 化酶没有活性。当刺激型的第一信使作用于刺激型的受体后，导致受体构象改变，受体复合 物与 GS 结合引起 Gs 的α亚基构象变化排斥 GDP，而与 GTP 结合被活化，三聚体 Gs 解离 出α亚基和贝塔嘎嘛亚基复合物，活化的刺激型 Gsα亚基继激活腺苷酸环化酶的活性，从而 产生第二信使 cAMP，由于 cAMP 的浓度升高，引起细胞内依赖于 cAMP 的靶酶活化，由 此将胞外信号转换成胞内信号传递、放大以致调节细胞生理反应或基因的表达等。随着 GTP 的水解使α亚基恢复原来的构象并导致与腺苷酸环化酶解离，终止腺苷酸环化酶的活化作 用,α亚基和βγ亚基重新结合，使细胞回复到静止状态。","kp":"ch11_s0_1","kps":"Gs为异三聚体、AC无活性；配体结合受体→Gs活化、α排GDP结合GTP→分离α与βγ→AC产生cAMP→激活PKA"},{"id":"ch11_short_5","modI":6,"q":"细胞是如何实现对信号的适应的？","a":"细胞以不同的方式产生对信号的适应：（1）逐渐降低表面受体的数目，游离受体的减 少降低了对外界信号的敏感度；（2）快速钝化受体(受体本身脱敏)，从而降低受体和配体 的亲和力，降低受体对胞外微量配体的敏感性；（3）在受体已被激活的情况下，其下游信 号蛋白发生变化，使通路受阻，这种适应是通过副反馈实现的，即强反应调节使其自身反应 关闭。","kp":"ch11_s6_0","kps":"适应：①降低表面受体数目，降低敏感度；②快速钝化受体，降低与配体亲和力；③下游信号蛋白变化致通路受阻（负反馈）"},{"id":"ch11_short_6","modI":1,"q":"Ca2+为何可以作为胞内信号进行信号转导，Ca2+的储存与释放在信号转导中有什么作用？","a":"在细胞质基质中，基态的 Ca2+浓度约为 l0-7～mol／L，很少的 Ca2+流入就可以导致胞内 溶胶 Ca2+较大程度变化。与 Na+相比，胞内 Na+浓度发生显著改变所需要的离子量要大得多。 在信号转导中，Ca2+作用极其重要，不仅可以作为第三信使参与广泛的生理活动，活化各种 Ca2+结合蛋白并引起细胞反应，而且在双信使系统本身的调节方面也非常重要。胞内 Ca2+ 浓度过高会引起细胞中毒，质膜上的钙泵和钠钙交换器将 Ca2+泵出细胞，内质网膜上的钙 泵会将高浓度的 Ca2+泵进内质网钙库。至少已经发现 4 种以上的钙结合蛋白，每个钙结合蛋 白可与 30 个左右的 Ca2+结合，钙结合蛋白的浓度可达 30～100 mg／mL，内质网作为 Ca2+ 的储存库。","kp":"ch11_s4_0","kps":"胞质Ca²⁺约10⁻⁷mol/L，微量内流即显著变化，故为第三信使；活化钙结合蛋白；钙泵泵出，内质网钙库储存并释放"},{"id":"ch11_short_7","modI":1,"q":"比较 cAMP 信号系统与 IP3-DAG 信号系统在跨膜信号传递作用的异同。","a":"二者都是 G 蛋白偶联信号转导系统，但是第二信使不同，分别由不同的效应物生成： cAMP 由腺苷酸环化酶(AC)水解细胞中的 ATP 生成，cAMP 再与蛋白激酶 A(PKA)结合，引 发一系列细胞质反应与细胞核中的作用。在另一种信号转导系统中，效应物磷脂酶 Cq(PLC) 将膜上的磷脂酰肌醇 4，5-二磷酸分解为两个信使：二酰甘油(DAG)与 1，4，5-三磷酸肌醇(IP3)， IP3 动员胞内钙库释放 Ca2+，与钙调蛋白结合引起系列反应，而 DAG 在 Ca2+的协同下激活 蛋白激酶 C(PKC)，再引起级联反应。","kp":"ch11_s1_2","kps":"均G蛋白偶联；AC水解ATP生成cAMP激活PKA；PLC水解PIP₂生IP₃和DAG；IP₃释钙、DAG激活PKC"},{"id":"ch11_short_8","modI":4,"q":"肌细胞中的肌球蛋白／肌动蛋白系统的收缩是由胞内 Ca2+浓度的增加来触发的。肌细胞 具有特殊的 Ca2+释放通道-里阿诺碱(ryanodine)受体，因为它对药物中的里阿诺碱敏感。里阿 诺碱受体位于肌质网的膜中，与内质网中的 IP3 门控 Ca2+通道相反，操纵里阿诺碱受体的配 体就是 Ca2+。试讨论里阿诺碱受体通道对肌细胞收缩的重要性。","a":"Ca2+激活的 Ca2+通道产生一个正反馈回路：Ca2+释放的越多，就有更多的 Ca2+通道开放。 因此，胞质溶胶内的 Ca2+信号爆发式地被传送到整个肌细胞，从而确保所有的肌球蛋白／ 肌动蛋白纤维几乎同时收缩。","kp":"ch11_s4_0","kps":"里阿诺碱受体是肌质网Ca²⁺释放通道，配体为Ca²⁺；构成正反馈；使Ca²⁺信号传遍肌细胞，保证纤维同步收缩"},{"id":"ch11_short_9","modI":1,"q":"请列举三种以上受体酪氨酸蛋白激酶介导的信号转导的级联通路。","a":"受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要受体家族。 当配体与受体相结合，激活受体的酪氨酸蛋白激酶活性，随即引起一系列磷酸化级联反应， 最终导致细胞生理和基因表达的改变。其介导的信号转导级联通路举例如下： （1）Grb2 信号通路 活化的受体识别含有 SH2 结构的靶蛋白，当 TPK 受体被激活后便借助于自身磷酸化的酪氨 酸残基与细胞内的信号分子接头蛋白 Grb2 的 SH2 结构结合，激活靶蛋白。 （2）Sos 信号通路 TPK 除含有一个隐含的 SH2 结构域外，还具有两个 SH3 结构域。它的功能是识别并结合下 游的另一个信号分子——鸟苷酸释放因子（Sos），识别部位是 Sos 中富含脯氨酸的区段。 在细胞静息状态时，Grb2 通过两个 SH3 结构与 Sos 结合形成复合物，存在于胞浆中，当 TPK 受体被激活，通过 Grb2 的 N 端 SH2 结构将 Grb2-Sos 复合物与受体相连，并将其转移至细 胞膜上募集 Sos，提高 Sos 在质膜上的局部浓度，Sos 具有核苷酸转移酶的活性，可激活下 游靶蛋白 Ras。 （3）RTK-Ras 蛋白信号通路 Ras 蛋白在 RTK 介导的信号通路中是一种关键组分。Ras 蛋白结合 GTP 时为活化态，而结 合 GDP 时为失活态。所以 Ras 蛋白具有分子开关的作用。Ras 蛋白的活化及其细胞应答是 通过配体与 RTK 的结合而诱导的。由 RTK 介导的信号通路具有广泛的功能，包括调节细胞 的增殖、分化、促进细胞存活，以及细胞代谢过程中的调节与校正作用。各种不同的胞外配 体（生长因子）与 RTK 结合，有时会引起细胞内产生多向性的效应，包括早期和晚期的基 因表达。","kp":"ch11_s2_4","kps":"RTK配体结合致二聚化及磷酸化；Grb2/Sos激活Ras，经Raf-MEK-MAPK级联；另有PI3K-Akt"},{"id":"ch11_short_10","modI":2,"q":"概述酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点和功能。","a":"（1）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点 ①受体酪氨酸蛋白激酶：是由 50 多种跨膜受体组成的超家族，其胞外配体是可溶性或膜结 合的多肽或蛋白类激素，包括胰岛素和多种生长因子。胞外配体与受体胞外区结合后，受体 发生二聚化并催化胞内区酪氨酸残基自身磷酸化，进而活化 RTK。磷酸化的酪氨酸可被一 类含有 SH2 结构域的胞内信号蛋白识别，通过级联反应向细胞内进行信号转导。 ②RTK-Ras 信号通路：配体→活化酪氨酸激酶 RTK→活化的酪氨酸激酶 RTK 结合接头蛋白 adaptor-GRF（鸟苷酸释放因子）→促进 GDP 释放→Ras（GTP 结合蛋白）活化，诱导下游 事件：Raf 丝氨酸／苏氨酸蛋白激酶（又称 MAPKKK）活化（使蛋白上的丝氨酸／苏氨酸 残基磷酸化）→活化的 Raf 结合并磷酸化另一种蛋白激酶 MAPKK，导致 MAPKK 活化 （MAPKK 是一种具双重特异的蛋白激酶，它能磷酸化 MAPK 的苏氨酸和酪氨酸残基使之 激活）→MAPK 活化→进入细胞核→其他激酶或基因调控蛋白（转录因子）的磷酸化修饰。 （2）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的功能 调节细胞的增殖与分化，促进细胞存活，以及细胞代谢过程中的调节与校正作用。","kp":"ch11_s2_4","kps":"RTK为跨膜受体超家族，配体为多肽/蛋白激素；结合致二聚化与自身磷酸化；磷酸酪氨酸被SH2蛋白识别；经GRF激活Ras"},{"id":"ch11_short_11","modI":1,"q":"真核细胞为何以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使？（注：细胞质中游 ＋        ＋   离 Ca2 的浓度维持在 10-7mol/L，而 Na 的浓度维持在 10-3mol/L） ＋                     ＋","a":"真核细胞之所以以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使，主要有两方面 ＋       ＋   的原因： （1）以 Ca2 为细胞内的第三信使，只需要少量的 Ca2 进入细胞，即可达到传递信号所需的 ＋                         ＋   浓度阈值，从而诱发各种细胞反应，即使在细胞外 Ca2 缺乏的情况下也容易达到； ＋   （2）若以 Na 作为第三信使，势必需要很多 Na 进入细胞内，一方面会引起细胞外 Na 的 ＋                   ＋                          ＋   缺少，需要大量 Na 进行补充；另一方面也会引起膜电位的紊乱，对细胞造成伤害。 ＋","kp":"ch11_s4_0","kps":"Ca²⁺胞质约10⁻⁷mol/L，少量内流即达阈值；Na⁺胞内10⁻³mol/L则需大量内流才改变，故Ca²⁺适作信使"},{"id":"ch11_short_12","modI":1,"q":"如果说细胞信号产生于多细胞生命形式的需要，那如何解释动物与单细胞的出芽酵母之 间在细胞信号上有如此相似的机制？","a":"动物与单细胞的出芽酵母之间在细胞信号上有相似机制的原因：多细胞有机体的细胞和 细胞之间需要进行信息交流，所以有信号转导机制。单细胞的出芽酵母也要与周围的环境进 行信息交流，当细胞受到刺激后首先被细胞表面特异性受体所识别，胞外信号通过信使进入 胞内转变为胞内信号，这与多细胞生物是相似的。","kp":"ch11_s0_0","kps":"多细胞需细胞间信息交流故有信号转导；单细胞出芽酵母也需与环境交流；均经表面受体识别胞外信号并转为胞内信号，机制同源相似"},{"id":"ch11_short_13","modI":1,"q":"G 蛋白在细胞质膜受体介导的信号传导途径中的功能及其调节。","a":"（1）G 蛋白在细胞质膜受体介导的信号传导途径中的功能 G 蛋白能够将受体接受的信号传递给效应物，产生第二信使，进行信号转导，某些 G 蛋白 还可直接调节某些离子通道的通透性。 （2）G 蛋白在细胞质膜受体介导的信号传导途径中的调节 G 蛋白由α，β，γ三个不同亚基组成。配体和受体结合，诱导 GTP 与 G 蛋白结合的 GDP 进 行交换，GTP 结合的 G 蛋白处于活化状态，激活位于信号传导途径中的下游分子如腺苷酸 环化酶。G 蛋白α亚基具有内源 GTP 酶活性，当 GTP-Gα水解为 GDP-Gα后，则处于失活状 态。 G 蛋白偶联受体介导的信号通路主要有两条：一条是 cAMP 信号通路，另有一条是磷脂酰 肌醇信号通路。前者是配体与受体结合，激活偶联的 G 蛋白，G 蛋白激活腺苷酸环化酶， 产生第二信使 cAMP，引发下游细胞事件。后者也是配体与受体结合激活偶联的 G 蛋白， 活化的 G 蛋白激活质膜上的磷脂酶 C，使 PIP2 水解为 IP3 和 DAG 两个第二信使，IP3 可动员 细胞内 Ca2 释放，DAG 可激活蛋白激酶 C（PKC），分别激发细胞的下游事件，又称“双信 ＋   使系统”。","kp":"ch11_s0_0","kps":"功能：将受体信号传效应物产生第二信使，或调离子通道；调节：αβγ三亚基，GTP置换GDP活化，α亚基水解GTP后失活"},{"id":"ch11_short_y1","modI":2,"q":"比较受体酪氨酸激酶（RTK）通路与G蛋白偶联受体通路在受体结构、是否需第二信使和激活方式上的差异。","a":"①受体结构：GPCR为7次跨膜α螺旋受体；RTK为单次跨膜受体，胞内具酪氨酸激酶结构域。②第二信使：GPCR通路常经第二信使（cAMP、IP3/DAG、Ca2+）；RTK通路一般无特定第二信使，而靠蛋白-蛋白相互作用和磷酸化级联传递（如Ras-MAPK）。③激活方式：GPCR通过配体结合激活G蛋白（GTP/GDP交换）；RTK通过配体诱导受体二聚化和自磷酸化激活。④下游：GPCR常经PKA/PKC；RTK常经Ras-MAPK、PI3K-Akt、JAK-STAT等。","kps":"结构:7次跨膜 vs 单次跨膜+酪氨酸激酶域;第二信使:有 vs 无特定;激活:配体→G蛋白 vs 二聚化自磷酸化;下游:PKA/PKC vs Ras-MAPK等","type":"比较型","kp":"ch11_s2_0"}],"calc":[{"id":"ch11_calc_1","modI":6,"q":"请比较神经细胞与分泌激素的内分泌细胞信号传导的异同。并讨论两种机制的优点。","a":"（1）相同点：两类细胞产生的信号都能够长距离传导：神经元能够沿着长轴突传递动 作电位，而激素则通过循环系统到达机体各处。 （2）不同点：由于在一个突触处神经元分泌大量的神经递质，因此浓度非常高，从而神经 递质受体只需以低亲和力与神经递质结合。相反，激素在血液中被极大地稀释，它们以很低 的浓度进入循环。因此，激素受体一般以极高的亲和力与相应激素结合。 （3）靶细胞通过感受血液中激素的水平作出应答；而一个神经元通过特定的突触联系与选 定的靶细胞通讯。神经信号传递速度很快，仅受动作电位的传播速度与突触的工作情况所限 制；而激素信号则比较慢，其限制因素是循环速度和远距离的扩散。","kp":"ch11_s6_0","kps":"相同:长距离传导;不同:突触高浓度低亲和力 vs 激素低浓度高亲和力;靶向:突触特异 vs 激素全身;速度:神经快 vs 激素慢"},{"id":"ch11_calc_2","modI":6,"q":"试分析信号转导(transduction)的几条通路的共性与特性。","a":"cAMP 信号通路，磷脂酰肌醇信号通路，受体酪氨酸激]醛}-Ras 信号通路是细胞信号转 导研究比较多的信号通路。 他们的共性与特性有：（1）多途径、多层次的细胞信号传递通路具有收敛或发散的特点； （2）细胞的信号转导既具有专一性又有作用机制的相似性；（3）信号转导过程具有信号放 大作用，其放大作用又必须受到适度的控制，表现为信号的放大作用和信号的终止作用并存， 例如，各条信号通路中蛋白质或酶的磷酸化与去磷酸化起信号的传递，级联放大以及终止等 类似作用；（4）细胞对长期的信号刺激反应能进行自身调节。","kp":"ch11_s6_1","kps":"共性:收敛/发散、专一性与相似性、放大与终止并存、自身调节"},{"id":"ch11_calc_3","modI":0,"q":"如何理解信号系统及其功能?","a":"（1）信号系统的基本组成及信号蛋白 ①通过细胞表面受体介导的信号途径的步骤组成： a．细胞通过特异性受体识别胞外信号分子； b．信号跨膜转导； c．通过胞内级联反应实现信号放大作用，并终止细胞活性改变； d．由于信号分子失活，细胞反应终止或下调。 ②相关信号蛋白： a．细胞表面受体；b．转承蛋白；c．信使蛋白；d．接头蛋白；e．放大和转导蛋白；f．传 感蛋白；g．分歧蛋白；h．整合蛋白；i．潜在基因调控蛋白。 （2）信号转导系统的功能 ①相关信号蛋白的功能如下： a．细胞表面受体：特异识别胞外信号。 b．转承蛋白：负责信息向下传递。 c．信使蛋白：携带信号从一部分传递到另外一部分。 d．接头蛋白：连接信号蛋白。 e．放大和转导蛋白：由酶和离子通道组成，介导信号级联反应。 f．传感蛋白：负责不同形式信号的转换。 g．分歧蛋白：信号从一条途径传递到另外一条途径。 h．整合蛋白：从多条通路接受信号并向下传递。 i．潜在基因调控蛋白：在表面被受体活化，迁移到细胞核刺激基因转录。 ②细胞内信号蛋白的相互作用是靠蛋白质模式结合域特异性介导的。信号蛋白具有不同的模 式结合域与另一相匹配的基序识别并结合，在细胞内组装成不同的信号转导复合物，构成细 胞内信号传递通路的基础。 ③信号转导系统的主要作用：特异性、放大作用、信号终止、整合作用。","kp":"ch11_s0_0","kps":"信号系统组成:受体、转承、信使、接头、放大转导、传感、分歧、整合、潜在基因调控蛋白;功能"},{"id":"ch11_calc_4","modI":2,"q":"概述受体酪氨酸激酶介导的信号通路的组成、特点及其主要功能。","a":"（1）受体酪氨酸激酶介导的信号通路的组成 ①受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要的受体家族， 包括 6 个亚族。 ②胞外配体是可溶性或膜结合的多肽或蛋白类激素，包括胰岛素和多种生长因子。 ③接头蛋白，如生长因子受体结合蛋白 2（GRB2）。 ④信号通路中有关的酶，如 GTP 酶活化蛋白（GAP）、与肌醇磷脂代谢有关的酶、蛋白磷 酸酯酶（SyP）以及 Src 类的非受体酪氨酸蛋白激酶等。 ⑤Ras 蛋白，具有 GTPase 活性，结合 GTP 活化，结合 GDP 失活，是一种分子开关。 ⑥鸟苷酸释放因子（GRF）。 ⑦Raf 又称 MAPKKK，是 Ser/Thr 蛋白激酶。 ⑧MAPKK 蛋白激酶和 MAPK。 （2）受体酪氨酸激酶介导的信号通路的特点 ①激活机制为受体之间的二聚体化→自磷酸化→活化自身； ②没有特定的第二信使，要求信号有特定的结构域； ③有 Ras 分子开关的参与； ④介导下游 MAPK 的激活。 （3）受体酪氨酸激酶介导的信号通路的主要功能 该信号通路是这类受体所介导的重要信号通路，具有广泛的功能，包括调节细胞的增殖与分 化，促进细胞的存活，以及细胞代谢过程中的调节与校正等。","kp":"ch11_s2_1","kps":"RTK组成(受体、配体、接头GRB2、GAP、Ras、GRF、Raf/MAPKKK、MAPKK/MAPK);特点(二聚化自磷酸化、无第二信使、结构域);功能"},{"id":"ch11_calc_5","modI":6,"q":"概述细胞信号的整合方式与控制机制。","a":"（1）细胞信号的整合方式 细胞的信号转导是多通路、多环节、多层次和高度复杂的可控过程。细胞对信号的应答反应 具有收敛或发散的特点，细胞信号的整合方式分为以下 3 种： ①信号的强度和持续的时间不同控制反应的性质。每种受体都能识别和结合各自的特异性配 体，来自各种非相关受体的信号可以在细胞内收敛成激活一个共同的效应器的信号，从而引 起细胞生理、生化反应和细胞行为的改变。另外，来自相同配体的信号又可发散激活各种不 同的效应器，导致多样化的细胞应答。 ②在不同的细胞中，相同受体因不同的胞内信号蛋白可引发不同的下游通路。细胞的信号转 导既具有专一性又有作用机制的相似性。不同的细胞中，因为转录因子组分不同，即使受体 相同而其下游的通路也是不同的。 ③形成蛋白激酶的网络整合信息。细胞各种不同的信号通路提供了信号途径本身的线性特征， 信号转导最重要的特征之一是构成复杂的信号网络系统，具有高度的非线性特点。因此细胞 需要对各种信号进行整合和精确控制，在各信号通路之间进行“交叉对话”并作出适宜的应答。 整合信号会聚其他信号通路的输入从而修正细胞对信号的反应。 （2）细胞信号的控制机制 ①细胞对外界信号适度的反应既涉及信号的有效刺激和启动，也依赖信号的解除与细胞的反 应终止； ②信号放大与信号终止并存； ③当细胞长期暴露在某种形式的刺激下时，细胞对刺激的反应将会降低； ④细胞以不同的方式对信号进行适应： a．受体没收：细胞通过配体依赖性的受体介导的内吞作用暂时减少细胞表面可利用受体的 数目，但在需要时可以重新释放得以利用。 b．受体下调：细胞通过表面自由受体数目减少和配体的清除机制导致细胞对信号敏感性下 调。 c．信号蛋白失活：受体蛋白未发生改变及影响，而体内的信号蛋白自身发生变化使得信号 通路受阻。 d．抑制性蛋白产生：受体结合配体而被激活后，在下游反应中（如对基因表达的调控）产 生抑制性蛋白并形成负反馈环从而降低或阻断信号转导途径。 e．受体失活：抑制蛋白与受体结合而使得配体无法与受体结合，从而丧失信号通路。","kp":"ch11_s6_0","kps":"整合方式:强度与时间、不同细胞相同受体不同通路、蛋白激酶网络;控制:磷酸化/去磷酸化、GTPase、自身调节"},{"id":"ch11_calc_y2","modI":2,"q":"说明RTK-Ras-MAPK通路的信号传递机制及Ras作为分子开关的调控。","a":"①生长因子与RTK胞外域结合，诱导受体二聚化和胞内酪氨酸激酶结构域自磷酸化。②接头蛋白GRB2通过SH2域结合磷酸酪氨酸，GRF（Sos）被招募到膜上，促使Ras释放GDP、结合GTP而活化。③活化的Ras-GTP激活Raf（MAPKKK）→MAPKK→MAPK级联，MAPK入核磷酸化转录因子，调控基因表达，促进细胞增殖。④Ras具GTPase活性，GAP促进GTP水解使Ras失活，回到GDP态。⑤Ras突变导致其持续活化（无法水解GTP），下游MAPK持续激活，细胞增殖失控，导致癌变。","kps":"配体→RTK二聚化自磷酸化;GRB2-GRF;Ras-GTP活化;Raf-MAPKK-MAPK级联入核;GAP使Ras失活;Ras突变持续活化致癌","type":"机制型","kp":"ch11_s2_4"},{"id":"ch11_calc_y3","modI":0,"q":"设计实验证明某信号通路中蛋白A与蛋白B存在直接相互作用。","a":"思路（任选其一或组合）：①酵母双杂交：将A与DNA结合域融合（诱饵）、B与转录激活域融合（猎物），若A、B互作则激活报告基因，菌落生长/显色。②免疫共沉淀（Co-IP）：用抗A抗体沉淀细胞裂解液，检测B是否共沉淀；反之亦然。③FRET：将A、B分别融合CFP、YFP，若两蛋白距离约10nm内则发生FRET，可活细胞检测。④GST pull-down：用GST-A融合蛋白拉下B。对照：无关蛋白对照、突变体（破坏结合位点）对照。预期：上述实验阳性且对照阴性，证明A与B直接互作。","kps":"酵母双杂交;Co-IP;FRET;GST pull-down;对照(无关蛋白/突变体);预期阳性","type":"实验设计型","kp":"ch11_s6_0"}],"appcards":[{"front":"什么是“交叉对话”（cross talking）现象（举例说明）？对此研究有何意义？","back":"（1）细胞信号传递最重要的特征之一是构成一个复杂的信号网络系统，不同的信号可 能包含有相同的中间信号分子，因而在不同信号通路之间可能产生“交叉对话”（cross talking）。 通过蛋白激酶的网络整合信息是调控复杂的细胞行为使不同信号通路之间实现 cross talking 的一种重要方式。例如，磷脂酶 C 既是 G 蛋白偶联受体信号途径的效应酶，又是 RTK 信号 途径的效应酶，并可最终激活蛋白激酶 C（PKC）。 （2）对信号传递过程中 cross talking 的研究有助于加深对信号传递过程非线性内涵的认识， 对此研究将对深入了解多基因表达调控机制、发育机制、病理过程及疾病控制产生十分重要 的影响。","mod":6,"modName":"六、 不同信号体系间的相互作用","points":""},{"front":"整联蛋白在信号传递过程中发挥什么样的作用？","back":"（1）整联蛋白是细胞表面的跨膜蛋白，由α、β两个亚基组成二聚体，其胞外段具有多 种胞外基质组分的结合位点，包括纤连蛋白、胶原和蛋白聚糖的结合位点。 （2）整联蛋白不仅介导细胞附着到细胞外基质上，更重要的是提供了一种细胞外环境调控 细胞内活性的渠道。整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞 质基质，肌醇第二信使的合成，胞内酪氨酸残基的磷酸化等。这些信号对细胞具有深远影响， 诸如细胞生长、迁移、分化乃至生存。","mod":6,"modName":"六、 不同信号体系间的相互作用","points":""},{"front":"G 蛋白偶联受体与酶联受体有什么主要不同点？","back":"蛋白偶联受体都含有 7 次跨膜的结构域，在信号转导中全部与 G 蛋白偶联；酶联受体 都属于单次跨膜受体，当该类受体与配体结合时导致受体二聚化形成同源或异源多聚化。","mod":0,"modName":"4.1.2 G-蛋白偶联受体","points":""},{"front":"简述 cAMP 途径中的 Gs 调节模型。","back":"在该途径中由刺激型 Gs 蛋白复合物偶联刺激型受体与腺苷酸环化酶。当细胞没有接受 刺激信号时，Gs 处于非活化状态，Gs 蛋白为异三聚体，α亚基与 GDP 结合，这时腺苷酸环 化酶没有活性。当刺激型的第一信使作用于刺激型的受体后，导致受体构象改变，受体复合 物与 GS 结合引起 Gs 的α亚基构象变化排斥 GDP，而与 GTP 结合被活化，三聚体 Gs 解离 出α亚基和贝塔嘎嘛亚基复合物，活化的刺激型 Gsα亚基继激活腺苷酸环化酶的活性，从而 产生第二信使 cAMP，由于 cAMP 的浓度升高，引起细胞内依赖于 cAMP 的靶酶活化，由 此将胞外信号转换成胞内信号传递、放大以致调节细胞生理反应或基因的表达等。随着 GTP 的水解使α亚基恢复原来的构象并导致与腺苷酸环化酶解离，终止腺苷酸环化酶的活化作 用,α亚基和βγ亚基重新结合，使细胞回复到静止状态。","mod":0,"modName":"4.1.2 G-蛋白偶联受体","points":""},{"front":"细胞是如何实现对信号的适应的？","back":"细胞以不同的方式产生对信号的适应：（1）逐渐降低表面受体的数目，游离受体的减 少降低了对外界信号的敏感度；（2）快速钝化受体(受体本身脱敏)，从而降低受体和配体 的亲和力，降低受体对胞外微量配体的敏感性；（3）在受体已被激活的情况下，其下游信 号蛋白发生变化，使通路受阻，这种适应是通过副反馈实现的，即强反应调节使其自身反应 关闭。","mod":6,"modName":"六、 不同信号体系间的相互作用","points":""},{"front":"Ca2+为何可以作为胞内信号进行信号转导，Ca2+的储存与释放在信号转导中有什么作用？","back":"在细胞质基质中，基态的 Ca2+浓度约为 l0-7～mol／L，很少的 Ca2+流入就可以导致胞内 溶胶 Ca2+较大程度变化。与 Na+相比，胞内 Na+浓度发生显著改变所需要的离子量要大得多。 在信号转导中，Ca2+作用极其重要，不仅可以作为第三信使参与广泛的生理活动，活化各种 Ca2+结合蛋白并引起细胞反应，而且在双信使系统本身的调节方面也非常重要。胞内 Ca2+ 浓度过高会引起细胞中毒，质膜上的钙泵和钠钙交换器将 Ca2+泵出细胞，内质网膜上的钙 泵会将高浓度的 Ca2+泵进内质网钙库。至少已经发现 4 种以上的钙结合蛋白，每个钙结合蛋 白可与 30 个左右的 Ca2+结合，钙结合蛋白的浓度可达 30～100 mg／mL，内质网作为 Ca2+ 的储存库。","mod":1,"modName":"4.1.3 G蛋白偶联受体","points":""},{"front":"比较 cAMP 信号系统与 IP3-DAG 信号系统在跨膜信号传递作用的异同。","back":"二者都是 G 蛋白偶联信号转导系统，但是第二信使不同，分别由不同的效应物生成： cAMP 由腺苷酸环化酶(AC)水解细胞中的 ATP 生成，cAMP 再与蛋白激酶 A(PKA)结合，引 发一系列细胞质反应与细胞核中的作用。在另一种信号转导系统中，效应物磷脂酶 Cq(PLC) 将膜上的磷脂酰肌醇 4，5-二磷酸分解为两个信使：二酰甘油(DAG)与 1，4，5-三磷酸肌醇(IP3)， IP3 动员胞内钙库释放 Ca2+，与钙调蛋白结合引起系列反应，而 DAG 在 Ca2+的协同下激活 蛋白激酶 C(PKC)，再引起级联反应。","mod":1,"modName":"4.1.3 G蛋白偶联受体","points":""},{"front":"肌细胞中的肌球蛋白／肌动蛋白系统的收缩是由胞内 Ca2+浓度的增加来触发的。肌细胞 具有特殊的 Ca2+释放通道-里阿诺碱(ryanodine)受体，因为它对药物中的里阿诺碱敏感。里阿 诺碱受体位于肌质网的膜中，与内质网中的 IP3 门控 Ca2+通道相反，操纵里阿诺碱受体的配 体就是 Ca2+。试讨论里阿诺碱受体通道对肌细胞收缩的重要性。","back":"Ca2+激活的 Ca2+通道产生一个正反馈回路：Ca2+释放的越多，就有更多的 Ca2+通道开放。 因此，胞质溶胶内的 Ca2+信号爆发式地被传送到整个肌细胞，从而确保所有的肌球蛋白／ 肌动蛋白纤维几乎同时收缩。","mod":4,"modName":"5.1 细胞质中低Ca2+浓度(10-7M)的控制机制","points":""},{"front":"请列举三种以上受体酪氨酸蛋白激酶介导的信号转导的级联通路。","back":"受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要受体家族。 当配体与受体相结合，激活受体的酪氨酸蛋白激酶活性，随即引起一系列磷酸化级联反应， 最终导致细胞生理和基因表达的改变。其介导的信号转导级联通路举例如下： （1）Grb2 信号通路 活化的受体识别含有 SH2 结构的靶蛋白，当 TPK 受体被激活后便借助于自身磷酸化的酪氨 酸残基与细胞内的信号分子接头蛋白 Grb2 的 SH2 结构结合，激活靶蛋白。 （2）Sos 信号通路 TPK 除含有一个隐含的 SH2 结构域外，还具有两个 SH3 结构域。它的功能是识别并结合下 游的另一个信号分子——鸟苷酸释放因子（Sos），识别部位是 Sos 中富含脯氨酸的区段。 在细胞静息状态时，Grb2 通过两个 SH3 结构与 Sos 结合形成复合物，存在于胞浆中，当 TPK 受体被激活，通过 Grb2 的 N 端 SH2 结构将 Grb2-Sos 复合物与受体相连，并将其转移至细 胞膜上募集 Sos，提高 Sos 在质膜上的局部浓度，Sos 具有核苷酸转移酶的活性，可激活下 游靶蛋白 Ras。 （3）RTK-Ras 蛋白信号通路 Ras 蛋白在 RTK 介导的信号通路中是一种关键组分。Ras 蛋白结合 GTP 时为活化态，而结 合 GDP 时为失活态。所以 Ras 蛋白具有分子开关的作用。Ras 蛋白的活化及其细胞应答是 通过配体与 RTK 的结合而诱导的。由 RTK 介导的信号通路具有广泛的功能，包括调节细胞 的增殖、分化、促进细胞存活，以及细胞代谢过程中的调节与校正作用。各种不同的胞外配 体（生长因子）与 RTK 结合，有时会引起细胞内产生多向性的效应，包括早期和晚期的基 因表达。","mod":1,"modName":"4.1.3 G蛋白偶联受体","points":""},{"front":"概述酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点和功能。","back":"（1）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点 ①受体酪氨酸蛋白激酶：是由 50 多种跨膜受体组成的超家族，其胞外配体是可溶性或膜结 合的多肽或蛋白类激素，包括胰岛素和多种生长因子。胞外配体与受体胞外区结合后，受体 发生二聚化并催化胞内区酪氨酸残基自身磷酸化，进而活化 RTK。磷酸化的酪氨酸可被一 类含有 SH2 结构域的胞内信号蛋白识别，通过级联反应向细胞内进行信号转导。 ②RTK-Ras 信号通路：配体→活化酪氨酸激酶 RTK→活化的酪氨酸激酶 RTK 结合接头蛋白 adaptor-GRF（鸟苷酸释放因子）→促进 GDP 释放→Ras（GTP 结合蛋白）活化，诱导下游 事件：Raf 丝氨酸／苏氨酸蛋白激酶（又称 MAPKKK）活化（使蛋白上的丝氨酸／苏氨酸 残基磷酸化）→活化的 Raf 结合并磷酸化另一种蛋白激酶 MAPKK，导致 MAPKK 活化 （MAPKK 是一种具双重特异的蛋白激酶，它能磷酸化 MAPK 的苏氨酸和酪氨酸残基使之 激活）→MAPK 活化→进入细胞核→其他激酶或基因调控蛋白（转录因子）的磷酸化修饰。 （2）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的功能 调节细胞的增殖与分化，促进细胞存活，以及细胞代谢过程中的调节与校正作用。","mod":2,"modName":"4.2 酶联受体","points":""},{"front":"真核细胞为何以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使？（注：细胞质中游 ＋        ＋   离 Ca2 的浓度维持在 10-7mol/L，而 Na 的浓度维持在 10-3mol/L） ＋                     ＋","back":"真核细胞之所以以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使，主要有两方面 ＋       ＋   的原因： （1）以 Ca2 为细胞内的第三信使，只需要少量的 Ca2 进入细胞，即可达到传递信号所需的 ＋                         ＋   浓度阈值，从而诱发各种细胞反应，即使在细胞外 Ca2 缺乏的情况下也容易达到； ＋   （2）若以 Na 作为第三信使，势必需要很多 Na 进入细胞内，一方面会引起细胞外 Na 的 ＋                   ＋                          ＋   缺少，需要大量 Na 进行补充；另一方面也会引起膜电位的紊乱，对细胞造成伤害。 ＋","mod":1,"modName":"4.1.3 G蛋白偶联受体","points":""},{"front":"如果说细胞信号产生于多细胞生命形式的需要，那如何解释动物与单细胞的出芽酵母之 间在细胞信号上有如此相似的机制？","back":"动物与单细胞的出芽酵母之间在细胞信号上有相似机制的原因：多细胞有机体的细胞和 细胞之间需要进行信息交流，所以有信号转导机制。单细胞的出芽酵母也要与周围的环境进 行信息交流，当细胞受到刺激后首先被细胞表面特异性受体所识别，胞外信号通过信使进入 胞内转变为胞内信号，这与多细胞生物是相似的。","mod":1,"modName":"4.1.3 G蛋白偶联受体","points":""},{"front":"G 蛋白在细胞质膜受体介导的信号传导途径中的功能及其调节。","back":"（1）G 蛋白在细胞质膜受体介导的信号传导途径中的功能 G 蛋白能够将受体接受的信号传递给效应物，产生第二信使，进行信号转导，某些 G 蛋白 还可直接调节某些离子通道的通透性。 （2）G 蛋白在细胞质膜受体介导的信号传导途径中的调节 G 蛋白由α，β，γ三个不同亚基组成。配体和受体结合，诱导 GTP 与 G 蛋白结合的 GDP 进 行交换，GTP 结合的 G 蛋白处于活化状态，激活位于信号传导途径中的下游分子如腺苷酸 环化酶。G 蛋白α亚基具有内源 GTP 酶活性，当 GTP-Gα水解为 GDP-Gα后，则处于失活状 态。 G 蛋白偶联受体介导的信号通路主要有两条：一条是 cAMP 信号通路，另有一条是磷脂酰 肌醇信号通路。前者是配体与受体结合，激活偶联的 G 蛋白，G 蛋白激活腺苷酸环化酶， 产生第二信使 cAMP，引发下游细胞事件。后者也是配体与受体结合激活偶联的 G 蛋白， 活化的 G 蛋白激活质膜上的磷脂酶 C，使 PIP2 水解为 IP3 和 DAG 两个第二信使，IP3 可动员 细胞内 Ca2 释放，DAG 可激活蛋白激酶 C（PKC），分别激发细胞的下游事件，又称“双信 ＋   使系统”。","mod":1,"modName":"4.1.3 G蛋白偶联受体","points":""},{"front":"请比较神经细胞与分泌激素的内分泌细胞信号传导的异同。并讨论两种机制的优点。","back":"（1）相同点：两类细胞产生的信号都能够长距离传导：神经元能够沿着长轴突传递动 作电位，而激素则通过循环系统到达机体各处。 （2）不同点：由于在一个突触处神经元分泌大量的神经递质，因此浓度非常高，从而神经 递质受体只需以低亲和力与神经递质结合。相反，激素在血液中被极大地稀释，它们以很低 的浓度进入循环。因此，激素受体一般以极高的亲和力与相应激素结合。 （3）靶细胞通过感受血液中激素的水平作出应答；而一个神经元通过特定的突触联系与选 定的靶细胞通讯。神经信号传递速度很快，仅受动作电位的传播速度与突触的工作情况所限 制；而激素信号则比较慢，其限制因素是循环速度和远距离的扩散。","mod":6,"modName":"六、 不同信号体系间的相互作用","points":""},{"front":"试分析信号转导(transduction)的几条通路的共性与特性。","back":"cAMP 信号通路，磷脂酰肌醇信号通路，受体酪氨酸激]醛}-Ras 信号通路是细胞信号转 导研究比较多的信号通路。 他们的共性与特性有：（1）多途径、多层次的细胞信号传递通路具有收敛或发散的特点； （2）细胞的信号转导既具有专一性又有作用机制的相似性；（3）信号转导过程具有信号放 大作用，其放大作用又必须受到适度的控制，表现为信号的放大作用和信号的终止作用并存， 例如，各条信号通路中蛋白质或酶的磷酸化与去磷酸化起信号的传递，级联放大以及终止等 类似作用；（4）细胞对长期的信号刺激反应能进行自身调节。","mod":6,"modName":"六、 不同信号体系间的相互作用","points":""},{"front":"如何理解信号系统及其功能?","back":"（1）信号系统的基本组成及信号蛋白 ①通过细胞表面受体介导的信号途径的步骤组成： a．细胞通过特异性受体识别胞外信号分子； b．信号跨膜转导； c．通过胞内级联反应实现信号放大作用，并终止细胞活性改变； d．由于信号分子失活，细胞反应终止或下调。 ②相关信号蛋白： a．细胞表面受体；b．转承蛋白；c．信使蛋白；d．接头蛋白；e．放大和转导蛋白；f．传 感蛋白；g．分歧蛋白；h．整合蛋白；i．潜在基因调控蛋白。 （2）信号转导系统的功能 ①相关信号蛋白的功能如下： a．细胞表面受体：特异识别胞外信号。 b．转承蛋白：负责信息向下传递。 c．信使蛋白：携带信号从一部分传递到另外一部分。 d．接头蛋白：连接信号蛋白。 e．放大和转导蛋白：由酶和离子通道组成，介导信号级联反应。 f．传感蛋白：负责不同形式信号的转换。 g．分歧蛋白：信号从一条途径传递到另外一条途径。 h．整合蛋白：从多条通路接受信号并向下传递。 i．潜在基因调控蛋白：在表面被受体活化，迁移到细胞核刺激基因转录。 ②细胞内信号蛋白的相互作用是靠蛋白质模式结合域特异性介导的。信号蛋白具有不同的模 式结合域与另一相匹配的基序识别并结合，在细胞内组装成不同的信号转导复合物，构成细 胞内信号传递通路的基础。 ③信号转导系统的主要作用：特异性、放大作用、信号终止、整合作用。","mod":0,"modName":"4.1.2 G-蛋白偶联受体","points":""},{"front":"概述受体酪氨酸激酶介导的信号通路的组成、特点及其主要功能。","back":"（1）受体酪氨酸激酶介导的信号通路的组成 ①受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要的受体家族， 包括 6 个亚族。 ②胞外配体是可溶性或膜结合的多肽或蛋白类激素，包括胰岛素和多种生长因子。 ③接头蛋白，如生长因子受体结合蛋白 2（GRB2）。 ④信号通路中有关的酶，如 GTP 酶活化蛋白（GAP）、与肌醇磷脂代谢有关的酶、蛋白磷 酸酯酶（SyP）以及 Src 类的非受体酪氨酸蛋白激酶等。 ⑤Ras 蛋白，具有 GTPase 活性，结合 GTP 活化，结合 GDP 失活，是一种分子开关。 ⑥鸟苷酸释放因子（GRF）。 ⑦Raf 又称 MAPKKK，是 Ser/Thr 蛋白激酶。 ⑧MAPKK 蛋白激酶和 MAPK。 （2）受体酪氨酸激酶介导的信号通路的特点 ①激活机制为受体之间的二聚体化→自磷酸化→活化自身； ②没有特定的第二信使，要求信号有特定的结构域； ③有 Ras 分子开关的参与； ④介导下游 MAPK 的激活。 （3）受体酪氨酸激酶介导的信号通路的主要功能 该信号通路是这类受体所介导的重要信号通路，具有广泛的功能，包括调节细胞的增殖与分 化，促进细胞的存活，以及细胞代谢过程中的调节与校正等。","mod":2,"modName":"4.2 酶联受体","points":""},{"front":"概述细胞信号的整合方式与控制机制。","back":"（1）细胞信号的整合方式 细胞的信号转导是多通路、多环节、多层次和高度复杂的可控过程。细胞对信号的应答反应 具有收敛或发散的特点，细胞信号的整合方式分为以下 3 种： ①信号的强度和持续的时间不同控制反应的性质。每种受体都能识别和结合各自的特异性配 体，来自各种非相关受体的信号可以在细胞内收敛成激活一个共同的效应器的信号，从而引 起细胞生理、生化反应和细胞行为的改变。另外，来自相同配体的信号又可发散激活各种不 同的效应器，导致多样化的细胞应答。 ②在不同的细胞中，相同受体因不同的胞内信号蛋白可引发不同的下游通路。细胞的信号转 导既具有专一性又有作用机制的相似性。不同的细胞中，因为转录因子组分不同，即使受体 相同而其下游的通路也是不同的。 ③形成蛋白激酶的网络整合信息。细胞各种不同的信号通路提供了信号途径本身的线性特征， 信号转导最重要的特征之一是构成复杂的信号网络系统，具有高度的非线性特点。因此细胞 需要对各种信号进行整合和精确控制，在各信号通路之间进行“交叉对话”并作出适宜的应答。 整合信号会聚其他信号通路的输入从而修正细胞对信号的反应。 （2）细胞信号的控制机制 ①细胞对外界信号适度的反应既涉及信号的有效刺激和启动，也依赖信号的解除与细胞的反 应终止； ②信号放大与信号终止并存； ③当细胞长期暴露在某种形式的刺激下时，细胞对刺激的反应将会降低； ④细胞以不同的方式对信号进行适应： a．受体没收：细胞通过配体依赖性的受体介导的内吞作用暂时减少细胞表面可利用受体的 数目，但在需要时可以重新释放得以利用。 b．受体下调：细胞通过表面自由受体数目减少和配体的清除机制导致细胞对信号敏感性下 调。 c．信号蛋白失活：受体蛋白未发生改变及影响，而体内的信号蛋白自身发生变化使得信号 通路受阻。 d．抑制性蛋白产生：受体结合配体而被激活后，在下游反应中（如对基因表达的调控）产 生抑制性蛋白并形成负反馈环从而降低或阻断信号转导途径。 e．受体失活：抑制蛋白与受体结合而使得配体无法与受体结合，从而丧失信号通路。","mod":6,"modName":"六、 不同信号体系间的相互作用","points":""}],"jyq":[{"id":"jyq_ch11_1","kind":"mcq","q":"次级溶解体内（）。","o":["A. 只含有无活性的水解酶","B. 含有被激活的水解酶","C. 含有作用底物和消化产物","D. 以上均不对"],"a":"B","src":"华中农业大学，2009年","kp":null,"e":"次级溶酶体由初级溶酶体与吞噬泡或自噬泡融合形成，内含被激活的水解酶。","oe":["A. 只含有无活性的水解酶：错误，含无活性水解酶的是初级溶酶体。","B. 含有被激活的水解酶：正确，次级溶酶体内水解酶已被激活。","C. 含有作用底物和消化产物：错误，本题考点为水解酶已被激活，故选B。","D. 以上均不对：错误，B项正确。"]},{"id":"jyq_ch11_2","kind":"short","q":"用秋水仙素处理动物细胞，细胞内质网与高尔基体分布有什么改变，为什么？","a":"秋水仙素（colchicine）是一种生物碱，能抑制有丝分裂，破坏纺锤体，使染色体停滞在分裂中期。这种由秋水仙素引起的不正常分裂，称为秋水仙素有丝分裂（C-mitosis）。在这样的有丝分裂中，染色体虽然纵裂，但细胞不分裂，不能形成两个子细胞，因而使染色体加倍。高尔基体的主要功能是将内质网合成的蛋白质进行加工、分类与包装，然后分门别类地送到细胞特定的部位或分泌到细胞外。内质网的功能主要是与脂类、糖类代谢、蛋白质的合成有关，秋水仙素处理过的动物细胞中高尔基体和内质网的分布会比较乱（引起聚集）。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch11_3","kind":"mcq","q":"下列哪些属于酶连接的受体（）。","o":["A. receptor tyrosinekinases","B. receptorSet/Thrkinase","C. receptor tyrosinephosphatase","D. 以上都是"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"酶连接受体包括受体酪氨酸激酶、受体丝/苏氨酸激酶和受体酪氨酸磷酸酶等。","oe":["A. receptor tyrosine kinases：正确，受体酪氨酸激酶属酶连接受体之一。","B. receptor Ser/Thr kinase：正确，受体丝/苏氨酸激酶也属酶连接受体。","C. receptor tyrosine phosphatase：正确，受体酪氨酸磷酸酶也属酶连接受体。","D. 以上都是：正确，A、B、C同属酶连接受体，故选D。"]},{"id":"jyq_ch11_4","kind":"short","q":"离子通道偶联受体（ino-channellinkedreceptor）","a":"具有离子通道作用的细胞质膜受体称为离子通道偶联受体，这种受体见于可兴奋细胞间的突触信号传导，产生一种电效应。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch11_5","kind":"short","q":"抑制型受体（inhibitreceptor，Ri）","a":"抑制型的受体（Ri）通过Gi抑制腺苷酸环化酶的活性，降低细胞质中cAMP的水平。已知如乙酰胆碱（M型）受体、肾上腺素（α2型）受体等，作用于抑制型受体的第一信使有前列腺素PGE，和腺苷。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch11_6","kind":"short","q":"分子开关（molecularswitches）","a":"细胞信号转导过程中，通过结合GTP与水解GDP，或者通过蛋白质磷酸化与去磷酸化而开启或关闭蛋白质的活性。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch11_7","kind":"judge","q":"细胞外配体与受体酪氨酸激酶结合，并通过单次穿膜的α螺旋的构象变化激活了细胞内催化结构域的活性。第九章细胞信号转导","a":"错","src":"中山大学，2009年","kp":null,"oe":["若选对，是以为RTK靠单个α螺旋构象变化激活；实际需二聚化与自磷酸化。","RTK激活依赖配体诱导的二聚化和胞内域交叉自磷酸化，并非单次穿膜螺旋构象变化。"]},{"id":"jyq_ch11_8","kind":"judge","q":"G蛋白耦联受体被激活后，使相应的G蛋白解离成α、β、三个亚基，以进行信号传递。","a":"错","src":"南京师范大学，2008年","kp":null,"oe":["若选对，是误以为G蛋白解离为三个亚基；其实β与γ以二聚体形式不分开。","G蛋白活化后解离为α亚基和βγ二聚体两部分，并非分成三个游离亚基，故说法错误。"]},{"id":"jyq_ch11_9","kind":"fill","q":"细胞内信号传递作为分子开关的蛋白主要有两类：一类是开关蛋白的活性由（蛋白激酶使之磷酸化）开启，蛋白磷酸酯酶使之去磷酸化而关闭。另一类主要开关蛋白有组成，结合而活化，结合而失活。","a":"GTPase;GTP；GDP。","src":"湖北大学，2008年","kp":null,"e":"细胞内另一类分子开关是GTPase（GTP结合蛋白），结合GTP时活化、结合GDP时失活。","oe":["这类开关蛋白是GTPase（GTP结合蛋白），通过结合GTP或GDP改变构象。","结合GTP时GTPase被活化，处于“开”的状态。","结合GDP时GTPase失活，处于“关”的状态。"]},{"id":"jyq_ch11_10","kind":"short","q":"活化的RTK可以结合多种细胞质中带有结构域的结合蛋白或信号蛋白。","a":"SH2。是一种核糖核蛋白复合物，它能与新合成多肽N端的信号序列结合，并引导合成的多肽及与其相连的核糖体与ER结合。【答案】SRP（信号识别颗粒）。","src":"上海交通大学，2007年","kp":null},{"id":"jyq_ch11_11","kind":"mcq","q":"G蛋白是一种（）。","o":["A. 单跨膜蛋白","B. 三次跨膜蛋白","C. 受体蛋白","D. 分子开关蛋白"],"a":"C","src":"湖北大学，2008年","kp":null,"e":"G蛋白是结合GTP/GDP的调节蛋白，通过GTP结合与水解在活性和非活性间切换，故为分子开关蛋白。","oe":["A. 单跨膜蛋白：错误，G蛋白不是单次跨膜的膜蛋白。","B. 三次跨膜蛋白：错误，跨膜次数描述与G蛋白不符。","C. 受体蛋白：错误，G蛋白与受体偶联，但本身不是受体。","D. 分子开关蛋白：正确，G蛋白结合GTP而激活、水解GDP而失活，起分子开关作用。"]},{"id":"jyq_ch11_12","kind":"short","q":"Ca是动物和植物细胞中重要的胞内信使。试述三磷酸肌醇（IP）动员细胞内Ca释放和产生相应生理功能的机制。","a":"①IP，由PIP2水解产生。它从细胞膜扩散到细胞质，与内质网膜上的IP，受体结合，动员Ca²+库（主要是内质网）中的Ca+转移到细胞质中，提高细胞质中游离Ca浓度。②信号Ca在细胞内的调节机制，是通过Ca²活化钙结合蛋白进行的。钙结合蛋白有多种，其中了解最多的是钙调素（CaM）。③CaM有4个可与Ca结合的区域。CaM与Ca结合后，引起构象改变，形成Ca+CaM复合物，被活化。活化后可激活蛋白激酶或磷酸酶，后两者可磷酸化底物蛋白，调节细胞内代谢活动。④长时间维持细胞质中Ca²+的高浓度会使细胞中毒。细胞膜和内质网上的Ca²+泵可把细胞质中的Ca²+泵到细胞外或内质网腔中，使浓度恢复到常态水平。细胞反应终止。","src":"华中农业大学，2008年","kp":null},{"id":"jyq_ch11_13","kind":"short","q":"真核细胞为何以游离状态Ca，而不是以Na*为细胞内的第三信使？（注：细胞质中游离Ca的浓度维持在10mol/L，而Na的浓度维持在10mol/L）","a":"以Ca²+为细胞内的第三信使，只需要少量的Ca²+进人细胞，即可达到传递信号所需的浓度阈值，是容易达到的；但若以Na*作为第三信使，势必要很多Na+进人细胞内球臻考硬膜论的紊乱44难以实现的。","src":"武汉大学，2006年","kp":null},{"id":"jyq_ch11_14","kind":"short","q":"细胞的信号传递的过程中有哪些正、负反馈的机制来调控信号的放大以及信号的中止？","a":"①在细胞信号传递的一系列级联反应中，必须有正、负两种相辅相成的反馈机制进行精确调控，其中分子开关起重要作用。细胞信号传递中的分子开关蛋白质有两种，一种分子开关的活性由蛋白激酶催化的磷酸化而开启，由磷酸酶催化的去磷酸化而关闭；另一类分子开关是GTP结合蛋白，结合GTP而活化，结合GDP而失而活。②信号放大的正反馈调节如受体酪氨酸激酶途径中的级联磷酸化反应，Raf磷酸化MAPKK从而将其激活，MAPKK磷酸化MAPK从而将其激活，MAPK磷酸化而激活，它可以继续磷酸化下游效应分子。在这个级联磷酸化反应中，上一步的激酶可以磷酸化很多下游底物，因此信号在这个过程中以几何级数放大。③G蛋白偶联受体介导的信号转导途径中，Ca从胞质钙库中释放出来，少量的Ca²+的释放即可激活PKC，通过第二信使也是信号放大的一个策略。④信号转导结束后，通过负反馈调节方式使转导途径中断。G蛋白偶联受体介导的途径中，cAMP为环腺苷磷酸二酯酶水解为AMP，IP和DAG亦被转化或者降解，从而将信号转导终止。另有一些负反馈调节途径如细胞膜表面受体的内吞甚至降解、膜表面受体的不敏感化等。","src":"武汉大学，2006年","kp":null},{"id":"jyq_ch11_15","kind":"short","q":"试比较G蛋白偶联受体介导的信号通路（效应蛋白、第二信使、生物学功能）。","a":"答G蛋白偶联受体是细胞表面由单条多肽经7次跨膜形成的受体，该信号通路是指配体-受体复合物与靶细胞（酶或离子通道）的作用要通过与G蛋白的偶联，在细胞内产生第二信使，从而将胞外信号跨膜传递到胞内，影响细胞的行为。根据产生第二信使的不同，它可分为cAMP信号通路和磷脂酰肌醇信号通路。cAMP信号通路的主要效应是激活靶细胞和开启基因表达，这是通过蛋白激酶A完成的。该信号途径涉及的反应链可表示为激素→G蛋白偶联受体→G蛋白→腺苷酸环化酶→cAMP→cAMP依赖的蛋白激酶A→基因调控蛋白→基因转录。第九章细胞信号转导个信号传递途径，即IP/Ca²+和DAG/PKC途径，实现细胞对外界信号的应答，因此，这一信号系统又称为双信使系统。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch11_16","kind":"short","q":"神经细胞轴突内物质的运输主要沿进行，从细胞体向轴突顶端的运输称为正向运输，主要由介导，而从轴突的顶端向细胞体的运输称为逆向运输，主要由介导。","a":"微管；驱动蛋白；动力蛋白。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch11_17","kind":"short","q":"核型分析制备染色体时需用秋水仙素，为什么？","a":"利用秋水仙素，是因为秋水仙素可以结合到α、B二聚体上，阻止微管进一步聚合，造成微管解聚。而微管是细胞进行有丝分裂时牵拉染色体、各类细胞器分别移向细胞两极，形成子细胞的动力，若在细胞分裂时用秋水仙素进行处理，可使细胞有丝分裂停滞，富集中期的细胞分裂相，使得在核型分析时可清晰的观看各时期的染色体图像。","src":"华中师范大学，2008年","kp":null},{"id":"jyq_ch11_18","kind":"fill","q":"CDK是一种周期的白依赖性的蛋白源酶，可使靶蛋白的残基磷酸化。","a":"丝氨酸或苏氨酸。","src":"南开大学，2009年","kp":null,"e":"CDK是一种周期蛋白依赖性激酶，属丝氨酸/苏氨酸蛋白激酶，可使靶蛋白的丝氨酸或苏氨酸残基磷酸化。","oe":["CDK为周期蛋白依赖性激酶，属丝氨酸/苏氨酸蛋白激酶，故靶蛋白被磷酸化的残基是丝氨酸或苏氨酸。"]},{"id":"jyq_ch11_19","kind":"short","q":"什么是原癌基因？","a":"为什么突变后会导致细胞癌变？殖的调节。但突变后成为促癌的癌基因，导致细胞癌变。原癌基因突变成癌基因，称为原癌基因的激活。有几种可能的机制使原癌基因激活：①原癌基因的编码区发生突变，改变了原有的基因结构，致使编码产物的性质发生变化，使其不再具有正常的活性；②原癌基因的调节区发生突变从而改变了结构基因表达方式，有可能大大增加表达量；③通过染色体重排，使不在一起的基因序列同原癌基因排列在一起，可能会合成新的蛋白或融合蛋白，改变了原有基因的自然活性。上述的任何一种突变，都有可能使细胞失去正常的分裂控制，从而向恶性方向转变。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch11_20","kind":"short","q":"人类许多的癌症患者（占30%）是与ras基因（编码Ras蛋白）突变有关，试着分析它的机理。","a":"Ras蛋白的活化对诱导不同类型的细胞的分化和增值是必要且充分的，Ras突变后，与GTP结合而活化，但不能将其水解为GDP，所以Ras蛋白被锁定在开启状态，所以引起赘生性细胞转化。","src":"武汉大学，2006年","kp":null},{"id":"jyq_ch11_21","kind":"short","q":"论述Ras蛋白的特性及其在肿瘤发生中的作用机制。","a":"Pase活性。③结合GTP时为活性态，结合GDP时为失活态。状态的改变起分子开关作用，需要GRF和GAP的促进。4Ras的突变，失去GTPase活性，使Ras蛋白被“锁定”在激活状态，继而使Ras介导的RTK途径一直传导，促进细胞的增殖及失控，导致肿瘤的发生。Ras蛋白从活化态转变为失活态，需要GTP酶活化蛋白（GAP）的促进，因此，GAP蛋白功能的异常，会影响Ras-GTPase活性的提高，继而促进细胞增殖和肿瘤的发生。","src":"南京师范大学，2008年","kp":null}],"outline":["GPCR 通路","酶联受体(RTK/Ras-MAPK)","第二信使(IP3/DAG/Ca²⁺)","信号网络互作","信号解除"],"outlineMap":[0,2,1,6,6]};